/* ════════════════════════════════════════════════
   SX SPORTS — MODERN UI 2026
   No borders · Fluid · GPU-accelerated
════════════════════════════════════════════════ */

/* ── TOKENS — MAGENTA × ORANGE-GOLD (SX logo palette) ── */
:root {
  --gold: #6d28ff;
  --gold-light: #c4a5ff;
  --gold-dark: #2a1459;
  --diamond: #9d6bff;
  --diamond-light: #c4a5ff;
  --diamond-dark: #1a0f33;
  --indigo: #9d6bff;         /* legacy alias → chrome silver */
  --violet: #6d28ff;         /* legacy alias → fire orange */
  --lavender: #c4a5ff;       /* legacy alias → light fire-gold */
  --ice: #c4a5ff;
  --live-red: #9d6bff;
  --white: #FFFFFF;
  --text-muted: rgba(255,255,255,0.55);
  --text-dim: rgba(255,255,255,0.32);

  /* Surfaces */
  --s0: #000000;
  --s1: rgba(255,255,255,0.03);
  --s2: rgba(255,255,255,0.055);
  --s3: rgba(255,255,255,0.08);

  /* Glows */
  --glow-indigo: rgba(157,107,255,0.35);
  --glow-magenta: rgba(157,107,255,0.32);
  --glow-gold: rgba(109,40,255,0.45);
  --glow-diamond: rgba(157,107,255,0.40);

  /* Glass */
  --glass: rgba(255,255,255,0.035);
  --glass-h: rgba(255,255,255,0.07);
  --blur: blur(20px) saturate(1.8);
  --blur-sm: blur(12px) saturate(1.5);

  /* Motion */
  --ease: cubic-bezier(0.25,0.46,0.45,0.94);
  --spring: cubic-bezier(0.34,1.3,0.64,1);

  /* Gradients */
  --grad-brand: linear-gradient(135deg,#000000 0%,#1a0f33 50%,#9d6bff 100%);
  --grad-brand-h: linear-gradient(90deg,#000000,#1a0f33,#9d6bff,#c4a5ff);
  --grad-magenta: linear-gradient(135deg,#1a0f33,#9d6bff);
  --grad-gold: linear-gradient(135deg,#c4a5ff 0%,#9d6bff 55%,#1a0f33 100%);
  --grad-gold-h: linear-gradient(90deg,#1a0f33,#9d6bff,#c4a5ff,#9d6bff,#1a0f33);
  --grad-diamond: linear-gradient(135deg,#c4a5ff 0%,#9d6bff 50%,#1a0f33 100%);

  /* Fonts */
  --font-display: 'Satoshi','Chakra Petch','Rajdhani',sans-serif;
  --font-body: 'Satoshi','Syne','Space Grotesk',sans-serif;
  --font-pricedown: 'Pricedown','Chakra Petch',sans-serif;
  --font-googlesans: 'Product Sans','Google Sans',Roboto,Arial,sans-serif;

  /* Legacy compat */
  --yellow: #c4a5ff;
  --yellow-dark: #6d28ff;
  --yellow-light: rgba(157,107,255,0.10);
  --cyan: #9d6bff;
  --cyan-dark: #1a0f33;
  --cyan-glow: rgba(157,107,255,0.50);
  --bhagva: #9d6bff;
  --bhagva-dark: #1a0f33;
  --black: #000000;
  --bg: #000000;
  --bg2: #000000;
  --bg3: #000000;
  --gray-50: #F7F7F7;
  --gray-100: #EEEEEE;
  --gray-200: #DDDDDD;
  --gray-400: rgba(255,255,255,0.55);
  --gray-600: rgba(255,255,255,0.35);
  --red-live: #9d6bff;
  --blue: #9d6bff;
  --logo-grad: var(--grad-gold);
  --logo-grad-rev: linear-gradient(135deg,#9d6bff 0%,#1a0f33 55%,#000000 100%);
  --logo-grad-h: var(--grad-gold-h);
  --purple-glow: 0 0 40px rgba(157,107,255,0.5),0 0 80px rgba(157,107,255,0.3);
}

/* ── RESET ── */
*,*::before,*::after { margin:0; padding:0; box-sizing:border-box; }
html { scroll-behavior:smooth; }
body {
  font-family: var(--font-body);
  background: #000000;
  color: var(--white);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ────────────────────────────────────────────
   PREMIUM BUTTON SYSTEM — 3D Gold / Diamond Glow
   Borderless throughout — depth comes from layered
   shadow + gradient, never from outlines.
──────────────────────────────────────────── */
.btn-3d-gold {
  position: relative; border: none; outline: none;
  background: var(--grad-gold);
  color: #FFFFFF;
  text-shadow: 0 1px 0 rgba(255,255,255,0.35);
  box-shadow:
    0 1px 0 rgba(255,255,255,0.65) inset,
    0 -3px 0 rgba(122,10,62,0.45) inset,
    0 8px 0 -2px rgba(122,10,62,0.55),
    0 14px 28px rgba(157,107,255,0.35),
    0 0 36px rgba(157,107,255,0.25);
  transform: translateY(0);
  transition: transform 0.16s var(--spring), box-shadow 0.16s var(--ease), filter 0.16s var(--ease);
}
.btn-3d-gold:hover {
  filter: brightness(1.07);
  transform: translateY(-2px);
  box-shadow:
    0 1px 0 rgba(255,255,255,0.7) inset,
    0 -3px 0 rgba(122,10,62,0.45) inset,
    0 10px 0 -2px rgba(122,10,62,0.55),
    0 18px 36px rgba(157,107,255,0.45),
    0 0 48px rgba(157,107,255,0.35);
}
.btn-3d-gold:active {
  transform: translateY(2px);
  box-shadow:
    0 1px 0 rgba(255,255,255,0.5) inset,
    0 -1px 0 rgba(122,10,62,0.4) inset,
    0 3px 0 -1px rgba(122,10,62,0.5),
    0 6px 16px rgba(157,107,255,0.30);
}

.btn-diamond-glow {
  position: relative; border: none; outline: none;
  background: rgba(157,107,255,0.10);
  color: var(--diamond-light);
  box-shadow: 0 0 0 0 transparent, 0 4px 18px rgba(157,107,255,0.10);
  transition: all 0.2s var(--ease);
}
.btn-diamond-glow:hover {
  background: rgba(157,107,255,0.18);
  color: #fff;
  box-shadow: 0 6px 28px rgba(157,107,255,0.35), 0 0 40px rgba(157,107,255,0.20);
  transform: translateY(-1px);
}

/* Ambient mesh background — GPU only */
body::before {
  content: '';
  position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background:
    radial-gradient(ellipse 70% 50% at 15% 15%, rgba(157,107,255,0.10) 0%, transparent 65%),
    radial-gradient(ellipse 55% 40% at 85% 80%, rgba(157,107,255,0.12) 0%, transparent 60%),
    radial-gradient(ellipse 35% 35% at 50% 45%, rgba(157,107,255,0.04) 0%, transparent 55%);
  will-change: transform;
  animation: meshDrift 16s ease-in-out infinite alternate;
}
/* faded watermark logo removed */
body::after { content:none !important; display:none !important; background-image:none !important; }
@keyframes meshDrift {
  0%   { transform: scale(1)    translateX(0); }
  100% { transform: scale(1.05) translateX(1%); }
}
@keyframes moviesGlow {
  0%, 100% { text-shadow: 0 0 6px rgba(157,107,255,0.55), 0 0 14px rgba(157,107,255,0.35); }
  50%      { text-shadow: 0 0 14px rgba(157,107,255,0.95), 0 0 28px rgba(157,107,255,0.65); }
}

/* Mobile GPU-compositing fix: the animated full-viewport ambient mesh layer
   (body::before), combined with will-change:transform and many stacked
   blurred/shadowed cards scrolling on top of it (Live TV grid), is what
   causes the green/blue tearing & flashing artifacts on phones. Freezing
   the mesh (no animation, no forced GPU layer) on mobile removes the
   artifact while keeping the same visual look. */
@media (max-width: 900px) {
  body::before { animation: none !important; will-change: auto !important; }
  .ch-search-box { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
}


/* ── PC Quick Nav (mirrors mobile tab bar) ── */
#pc-quicknav {
  display: flex; align-items: center; gap: 2px;
  flex-shrink: 0;
}
.pcqn-item {
  display: flex; align-items: center; gap: 5px;
  font-family: var(--font-display); font-size: 12px; font-weight: 700;
  letter-spacing: .04em; color: rgba(255,255,255,0.78);
  text-decoration: none; padding: 5px 10px; border-radius: 8px;
  white-space: nowrap; position: relative;
  transition: background .18s, color .18s;
}
.pcqn-item:hover { background: rgba(157,107,255,0.10); color: #c4a5ff; }
.pcqn-item svg { flex-shrink: 0; }
.pcqn-icon { width: 18px; height: 18px; object-fit: contain; display: block; flex-shrink: 0; }
.pcqn-dot {
  position: absolute; top: 4px; left: 8px;
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--live-red); box-shadow: 0 0 5px var(--live-red);
  animation: livePulse 1.5s ease-in-out infinite;
}
.pcqn-wt20 { color: #9d6bff !important; }
.pcqn-wt20:hover { color: #c4a5ff !important; }
@media (max-width: 900px) { #pc-quicknav { display: none; } }

/* Scrollbar */
::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: linear-gradient(180deg,#9d6bff,#9d6bff); border-radius: 8px; }

/* ────────────────────────────────────────────
   LOADER
──────────────────────────────────────────── */
#cms-loader {
  position: fixed; inset: 0; z-index: 9999;
  background: #000000;
  display: flex; align-items: center; justify-content: center;
  transition: opacity 0.6s var(--ease);
}
#cms-loader.done { opacity: 0; pointer-events: none; }

.loader-popup {
  position: relative; z-index: 2;
  display: flex; flex-direction: column; align-items: center; gap: 28px;
  animation: popIn 0.5s var(--spring) both;
}
@keyframes popIn { from { opacity:0; transform:scale(.88); } to { opacity:1; transform:none; } }

.loader-brand {
  display: flex;
  align-items: center;
  justify-content: center;
}
.loader-brand-img {
  height: 195px;
  max-width: 780px;
  width: auto;
  object-fit: contain;
  display: block;
  animation: loaderLogoPulse 1.8s ease-in-out infinite;
  filter: drop-shadow(0 0 0 rgba(157,107,255,0));
}
@keyframes loaderLogoPulse {
  0%, 100% { transform: scale(1); filter: drop-shadow(0 0 10px rgba(157,107,255,0.35)); }
  50%      { transform: scale(1.05); filter: drop-shadow(0 0 34px rgba(157,107,255,0.75)); }
}

.loader-goldbar {
  width: 160px; height: 2px; border-radius: 8px;
  background: rgba(196,165,255,0.08);
  overflow: hidden;
}
.loader-goldbar-inner {
  height: 100%; width: 32%; border-radius: 8px;
  background: linear-gradient(90deg,transparent,#1a0f33,#c4a5ff,#9d6bff,transparent);
  animation: barSlide 1.5s ease-in-out infinite;
}
@keyframes barSlide {
  0%   { transform: translateX(-220%); }
  100% { transform: translateX(520%); }
}

.loader-powered {
  display: flex; align-items: center; gap: 7px;
  text-decoration: none;
  font-family: var(--font-body); font-size: 11px; letter-spacing: 0.04em;
  color: rgba(255,255,255,0.45);
  padding: 6px 14px; border-radius: 8px;
  background: var(--s2);
  transition: all 0.2s var(--ease);
}
.loader-powered:hover { color: rgba(255,255,255,0.85); background: var(--s3); }
.loader-powered strong { color: #fff; font-weight: 700; }

/* ────────────────────────────────────────────
   PANEL-OPEN LOGO INTRO
   Brief logo splash played over Live TV / FIFA / FanCode (and News, which
   routes through Live TV) the moment their overlay opens. Sits above all
   three overlays (each z-index:1200) and removes itself once the animation
   finishes — see sxPlayPanelIntro() in the panel-open functions.
──────────────────────────────────────────── */
#sx-panel-intro {
  position: fixed; inset: 0; z-index: 1400;
  background: #000000;
  display: flex; align-items: center; justify-content: center;
  opacity: 1; transition: opacity 0.4s var(--ease);
  pointer-events: none;
}
#sx-panel-intro.fading { opacity: 0; }
#sx-panel-intro img {
  height: 120px; max-width: 70vw; width: auto; object-fit: contain;
  animation: sxPanelIntroPop 0.7s var(--spring) both;
}
@keyframes sxPanelIntroPop {
  0%   { opacity: 0; transform: scale(0.7); filter: drop-shadow(0 0 0 rgba(157,107,255,0)); }
  55%  { opacity: 1; transform: scale(1.08); filter: drop-shadow(0 0 30px rgba(157,107,255,0.65)); }
  100% { opacity: 1; transform: scale(1); filter: drop-shadow(0 0 14px rgba(157,107,255,0.4)); }
}

/* ────────────────────────────────────────────
   TICKER
──────────────────────────────────────────── */
.ticker-wrap {
  display: none; /* bar removed from markup */
}
.ticker-label {
  background: rgba(0,0,0,0.88);
  color: #c4a5ff;
  font-family: var(--font-display); font-weight: 800;
  font-size: 11px; letter-spacing: 2px;
  padding: 0 16px; height: 100%;
  display: flex; align-items: center; white-space: nowrap; flex-shrink: 0; z-index: 2;
}
.ticker-track {
  display: flex;
  animation: tickerScroll 34s linear infinite;
  align-items: center; height: 100%; padding-left: 16px;
  will-change: transform;
}
.ticker-item {
  white-space: nowrap;
  font-family: var(--font-display); font-weight: 700;
  font-size: 12px; color: rgba(255,255,255,0.90);
  padding-right: 48px;
  display: flex; align-items: center; gap: 8px;
}
@keyframes tickerScroll {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ────────────────────────────────────────────
   HEADER / NAV
──────────────────────────────────────────── */
header {
  background: rgba(0,0,0,0);
  box-shadow: none;
  position: sticky; top: 0; z-index: 1500;
  backdrop-filter: blur(0px);
  -webkit-backdrop-filter: blur(0px);
  transition: all 0.3s var(--ease);
  border-bottom: 1px solid rgba(255,255,255,0);
}
header.scrolled {
  background: rgba(0,0,0,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.header-bg-logo { display:none !important; background-image:none !important;
  background-image: none;
  position: absolute; inset: 0;
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  opacity: 0.08;
  pointer-events: none;
  z-index: 0;
}
.header-inner {
  position: relative; z-index: 1;
  max-width: 1400px; margin: 0 auto;
  display: flex; align-items: center; padding: 0 24px; height: 68px; gap: 14px;
}
.logo-wrap { display: flex; align-items: center; gap: 10px; text-decoration: none; flex-shrink: 0; }
.logo-img { height: 64px; width: auto; object-fit: contain; filter: drop-shadow(0 0 10px rgba(157,107,255,0.3)); }
.logo-fallback { font-family: var(--font-display); font-weight: 900; font-size: 26px; letter-spacing: 1px; color: var(--white); }
.logo-fallback span { color: var(--indigo); }

.nav-links-desktop { display: flex; align-items: center; gap: 2px; flex: 1; }
.nav-links-desktop a {
  font-family: var(--font-display); font-weight: 600; font-size: 14px;
  letter-spacing: 0.04em; color: rgba(255,255,255,0.80);
  text-decoration: none; padding: 6px 12px; border-radius: 8px;
  transition: all 0.18s var(--ease); white-space: nowrap;
}
.nav-links-desktop a:hover,
.nav-links-desktop a.active { color: #c4a5ff; background: rgba(157,107,255,0.10); }
.nav-movies-link {
  font-family: var(--font-googlesans) !important; font-weight: 700 !important;
  font-size: 15px !important; letter-spacing: 0.3px !important;
  color: #6d28ff !important; text-transform: uppercase;
  display: flex !important; align-items: center !important; gap: 7px !important;
  animation: moviesGlow 1.8s ease-in-out infinite;
}
.nav-movies-link .movies-logo-icon { width: 20px; height: 20px; object-fit: contain; border-radius: 8px; flex-shrink: 0; }
.nav-movies-link:hover { color: #6d28ff !important; background: rgba(157,107,255,0.10); }

.nav-live-btn { background: var(--live-red) !important; color: var(--white) !important; border-radius: 8px !important; display: flex !important; align-items: center !important; gap: 6px !important; }
.nav-live-btn:hover { background: #B0124E !important; }
.nav-watch-btn {
  background: var(--grad-gold) !important; color: #FFFFFF !important; font-weight: 800 !important;
  border-radius: 8px !important; padding: 7px 16px !important; border: none !important;
  box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset, 0 4px 16px rgba(157,107,255,0.30) !important;
  transition: all 0.18s var(--ease) !important;
}
.nav-watch-btn:hover { transform: translateY(-1px); box-shadow: 0 1px 0 rgba(255,255,255,0.6) inset, 0 8px 22px rgba(157,107,255,0.45) !important; }

.header-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

.btn-get-vip-nav {
  display: flex; align-items: center; justify-content: center; gap: 0;
  background: linear-gradient(135deg,#c4a5ff,#C21764); color: #FFFFFF;
  border: none; cursor: pointer;
  font-family: var(--font-display); font-weight: 800; font-size: 12px; letter-spacing: 0.5px;
  padding: 8px; border-radius: 50%; text-decoration: none; white-space: nowrap;
  box-shadow: 0 4px 12px rgba(196,165,255,0.35);
  transition: all 0.18s var(--ease);
}
.btn-get-vip-nav:hover { background: linear-gradient(135deg,#FFB3CF,#FF5FA0); box-shadow: 0 6px 18px rgba(196,165,255,0.50); transform: translateY(-1px); }
.btn-vip-icon { display: flex; align-items: center; flex-shrink: 0; }
.btn-vip-icon svg { width: 18px; height: 15px; display: block; }
@media(max-width:560px) {
  .btn-vip-icon svg { width: 18px; height: 15px; }
}
.btn-vip-label { display: none; }

.btn-login-nav {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  background: rgba(157,107,255,0.14); color: var(--cu-accent,#9d6bff);
  border: 1px solid rgba(157,107,255,0.35); cursor: pointer;
  font-family: var(--font-display); font-weight: 800; font-size: 12px; letter-spacing: 0.5px;
  padding: 8px 16px; border-radius: 999px; text-decoration: none; white-space: nowrap;
  transition: all 0.18s var(--ease);
}
.btn-login-nav:hover { background: rgba(157,107,255,0.24); box-shadow: 0 6px 18px rgba(157,107,255,0.35); transform: translateY(-1px); }
.btn-login-icon { display: flex; align-items: center; flex-shrink: 0; }
.btn-login-icon svg { width: 16px; height: 16px; display: block; }
.btn-login-label { display: block; }
@media(max-width:1050px) {
  .btn-login-nav { padding: 8px; border-radius: 50%; }
  .btn-login-label { display: none; }
}

.btn-yt {
  display: flex; align-items: center; justify-content: center; gap: 0;
  background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.75);
  font-family: var(--font-display); font-weight: 800; font-size: 12px; letter-spacing: 0.5px;
  padding: 8px; border-radius: 50%; text-decoration: none; white-space: nowrap;
  transition: all 0.18s var(--ease); backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,0.10);
}
.btn-yt:hover { background: rgba(255,255,255,0.15); color: #fff; }
.btn-yt svg { width: 18px; height: 18px; flex-shrink: 0; }

.btn-discord {
  display: flex; align-items: center; justify-content: center; gap: 0;
  background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.75);
  font-family: var(--font-display); font-weight: 800; font-size: 12px; letter-spacing: 0.5px;
  padding: 8px; border-radius: 50%; text-decoration: none; white-space: nowrap;
  transition: all 0.18s var(--ease); backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,0.10);
}
.btn-discord:hover { background: rgba(255,255,255,0.15); color: #fff; }
.btn-discord svg { width: 18px; height: 15px; flex-shrink: 0; display: block; overflow: visible; }
.btn-discord .btn-discord-label { display: none; }
@media(max-width:560px) {
  .btn-discord { width: 40px; height: 40px; padding: 0; flex-shrink: 0; box-sizing: border-box; }
  .btn-discord svg { width: 18px; height: 14px; }
}

.btn-telegram {
  display: flex; align-items: center; justify-content: center; gap: 0;
  background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.75);
  font-family: var(--font-display); font-weight: 800; font-size: 12px; letter-spacing: 0.5px;
  padding: 8px; border-radius: 50%; text-decoration: none; white-space: nowrap;
  transition: all 0.18s var(--ease); backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,0.10);
}
.btn-telegram:hover { background: rgba(255,255,255,0.15); color: #fff; }
.btn-telegram-icon { width: 18px; height: 18px; flex-shrink: 0; display: block; object-fit: contain; }
.btn-telegram .btn-telegram-label { display: none; }
@media(max-width:560px) {
  .btn-telegram { width: 40px; height: 40px; padding: 0; flex-shrink: 0; box-sizing: border-box; }
  .btn-telegram-icon { width: 18px; height: 18px; }
}

.hamburger {
  display: none; flex-direction: column; gap: 5px;
  cursor: pointer; padding: 6px; background: none; border: none; box-shadow: none;
  z-index: 201;
}
.hamburger span { display: block; width: 22px; height: 2px; background: #c4a5ff; border-radius: 1px; box-shadow: none; transition: all 0.28s var(--ease); }
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* Drawer */
.drawer-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.65); z-index: 8000; backdrop-filter: blur(6px); }
.drawer-overlay.open { display: block; }
.side-drawer {
  position: fixed; top: 0; left: -300px; bottom: 0; width: 280px;
  background: rgba(0,0,0,0.95);
  backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  z-index: 8010;
  transition: left 0.30s var(--ease);
  padding: 0; display: flex; flex-direction: column; overflow-y: auto;
}
.side-drawer.open { left: 0; }
.drawer-header { display: flex; align-items: center; justify-content: space-between; padding: 16px 18px; }
.drawer-logo { height: 44px; width: auto; object-fit: contain; }
.drawer-close {
  background: var(--s2); color: rgba(255,255,255,0.75); font-size: 18px;
  cursor: pointer; border-radius: 50%; width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  transition: all 0.2s var(--ease);
}
.drawer-close:hover { background: rgba(157,107,255,0.15); color: #fff; }
.drawer-nav { display: flex; flex-direction: column; padding: 8px 0; }
.drawer-nav a {
  display: flex; align-items: center; gap: 12px;
  padding: 13px 20px; color: rgba(255,255,255,0.85);
  text-decoration: none; font-family: var(--font-display);
  font-weight: 700; font-size: 15px; letter-spacing: 0.04em;
  cursor: pointer; transition: all 0.18s var(--ease);
  border-radius: 8px;
}
.drawer-nav a:hover { color: #c4a5ff; background: rgba(157,107,255,0.08); padding-left: 28px; }
.drawer-nav .drawer-live { color: #9d6bff !important; }
.drawer-nav .drawer-watch { color: #9d6bff !important; }
.drawer-nav .drawer-movies {
  font-family: var(--font-googlesans) !important; font-weight: 700 !important;
  font-size: 17px !important; letter-spacing: 0.3px !important;
  color: #6d28ff !important; text-transform: uppercase;
  animation: moviesGlow 1.8s ease-in-out infinite;
}
.drawer-nav .drawer-movies .movies-logo-icon { width: 22px; height: 22px; object-fit: contain; border-radius: 8px; flex-shrink: 0; }
.drawer-nav .drawer-vip {
  color: #FFFFFF !important;
  background: #9d6bff;
  margin: 6px 12px 4px; padding: 12px 16px;
  font-weight: 800 !important; letter-spacing: 0.03em;
}
.drawer-nav .drawer-vip:hover {
  background: #c4a5ff;
  color: #FFFFFF !important; padding-left: 16px;
}
.drawer-vip-icon { display: flex; align-items: center; flex-shrink: 0; }
.drawer-vip-icon svg { width: 18px; height: 15px; display: block; }
.drawer-nav .drawer-login {
  color: var(--cu-accent,#9d6bff) !important;
  background: rgba(157,107,255,0.10);
  border: 1px solid rgba(157,107,255,0.30);
  margin: 6px 12px 4px; padding: 12px 16px;
  font-weight: 800 !important; letter-spacing: 0.03em;
}
.drawer-nav .drawer-login:hover {
  background: rgba(157,107,255,0.18);
  padding-left: 16px;
}
.drawer-login-icon { display: flex; align-items: center; flex-shrink: 0; }
.drawer-login-icon svg { width: 16px; height: 16px; display: block; }
.drawer-divider { height: 1px; background: rgba(255,255,255,0.05); margin: 8px 16px; }

/* ────────────────────────────────────────────
   HERO — Desktop card grid
──────────────────────────────────────────── */
.hero { position: relative; background: transparent; overflow: hidden; height: auto; z-index: 100; }
.hero-cards-section { display: none !important; padding: 24px 0 16px; }
.hero-card-dots { display: none !important; }
.hero-cards-inner { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.hero-cards-track-wrap { overflow: visible; }
.hero-cards-track {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 16px;
  width: 100%;
  padding: 4px 2px 6px;
}
@media(min-width:901px) { .hero-card-dots { display: none !important; } }

.hero-slide-card {
  width: 100%; height: auto;
  border-radius: 8px; overflow: hidden; position: relative;
  cursor: pointer; background: var(--s1);
  box-shadow: 0 8px 40px rgba(0,0,0,0.65), 0 2px 0 rgba(255,255,255,0.04);
  transition: transform 0.32s var(--spring), box-shadow 0.32s var(--ease);
  display: flex; flex-direction: column; text-decoration: none;
  will-change: transform;
}
.hero-slide-card:hover {
  transform: translateY(-6px) scale(1.015);
  box-shadow: 0 24px 70px rgba(0,0,0,0.85), 0 0 36px rgba(157,107,255,0.28);
}
.hero-slide-card.active-card { box-shadow: 0 8px 40px rgba(0,0,0,0.65); }

.hsc-banner { width: 100%; aspect-ratio: 16/9; height: auto; position: relative; }
.hsc-banner-bg { position: absolute; inset: 0; background-size: cover; background-position: center; transition: transform 0.4s var(--ease); }
.hero-slide-card:hover .hsc-banner-bg { transform: scale(1.04); }
.hsc-banner-overlay { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.85) 100%); }
.hsc-badge-row { position: absolute; bottom: 10px; left: 12px; display: flex; gap: 6px; align-items: center; }
.hsc-sport-badge {
  font-family: var(--font-display); font-size: 9px; font-weight: 800;
  letter-spacing: 1.5px; text-transform: uppercase;
  background: var(--s3); color: rgba(255,255,255,0.90);
  padding: 3px 8px; border-radius: 8px;
}
.hsc-live-badge {
  font-family: var(--font-display); font-size: 9px; font-weight: 900;
  letter-spacing: 1.5px; color: #fff;
  background: var(--live-red); padding: 3px 8px; border-radius: 8px;
}

.hsc-info { flex: 1; display: flex; flex-direction: column; justify-content: space-between; padding: 14px 16px 16px; }
.hsc-title { font-family: var(--font-display); font-weight: 800; font-size: 16px; line-height: 1.3; color: var(--white); margin-bottom: 5px; }
.hsc-sub { font-family: var(--font-body); font-size: 12px; color: var(--text-muted); line-height: 1.4; }
.hsc-btn-row { display: flex; gap: 8px; margin-top: 12px; flex-wrap: wrap; }
.hsc-btn-watch {
  display: inline-flex; align-items: center; gap: 5px;
  background: var(--grad-gold); color: #FFFFFF; border: none;
  font-family: var(--font-display); font-weight: 800; font-size: 12px; letter-spacing: 0.5px;
  padding: 8px 16px; border-radius: 8px; text-decoration: none;
  box-shadow:
    0 1px 0 rgba(255,255,255,0.55) inset,
    0 -2px 0 rgba(122,10,62,0.4) inset,
    0 5px 0 -1px rgba(122,10,62,0.5),
    0 8px 22px rgba(157,107,255,0.30);
  transition: transform 0.2s var(--spring), box-shadow 0.2s var(--ease);
}
.hsc-btn-watch:hover {
  transform: translateY(-2px);
  box-shadow:
    0 1px 0 rgba(255,255,255,0.6) inset,
    0 -2px 0 rgba(122,10,62,0.4) inset,
    0 7px 0 -1px rgba(122,10,62,0.5),
    0 12px 30px rgba(157,107,255,0.45);
}
.hsc-btn-outline {
  display: inline-flex; align-items: center; gap: 5px;
  background: rgba(157,107,255,0.10); color: var(--diamond-light); border: none;
  font-family: var(--font-display); font-weight: 700; font-size: 12px;
  padding: 8px 16px; border-radius: 8px; text-decoration: none;
  transition: all 0.2s var(--ease);
}
.hsc-btn-outline:hover { background: rgba(157,107,255,0.18); color: #fff; box-shadow: 0 0 24px rgba(157,107,255,0.25); }

/* Slides — single full-width slide on every screen size, slightly larger on desktop. */
.slides-container { display: block !important; position: relative; width: 100%; aspect-ratio: 16/9; overflow: hidden; z-index: 1; }
.slide { position: absolute; inset: 0; background-color: var(--s1); opacity: 0; visibility: hidden; transition: opacity 0.5s var(--ease); z-index: 1; }
.slide.active { opacity: 1; visibility: visible; z-index: 2; }

@media(min-width:901px) {
  .slides-container {
    aspect-ratio: 16/9; height: auto;
    max-width: 640px; margin: 0 auto; padding: 24px 24px 16px;
    overflow: hidden;
  }
  .slide {
    border-radius: 8px; overflow: hidden;
    box-shadow: 0 6px 28px rgba(0,0,0,0.5);
  }
  .slide-title { font-size: 15px; }
  .slide-sub { font-size: 11px; margin-bottom: 6px; }
  .slide-content { padding: 0 14px 16px; }
  .slide-sport-badge { font-size: 8px; padding: 2px 7px; }
  .btn-slide-watch, .btn-slide-outline { font-size: 10px; padding: 6px 12px; }
}

/* ── slide-bg: full-bleed banner image inside each slide ── */
.slide-bg {
  position: absolute; inset: 0;
  background-size: cover; background-position: center; background-repeat: no-repeat;
  z-index: 0;
}

.slide-overlay { position: absolute; inset: 0; background: linear-gradient(180deg,transparent 30%,rgba(0,0,0,0.92) 100%); z-index: 1; }

/* safe-area-aware bottom padding — content compacted to fit 16:9 */
.slide-content {
  position: absolute; bottom: 0; left: 0; right: 0;
  padding: 0 16px calc(28px + env(safe-area-inset-bottom, 0px));
  z-index: 2;
}
.slide-dots {
  position: absolute; left: 0; right: 0;
  bottom: calc(8px + env(safe-area-inset-bottom, 0px));
  z-index: 3; display: flex; justify-content: center; gap: 6px;
}
.slide-sport-badge { font-family: var(--font-display); font-size: 8px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase; background: var(--s3); color: rgba(255,255,255,0.85); padding: 2px 8px; border-radius: 8px; display: inline-block; margin-bottom: 4px; }
.slide-title { font-family: var(--font-display); font-weight: 900; font-size: clamp(14px,4vw,22px); line-height: 1.15; color: var(--white); margin-bottom: 3px; }
.slide-sub { font-size: 11px; color: var(--text-muted); margin-bottom: 8px; }
.slide-btns { display: flex; gap: 8px; flex-wrap: wrap; }
.btn-slide-watch {
  display: inline-flex; align-items: center; gap: 5px;
  background: var(--grad-gold); color: #FFFFFF; border: none;
  font-family: var(--font-display); font-weight: 800; font-size: 11px;
  padding: 7px 14px; border-radius: 8px; text-decoration: none;
  box-shadow:
    0 1px 0 rgba(255,255,255,0.55) inset,
    0 -2px 0 rgba(122,10,62,0.4) inset,
    0 5px 0 -1px rgba(122,10,62,0.5),
    0 8px 24px rgba(157,107,255,0.35);
  transition: transform 0.18s var(--spring), box-shadow 0.18s var(--ease);
}
.btn-slide-watch:active { transform: translateY(2px); box-shadow: 0 2px 10px rgba(157,107,255,0.3); }
.btn-slide-outline {
  display: inline-flex; align-items: center; gap: 5px;
  background: rgba(157,107,255,0.12); color: var(--diamond-light); border: none;
  font-family: var(--font-display); font-weight: 700; font-size: 11px;
  padding: 7px 12px; border-radius: 8px; text-decoration: none;
  transition: all 0.18s var(--ease);
}
.btn-slide-outline:active { background: rgba(157,107,255,0.22); }
.hero-card-dots { display: flex; justify-content: center; gap: 7px; padding: 12px 0 4px; }
.dot { width: 7px; height: 7px; border-radius: 50%; background: rgba(255,255,255,0.25); cursor: pointer; transition: all 0.2s; }
.dot.active { background: var(--indigo); transform: scale(1.25); }

/* ────────────────────────────────────────────
   WATCH CHANNEL STRIP
──────────────────────────────────────────── */
#watch-ch-strip {
  display: flex; justify-content: center; gap: 8px; flex-wrap: wrap;
  padding: 12px 16px 6px;
}
@media(min-width:901px) {
  #watch-ch-strip { display: none !important; }
}
@media(max-width:900px) {
  /* Redundant with the bottom nav bar (Home / Live Matches / Search /
     Live TV / Favourites) — remove the whole quick-tab strip on mobile. */
  #watch-ch-strip { display: none !important; }
}
.wcs-btn {
  display: inline-flex; align-items: center; gap: 7px;
  background: rgba(var(--wcs-c),0.07);
  color: rgba(var(--wcs-c),1);
  font-family: var(--font-display); font-weight: 700; font-size: 12px; letter-spacing: 0.04em;
  padding: 7px 16px; border-radius: 8px;
  text-decoration: none; cursor: pointer;
  transition: all 0.18s var(--ease);
  white-space: nowrap; filter: brightness(1.1);
}
.wcs-btn:hover,.wcs-btn:active {
  background: rgba(var(--wcs-c),0.16);
  color: #fff;
  box-shadow: 0 0 16px rgba(var(--wcs-c),0.25);
  transform: translateY(-1px);
}
@media(max-width:600px) {
  #watch-ch-strip { display: grid; grid-template-columns: repeat(2,1fr); gap: 7px; padding: 10px 14px 4px; }
  .wcs-btn { justify-content: center; font-size: 11px; padding: 7px 10px; gap: 5px; }
  .wcs-btn svg { width: 12px; height: 12px; }
  /* Set by sxLayoutWatchStrip() on the last currently-VISIBLE button only —
     unlike a plain :nth-child(odd) selector this stays correct no matter
     how many quick-strip buttons are shown/hidden (e.g. FIFA toggling). */
  .wcs-btn.wcs-span-full { grid-column: 1/-1; }
}

/* ────────────────────────────────────────────
   MATCH OVERLAY (SMO)
──────────────────────────────────────────── */
.match-overlay-section { display: block; padding: 6px 0 4px; }
.slider-match-overlay {
  display: flex; flex-direction: column; gap: 8px; overflow-x: visible;
  padding: 4px 20px 8px;
  scrollbar-width: none;
}
.slider-match-overlay::-webkit-scrollbar { display: none; }
.smo-section {
  /* Mobile: ONE match per line (single column). Desktop widens to 3
     columns in the min-width:901px block further down. */
  display: grid; grid-template-columns: 1fr; gap: 8px;
}
.smo-section-label { grid-column: 1 / -1; }
.smo-section + .smo-section { border-top: 1px solid rgba(255,255,255,0.05); padding-top: 4px; }
.smo-section-label { display: flex; align-items: center; gap: 8px; font-family: var(--font-display); font-size: 10px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase; color: var(--lavender); padding: 2px 0; }
.smo-card {
  width: 100%; min-width: 0; max-width: 100%; flex-shrink: unset;
  background: var(--glass); backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border-radius: 8px; padding: 16px 16px 14px;
  position: relative; overflow: hidden;
  box-shadow: 0 8px 36px rgba(0,0,0,0.60), 0 1px 0 rgba(255,255,255,0.04);
  text-decoration: none; color: var(--white);
  transition: transform 0.28s var(--spring), box-shadow 0.28s var(--ease);
  display: block;
}
.smo-card:hover { transform: translateY(-3px); box-shadow: 0 16px 50px rgba(0,0,0,0.75); }
/* Unused now that date-based auto-hide was removed; kept in case you want
   a manual dismiss/fade transition for match cards later. */
.smo-card.smo-card-hide {
  opacity: 0; transform: scale(0.94);
  max-height: 0; padding-top: 0; padding-bottom: 0; margin: 0;
  border-width: 0; overflow: hidden; pointer-events: none;
  transition: opacity 0.35s ease, transform 0.35s ease,
              max-height 0.4s ease 0.1s, padding 0.4s ease 0.1s, margin 0.4s ease 0.1s;
}
.smo-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.smo-details { font-family: var(--font-display); font-weight: 700; font-size: 10px; letter-spacing: 0.5px; color: var(--text-muted); text-align: center; margin: -6px 0 12px; }
.smo-live-badge { font-family: var(--font-display); font-size: 9px; font-weight: 900; letter-spacing: 2px; background: var(--live-red); color: #fff; padding: 3px 8px; border-radius: 8px; }
.smo-upcoming-badge { font-family: var(--font-display); font-size: 9px; font-weight: 700; letter-spacing: 1.5px; background: var(--s3); color: rgba(255,255,255,0.70); padding: 3px 8px; border-radius: 8px; }
.smo-sport-label { font-family: var(--font-display); font-size: 9px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--text-muted); }
.smo-teams { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 12px; }
.smo-team { display: flex; flex-direction: column; align-items: center; gap: 6px; flex: 1; }
.smo-logo { width: 40px; height: 40px; object-fit: contain; filter: drop-shadow(0 2px 8px rgba(0,0,0,0.4)); }
.smo-name { font-family: var(--font-display); font-weight: 800; font-size: 12px; text-align: center; line-height: 1.3; color: var(--white); }
.smo-vs { font-family: var(--font-display); font-weight: 900; font-size: 18px; color: var(--live-red); flex-shrink: 0; }
.smo-footer { display: flex; align-items: center; justify-content: space-between; }
.timer-display { font-family: var(--font-display); font-weight: 900; font-size: 18px; color: var(--lavender); letter-spacing: 1px; }
.smo-btn {
  display: inline-flex; align-items: center; gap: 5px;
  background: var(--grad-gold); color: #FFFFFF; border: none;
  font-family: var(--font-display); font-weight: 800; font-size: 11px; letter-spacing: 0.5px;
  padding: 8px 14px; border-radius: 8px; text-decoration: none;
  box-shadow:
    0 1px 0 rgba(255,255,255,0.55) inset,
    0 -2px 0 rgba(122,10,62,0.4) inset,
    0 4px 0 -1px rgba(122,10,62,0.5),
    0 6px 18px rgba(157,107,255,0.30);
  transition: transform 0.2s var(--spring), box-shadow 0.2s var(--ease);
}
.smo-btn:hover { transform: translateY(-2px) scale(1.03); box-shadow: 0 1px 0 rgba(255,255,255,0.6) inset, 0 -2px 0 rgba(122,10,62,0.4) inset, 0 6px 0 -1px rgba(122,10,62,0.5), 0 10px 26px rgba(157,107,255,0.45); }

/* Home screen "nothing on today" state — the message plus a shortcut
   through to the full Matches page for whatever is coming up next. */
.smo-empty-today { display: flex; flex-direction: column; align-items: center; gap: 14px; }
.smo-next-btn {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--grad-gold); color: #FFFFFF; border: none; cursor: pointer;
  font-family: var(--font-display); font-weight: 800; font-size: 11px;
  letter-spacing: 1px; text-transform: uppercase;
  padding: 10px 18px; border-radius: 8px; text-decoration: none;
  box-shadow: 0 4px 16px rgba(157,107,255,0.32);
  transition: transform 0.2s var(--spring), box-shadow 0.2s var(--ease);
}
.smo-next-btn:hover { transform: translateY(-2px) scale(1.03); box-shadow: 0 8px 24px rgba(157,107,255,0.45); }

.smo-empty-box {
  width: 100%; text-align: center;
  background: var(--glass); backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border: 1px dashed rgba(255,255,255,0.14);
  border-radius: 8px; padding: 22px 16px;
  font-family: var(--font-display); font-weight: 800; font-size: 11px;
  letter-spacing: 2px; text-transform: uppercase; color: var(--text-muted);
}

/* ── Maintenance banner — shown in place of channels/matches when the
   SETTINGS sheet's maintain_channels / maintain_matches key is "YES".
   The reason text comes from that same row's "notes" column. ── */
.sx-maintenance-box {
  width: 100%; text-align: center; grid-column: 1 / -1;
  background: var(--glass); backdrop-filter: var(--blur);
  -webkit-backdrop-filter: var(--blur);
  border: 1px dashed rgba(255,197,61,0.35);
  border-radius: 10px; padding: 30px 18px;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
}
.sx-maintenance-icon { font-size: 26px; line-height: 1; }
.sx-maintenance-title {
  font-family: var(--font-display); font-weight: 800; font-size: 12px;
  letter-spacing: 2px; text-transform: uppercase; color: #FFC53D;
}
.sx-maintenance-note {
  font-size: 13px; color: var(--text-muted); max-width: 420px;
  line-height: 1.5;
}

/* ── ISSUE / NOTIFY banners — shown alongside content that still loads
   normally (unlike the full-replace maintenance box above). Inserted as
   a sibling right before the section's grid, so re-rendering the grid
   (search, category switch, auto-refresh) never wipes the banner. ── */
.sx-issue-banner, .sx-notify-banner {
  display: flex; align-items: flex-start; gap: 10px;
  border-radius: 8px; padding: 12px 14px; margin: 0 0 10px;
  font-size: 12.5px; line-height: 1.45;
}
.sx-issue-banner {
  background: rgba(255,180,50,0.10);
  border: 1px solid rgba(255,180,50,0.35);
  color: #FFC53D;
}
.sx-notify-banner {
  background: rgba(157,107,255,0.10);
  border: 1px solid rgba(157,107,255,0.35);
  color: #c4a5ff;
}
.sx-issue-icon, .sx-notify-icon { font-size: 16px; line-height: 1.3; flex: 0 0 auto; }
.sx-issue-text, .sx-notify-text { color: var(--text-muted); }

/* ── Match cards: 3-col grid on desktop ── */
@media(min-width:901px) {
  .slider-match-overlay {
    max-width: 1280px; margin: 0 auto;
    padding: 4px 24px 12px;
  }
  .smo-section {
    display: grid !important;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 10px;
  }
  .smo-section-label {
    grid-column: 1 / -1;
  }
}

/* ────────────────────────────────────────────
   EVENT SELECTOR TOOLBAR (dropdown + PC tabs)
   Lets the visitor pick a single "game" (event) from the MATCH CARDS
   sheet instead of scrolling through every event's cards stacked
   together. Dropdown always available; on PC the events also show as
   side-by-side pill tabs (game1) (game2) ... for one-tap switching.
──────────────────────────────────────────── */
.smo-toolbar {
  display: flex; flex-direction: column; gap: 10px;
  max-width: 1280px; margin: 0 auto; padding: 10px 20px 0;
}
/* 4-per-row grid on every screen size — categories wrap to a new line
   once there are more than 4 (ALL + LIVE NOW always occupy the first
   two slots of row 1, see smoBuildToolbar). */
.smo-game-tabs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 8px;
  width: 100%;
}
.smo-game-tab {
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--glass); backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border: 1px solid rgba(255,255,255,0.10);
  color: var(--text-muted);
  font-family: var(--font-display); font-weight: 700; font-size: 11px; letter-spacing: 0.6px; text-transform: uppercase;
  padding: 9px 8px; border-radius: 8px; cursor: pointer;
  transition: all 0.18s var(--ease);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.smo-game-tab:hover { color: var(--white); border-color: rgba(255,255,255,0.22); }
.smo-game-tab.active {
  color: #FFFFFF; background: var(--grad-gold); border-color: transparent;
  box-shadow: 0 4px 14px rgba(157,107,255,0.30);
}
/* "ALL" + "LIVE NOW" — bigger, bolder, always the first two tiles */
.smo-game-tab-big { font-size: 12.5px; font-weight: 800; padding: 11px 8px; }
.smo-game-tab-live { gap: 6px; }
.smo-game-tab-live.active {
  background: linear-gradient(135deg,#ff3b3b,#c2172c); border-color: transparent;
  box-shadow: 0 4px 14px rgba(255,59,59,0.35);
}
.smo-tab-live-dot {
  width: 7px; height: 7px; border-radius: 50%; background: currentColor;
  display: inline-block; flex-shrink: 0;
  animation: smoTabPulse 1.4s infinite;
}
@keyframes smoTabPulse { 0%,100%{opacity:1;} 50%{opacity:0.35;} }
.smo-game-select {
  background: var(--glass); backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border: 1px solid rgba(255,255,255,0.14);
  color: var(--white);
  font-family: var(--font-display); font-weight: 700; font-size: 11px; letter-spacing: 0.6px; text-transform: uppercase;
  padding: 11px 38px 11px 14px; border-radius: 8px; cursor: pointer;
  -webkit-appearance: none; -moz-appearance: none; appearance: none;
  width: 100%;
  /* keep the selected label readable instead of clipping it mid-word */
  text-overflow: ellipsis; white-space: nowrap; overflow: hidden;
}
.smo-game-select option { background: #1A0A14; color: var(--white); }

/* ── Dropdown-only selectors (PC + mobile) ──────────────────────────
   The old pill/tab strips are retired site-wide: both tiers (sport and
   tournament) are now plain <select> dropdowns with a caret, on every
   screen size. The tab containers stay in the DOM (other code still
   queries them) but are never shown. */
.smo-sel-wrap { display: flex; flex-direction: column; gap: 6px; width: 100%; }
/* Caret drawn by the wrapper, not a background image — guaranteed to show
   on every browser/appearance combo, on phones and desktop alike. */
.smo-sel-field { position: relative; display: block; width: 100%; }
.smo-sel-field::after {
  content: '▼';
  position: absolute; right: 13px; top: 50%; transform: translateY(-50%);
  font-size: 9px; line-height: 1; color: #FFB347;
  pointer-events: none;
}
.smo-sport-select + .smo-sel-caret, .smo-sel-field.is-sport::after { color: #9d6bff; }
.smo-sel-label {
  font-family: var(--font-display); font-weight: 800; font-size: 9px;
  letter-spacing: 1.6px; text-transform: uppercase; color: var(--text-muted);
}
/* Sport tier keeps its Diamond Blue accent so it still reads as the
   parent selector above the gold tournament one. */
.smo-sport-select { border-color: rgba(157,107,255,0.30); }
.smo-sport-select:focus, .smo-game-select:focus { outline: none; border-color: rgba(255,255,255,0.35); }

/* ── Where each control shows ──────────────────────────────────────
   Desktop (≥901px): horizontal selection bars — sports pills on the top
   tier, tournament tiles below — exactly as before; the dropdowns are
   hidden. Mobile/tablet (≤900px): the reverse, dropdowns only, since the
   bars don't fit a phone width. */
/* Sport tier (top): dropdown on mobile, a flat magenta nav bar on PC.
   Tournament tier (below): dropdown on EVERY screen size — unchanged. */
.smo-sport-tabs, .smo-game-tabs { display: none !important; }
.smo-sel-wrap { display: flex !important; }
@media(min-width:901px) {
  .smo-sport-toolbar .smo-sport-tabs { display: flex !important; }
  .smo-sport-toolbar .smo-sel-wrap { display: none !important; }
  .smo-toolbar { max-width: 560px; }
}
@media(max-width:900px) {
  .smo-toolbar { padding: 8px 14px 0; }
}

/* ────────────────────────────────────────────
   SPORT SELECTOR TOOLBAR — sits above the event/game toolbar.
   Reads the "sport"/"sports" column from the MATCH CARDS sheet
   (e.g. CRICKET, FOOTBALL) and groups the existing game/event
   sections one level up: pick a sport first, then the games/events
   inside it render exactly as before. Uses the Diamond Blue accent
   so it reads as the parent tier above the gold event tabs.
──────────────────────────────────────────── */
.smo-sport-toolbar {
  display: flex; flex-direction: column; gap: 10px;
  max-width: 1280px; margin: 0 auto; padding: 10px 20px 0;
}
/* Netflix-style genre bar: no box, no dividers, no border anywhere —
   just borderless tabs with generous spacing on a transparent strip.
   Only the active tab gets a solid magenta fill; everything else is
   flat text until hovered or picked. */
.smo-sport-tabs {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: none; -ms-overflow-style: none;
  gap: 10px;
  width: 100%;
  background: transparent;
  border: none;
}
.smo-sport-tabs::-webkit-scrollbar { display: none; }
.smo-sport-tab {
  display: inline-flex; align-items: center; justify-content: center;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  color: rgba(255,255,255,0.65);
  font-family: var(--font-display); font-weight: 700; font-size: 12px; letter-spacing: 0.6px; text-transform: uppercase;
  padding: 10px 18px; border-radius: 0; cursor: pointer;
  transition: background 0.15s var(--ease), color 0.15s var(--ease);
  white-space: nowrap;
}
.smo-sport-tab:hover { background: rgba(157,107,255,0.14); color: #fff; }
.smo-sport-tab.active {
  color: #fff; background: #9d6bff;
}
@media(max-width:900px) {
  .smo-sport-toolbar { padding: 10px 14px 0; }
}

/* ────────────────────────────────────────────
   SECTIONS
──────────────────────────────────────────── */
.section { padding: 36px 0; position: relative; z-index: 1; }
.section-inner { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.section-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.section-title {
  font-family: var(--font-display); font-weight: 900;
  font-size: clamp(18px,3vw,26px); color: var(--white);
  letter-spacing: 0.03em;
  display: flex; align-items: center; gap: 10px;
}
.section-title::before {
  content: '';
  display: inline-block; width: 3px; height: 22px;
  background: linear-gradient(180deg,#9d6bff,#9d6bff);
  border-radius: 8px; flex-shrink: 0;
  box-shadow: 0 0 10px rgba(157,107,255,0.35);
}
.view-all {
  font-family: var(--font-display); font-size: 12px; font-weight: 700;
  color: var(--lavender); text-decoration: none; letter-spacing: 0.06em;
  opacity: 0.75; transition: opacity 0.18s;
}
.view-all:hover { opacity: 1; }

/* ────────────────────────────────────────────
   CHANNEL CARDS
──────────────────────────────────────────── */
.channels-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(130px,1fr));
  gap: 12px;
}
.channel-card {
  background: var(--glass);
  backdrop-filter: var(--blur-sm);
  -webkit-backdrop-filter: var(--blur-sm);
  border-radius: 8px; padding: 16px 12px 14px;
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  text-decoration: none; color: var(--white);
  position: relative; overflow: hidden;
  box-shadow: 0 4px 24px rgba(0,0,0,0.55), 0 1px 0 rgba(255,255,255,0.04);
  transition: transform 0.28s var(--spring), box-shadow 0.28s var(--ease);
  cursor: pointer;
  will-change: transform;
}
.channel-card::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(180deg,rgba(255,255,255,0.055) 0%,transparent 50%);
  border-radius: inherit; pointer-events: none;
}
.channel-card:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: 0 16px 50px rgba(0,0,0,0.75), 0 0 28px rgba(157,107,255,0.25);
}
.channel-icon-wrap { width: 56px; height: 56px; display: flex; align-items: center; justify-content: center; border-radius: 8px; overflow: hidden; flex-shrink: 0; }
.channel-icon-wrap img { width: 100%; height: 100%; object-fit: contain; }

/* ════════════════════════════════════════════════════════════════════════
   LIVE CHANNELS → 16:9 FULL-SIZE CARD
   When a channel matches with LIVE CHANNELS sheet, transform to 16:9 aspect
   ratio full-size card instead of square thumbnail + text layout.
═════════════════════════════════════════════════════════════════════════ */
.channel-card.is-live-channel {
  width: 100%; height: auto; aspect-ratio: 16 / 9; padding: 0;
  flex-direction: row; align-items: stretch; gap: 0;
  grid-column: span 2;
}
.channel-card.is-live-channel .channel-icon-wrap {
  width: 100%; height: 100%; border-radius: 0; padding: 0; background: rgba(0,0,0,0.3);
}
.channel-card.is-live-channel .channel-icon-wrap img {
  width: 100%; height: 100%; object-fit: cover;
}
.channel-card.is-live-channel .channel-name,
.channel-card.is-live-channel .channel-status,
.channel-card.is-live-channel .channel-prog,
.channel-card.is-live-channel .quality-badge {
  display: none;
}
.channel-card.is-live-channel::before {
  background: linear-gradient(135deg,rgba(157,107,255,0.25) 0%,rgba(0,0,0,0.4) 100%);
}
.channel-card.is-live-channel:hover {
  transform: scale(1.04);
  box-shadow: 0 16px 50px rgba(0,0,0,0.85), 0 0 40px rgba(157,107,255,0.35);
}
.channel-icon-wrap.white-bg { background: rgba(255,255,255,0.90); }
.channel-icon-wrap.nobg { background: transparent; }
.channel-icon-wrap.black-bg { background: rgba(0,0,0,0.88); }
.channel-name { font-family: var(--font-display); font-weight: 800; font-size: 11px; text-align: center; line-height: 1.3; word-break: break-word; }
.channel-status { display: flex; align-items: center; gap: 5px; font-family: var(--font-display); font-size: 10px; font-weight: 700; }
.channel-prog { font-size: 10px; color: var(--text-muted); text-align: center; line-height: 1.3; }
.quality-badge { font-family: var(--font-display); font-size: 8px; font-weight: 800; letter-spacing: 1px; padding: 2px 6px; border-radius: 8px; background: var(--s3); color: var(--lavender); }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--live-red); box-shadow: 0 0 8px var(--live-red); animation: livePulse 1.5s ease-in-out infinite; flex-shrink: 0; }
.live-dot-r { width: 6px; height: 6px; border-radius: 50%; background: var(--live-red); box-shadow: 0 0 8px rgba(109,40,255,0.85); animation: livePulse 1.5s ease-in-out infinite; flex-shrink: 0; }
@keyframes livePulse { 0%,100% { opacity:1; transform:scale(1); } 50% { opacity:0.5; transform:scale(1.5); } }
@keyframes pulseDot { 0%,100% { opacity:1; } 50% { opacity:0.45; } }

/* ────────────────────────────────────────────
   CHANNEL BROWSER
──────────────────────────────────────────── */
#ch-browser { margin-top: 24px; }
.ch-browser-hdr { margin-bottom: 14px; }
.ch-browser-title { font-family: var(--font-display); font-weight: 900; font-size: 16px; color: var(--white); letter-spacing: 0.03em; }
.ch-search-wrap { margin-bottom: 14px; }
.ch-search-box {
  display: flex; align-items: center; gap: 10px;
  background: var(--glass); backdrop-filter: var(--blur-sm);
  border-radius: 8px; padding: 10px 14px;
  max-width: 380px;
}
.ch-search-box input {
  background: none; outline: none; font-family: var(--font-body);
  font-size: 14px; color: var(--white); flex: 1; min-width: 0;
}
.ch-search-box input::placeholder { color: var(--text-muted); }
.ch-tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.ch-tab {
  display: inline-flex; align-items: center; gap: 7px;
  background: var(--s1);
  color: rgba(255,255,255,0.65);
  font-family: var(--font-display); font-weight: 700; font-size: 12px;
  padding: 8px 14px; border-radius: 8px; cursor: pointer;
  transition: all 0.18s var(--ease);
  user-select: none;
}
.ch-tab:hover { background: var(--s2); color: var(--white); }
.ch-tab.active { background: rgba(157,107,255,0.15); color: #c4a5ff; }

.ch-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(110px,1fr));
  gap: 10px;
}
/* Channel browser cards */
.ch-card {
  background: var(--glass);
  border-radius: 8px; padding: 14px 10px 12px;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  text-decoration: none; color: var(--white); cursor: pointer;
  position: relative; overflow: hidden;
  transition: transform 0.25s var(--spring), box-shadow 0.25s var(--ease);
}
.ch-card:hover { transform: translateY(-3px); box-shadow: 0 12px 40px rgba(0,0,0,0.6); }
.ch-card.star-card { background: linear-gradient(145deg,rgba(109,40,255,0.14),rgba(74,10,44,0.16)); }
.ch-card.sony-card { background: linear-gradient(145deg,rgba(109,40,255,0.14),rgba(60,8,48,0.16)); }
.ch-card.fox-card { background: linear-gradient(145deg,rgba(157,107,255,0.12),rgba(35,35,35,0.16)); }
.ch-card.fancode-card { background: linear-gradient(145deg,rgba(157,107,255,0.12),rgba(90,10,52,0.16)); }
.ch-card.unite8-card { background: linear-gradient(145deg,rgba(109,40,255,0.10),rgba(80,10,44,0.14)); }
.ch-card.intl-card { background: linear-gradient(145deg,rgba(109,40,255,0.12),rgba(60,8,43,0.16)); }
.ch-card.zee-card { background: linear-gradient(145deg,rgba(157,107,255,0.12),rgba(120,15,10,0.16)); }
.ch-card.news-card { background: linear-gradient(145deg,rgba(70,20,44,0.14),rgba(20,6,13,0.18)); }
.ch-card.fifa-card { background: linear-gradient(145deg,rgba(196,165,255,0.12),rgba(90,10,52,0.16)); }
.ch-logo-wrap { width: 48px; height: 48px; border-radius: 8px; display: flex; align-items: center; justify-content: center; overflow: hidden; }
.ch-logo-wrap img { width: 100%; height: 100%; object-fit: contain; }
.ch-logo-wrap.nobg { background: transparent; }
.ch-logo-wrap.white-sq { background: rgba(255,255,255,0.88); }
.ch-logo-wrap.black-sq { background: rgba(0,0,0,0.85); }
.ch-name { font-family: var(--font-display); font-weight: 800; font-size: 10px; text-align: center; line-height: 1.3; }
.ch-live-dot { position: absolute; top: 8px; right: 8px; width: 6px; height: 6px; border-radius: 50%; background: var(--live-red); box-shadow: 0 0 6px var(--live-red); animation: livePulse 1.5s ease-in-out infinite; }
.ch-hd { position: absolute; top: 7px; left: 7px; font-family: var(--font-display); font-size: 7px; font-weight: 900; letter-spacing: 1px; background: var(--s3); color: var(--lavender); padding: 1px 4px; border-radius: 8px; }
.ch-premium-badge { position: absolute; top: 7px; left: 7px; width: 14px; height: 14px; }
.ch-logo-ph { font-family: var(--font-display); font-size: 10px; font-weight: 900; color: var(--lavender); }
.ch-no-results { grid-column: 1/-1; padding: 40px; text-align: center; color: var(--text-muted); font-family: var(--font-display); font-size: 14px; }

/* ────────────────────────────────────────────
   FIXTURES
──────────────────────────────────────────── */
.fixtures-grid { display: grid; grid-template-columns: repeat(auto-fill,minmax(280px,1fr)); gap: 16px; }

/* ── New "TimStreams-style" homepage match preview cards ── */
.sx-matches-hdr{ display:flex; align-items:center; gap:12px; margin-bottom:20px; }
.sx-matches-hdr-bar{ width:4px; height:26px; background:linear-gradient(180deg,#F5A623,#6d28ff); border-radius:4px; flex-shrink:0; }
.sx-matches-hdr-text{
  font-family: var(--cu-font,var(--font-display)); font-weight:900;
  font-size: clamp(20px,3vw,28px); letter-spacing:0.02em; color:#fff; text-transform:uppercase;
}
.fx2-card{
  display:flex; flex-direction:column; text-decoration:none;
  background: rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.08);
  border-radius: 10px; overflow:hidden; transition: transform 0.18s var(--ease), border-color 0.18s var(--ease);
}
.fx2-card:hover{ transform: translateY(-4px); border-color: rgba(255,255,255,0.2); }
.fx2-thumb{ position:relative; width:100%; aspect-ratio:16/9; background:#0a0a0a; overflow:hidden; }
.fx2-thumb-img{ width:100%; height:100%; object-fit:cover; display:block; }
.fx2-thumb-teams{
  width:100%; height:100%; display:flex; align-items:center; justify-content:center; gap:14px;
  background: radial-gradient(circle at 50% 40%, rgba(109,40,255,0.18), rgba(0,0,0,0.9));
}
.fx2-thumb-team img{ width:46px; height:46px; object-fit:contain; }
.fx2-thumb-vs{ font-family:var(--font-display); font-weight:900; font-size:14px; color:rgba(255,255,255,0.55); }
.fx2-badge{
  position:absolute; top:10px; left:10px; display:inline-flex; align-items:center; gap:5px;
  background: rgba(0,0,0,0.75); border-radius:6px; padding:4px 9px;
  font-family: var(--cu-font,var(--font-display)); font-weight:800; font-size:10px; letter-spacing:0.05em; color:#fff;
}
.fx2-badge-live .fx2-live-dot{
  width:6px; height:6px; border-radius:50%; background:var(--live-red,#6d28ff); display:inline-block;
  animation: liveDotPulse 1.4s ease-in-out infinite;
}
@keyframes liveDotPulse{ 0%,100%{opacity:1;} 50%{opacity:0.35;} }
.fx2-body{ padding:14px 16px 16px; display:flex; flex-direction:column; gap:8px; }
.fx2-title-row{ display:flex; align-items:flex-start; justify-content:space-between; gap:8px; }
.fx2-title{ font-family:var(--font-display); font-weight:700; font-size:14px; color:#fff; line-height:1.3; }
.fx2-free{
  flex-shrink:0; background: rgba(255,255,255,0.1); color:#fff;
  font-family: var(--cu-font,var(--font-display)); font-weight:800; font-size:9px; letter-spacing:0.04em;
  padding:3px 8px; border-radius:5px;
}
.fx2-meta{ display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.fx2-tag{
  background: rgba(255,255,255,0.06); color: rgba(255,255,255,0.65);
  font-family: var(--cu-font,var(--font-display)); font-size:10.5px; font-weight:600;
  padding:3px 8px; border-radius:5px;
}
.fx2-date{ font-family: var(--cu-font,var(--font-display)); font-size:11px; color: rgba(255,255,255,0.45); }

.fx2-viewall{
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:12px;
  background: rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.08); border-radius:10px;
  min-height:180px; text-decoration:none; transition: background 0.18s var(--ease), border-color 0.18s var(--ease);
}
.fx2-viewall:hover{ background: rgba(255,255,255,0.05); border-color: rgba(255,255,255,0.2); }
.fx2-viewall-arrow{
  width:52px; height:52px; border-radius:50%; background: rgba(255,255,255,0.08);
  display:flex; align-items:center; justify-content:center; font-size:22px; color:#fff;
}
.fx2-viewall-text{
  font-family: var(--cu-font,var(--font-display)); font-weight:800; font-size:12px;
  letter-spacing:0.08em; color: rgba(255,255,255,0.75); text-transform:uppercase;
}

/* ── Home screen "Live Channels" preview: compact one-line list rows on
   mobile (thumb + name + badge), instead of the tall vertical
   match-style poster cards used for Matches/Movies previews. ── */
@media(max-width:560px){
  #channelsPreviewGrid{ display:flex !important; flex-direction:column; gap:8px; }
  #channelsPreviewGrid .fx2-card{ flex-direction:row !important; align-items:center; border-radius:8px; }
  #channelsPreviewGrid .fx2-thumb{ width:84px !important; flex:0 0 84px !important; aspect-ratio:16/9; }
  #channelsPreviewGrid .fx2-body{ padding:8px 12px 8px 0 !important; gap:4px !important; flex:1; min-width:0; }
  #channelsPreviewGrid .fx2-title{ font-size:13px !important; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
