/* ── Live TV home preview: categories list + View All Channels ── */
.chp-grid{ display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:16px; }

/* Category card (new layout) */
.cat-card-preview{
  background: linear-gradient(135deg, rgba(157,107,255,0.12), rgba(157,107,255,0.05));
  border:1.5px solid rgba(157,107,255,0.25); border-radius:12px;
  overflow:hidden; cursor:pointer; display:flex; flex-direction:column;
  justify-content:center; align-items:center; padding:28px 20px;
  min-height:140px;
  transition: all 0.22s var(--spring);
  position:relative;
}
.cat-card-preview::before{
  content:''; position:absolute; inset:0;
  background: linear-gradient(180deg, rgba(255,255,255,0.05) 0%, transparent 100%);
  pointer-events:none; border-radius:inherit;
}
.cat-card-preview:hover{
  transform: translateY(-6px) scale(1.02);
  border-color: rgba(157,107,255,0.45);
