.fixture-badge { display: inline-flex; align-items: center; gap: 5px; background: var(--s2); border-radius: 8px; padding: 3px 10px; font-family: var(--font-display); font-size: 9px; font-weight: 800; color: var(--lavender); letter-spacing: 1px; text-transform: uppercase; }
.fixture-badge-live { background: rgba(109,40,255,0.12); color: var(--live-red); }
.fixture-body { padding: 16px; }
