.team-logo-wrap img { width: 100%; height: 100%; object-fit: contain; }
.fixture-team-name { font-family: var(--font-display); font-weight: 700; font-size: 12px; color: rgba(255,255,255,0.85); text-align: center; line-height: 1.3; }
.fixture-vs { font-family: var(--font-display); font-weight: 900; font-size: 20px; color: var(--live-red); flex-shrink: 0; }
