/* ────────────────────────────────────────────
   OTT PLATFORMS (FanCode, Prime, Willow) - FLAT STYLE
──────────────────────────────────────────── */
#ott-section {
  background: linear-gradient(180deg,#000000,#000000) !important;
  border-top: 1px solid rgba(255,255,255,0.06);
  position: relative;
}
#ott-section::before {
  display: none;
}
#ott-section .section-inner {
  position: relative;
  z-index: 1;
}

.ott-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }
.ott-card {
  border-radius: 8px; padding: 0;
  display: flex; flex-direction: column; align-items: center; gap: 0;
  text-align: center; position: relative; overflow: hidden;
  background: var(--glass); backdrop-filter: var(--blur-sm);
  box-shadow: 0 8px 36px rgba(0,0,0,0.60), 0 1px 0 rgba(255,255,255,0.04);
  transition: all 0.28s var(--spring);
  text-decoration: none; cursor: pointer;
  border: 1px solid rgba(255,255,255,0.06);
}
.ott-card::before { display: none; }
.ott-card::after { display: none; }
.ott-card:hover { 
  transform: translateY(-4px); 
  box-shadow: 0 20px 60px rgba(0,0,0,0.80);
  border-color: rgba(255,255,255,0.12);
}

.ott-logo-wrap { 
  width: 100%; padding: 20px 16px 16px;
  display: flex; align-items: center; justify-content: center; 
  overflow: hidden; 
  background: rgba(255,255,255,0.025);
  border-bottom: 1px solid rgba(255,255,255,0.04);
}
.ott-logo-wrap img { width: 70px; height: 70px; object-fit: contain; }
.ott-name { 
  font-family: var(--font-display); font-weight: 800; font-size: 15px; 
  letter-spacing: 0.03em; color: var(--white); position: relative; z-index: 2;
  text-transform: uppercase; padding: 12px 12px 0;
}
.ott-desc { 
  font-size: 11px; color: rgba(255,255,255,0.65); line-height: 1.4; 
  position: relative; z-index: 2; padding: 0 12px 12px;
}
.ott-btn {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--cu-accent,#9d6bff); color: #FFFFFF; border: none;
  font-family: var(--font-display); font-weight: 800; font-size: 11px;
  padding: 8px 16px; border-radius: 6px; text-decoration: none;
  transition: background-color 0.2s ease, transform 0.15s ease;
  box-shadow: none;
  position: relative; z-index: 2;
  cursor: pointer; margin: 0 12px 12px;
  width: calc(100% - 24px);
}
.ott-btn:hover:not(:disabled) { 
  transform: translateY(-1px); 
  background: #c4a5ff;
  box-shadow: none;
}
.ott-btn:disabled {
  opacity: 0.8;
  cursor: not-allowed;
}

/* ────────────────────────────────────────────
   BROADCAST
──────────────────────────────────────────── */
.broadcast-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.broadcast-card {
  border-radius: 8px; padding: 26px 22px;
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  text-align: center; position: relative; overflow: hidden;
  background: var(--glass); backdrop-filter: var(--blur-sm);
  box-shadow: 0 8px 36px rgba(0,0,0,0.55), 0 1px 0 rgba(255,255,255,0.04);
  transition: transform 0.28s var(--spring), box-shadow 0.28s var(--ease);
}
.broadcast-card::before { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg,rgba(255,255,255,0.05) 0%,transparent 45%); border-radius: inherit; pointer-events: none; }
.broadcast-card:hover { transform: translateY(-4px); box-shadow: 0 20px 60px rgba(0,0,0,0.75); }
.bc-featured::after { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px; background: linear-gradient(90deg,#9d6bff,#c4a5ff,#9d6bff); border-radius: 8px; }
.broadcast-logo-wrap { width: 76px; height: 76px; border-radius: 8px; display: flex; align-items: center; justify-content: center; overflow: hidden; background: var(--s2); }
.broadcast-logo-wrap img { width: 76px; height: 76px; object-fit: contain; }
.broadcast-name { font-family: var(--font-display); font-weight: 800; font-size: 17px; letter-spacing: 0.05em; color: var(--white); }
.broadcast-quality { display: inline-block; padding: 3px 14px; border-radius: 8px; font-family: var(--font-display); font-size: 10px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; background: var(--s3); color: var(--lavender); }
.broadcast-desc { font-size: 13px; color: var(--text-muted); line-height: 1.6; }
.partner-logos-row { display: grid; grid-template-columns: repeat(5,1fr); gap: 10px; width: 100%; margin-bottom: 6px; }
.partner-logo-item { display: flex; flex-direction: column; align-items: center; gap: 4px; }
.partner-logo-box { width: 48px; height: 48px; border-radius: 8px; display: flex; align-items: center; justify-content: center; overflow: hidden; background: var(--s2); }
.partner-logo-box img { width: 48px; height: 48px; object-fit: contain; }
.partner-logo-label { font-size: 8px; color: var(--text-muted); letter-spacing: 0.05em; text-align: center; text-transform: uppercase; }
.bc-watch-btn {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--grad-gold); color: #FFFFFF; border: none;
  font-family: var(--font-display); font-weight: 800; font-size: 13px;
  padding: 10px 22px; border-radius: 8px; text-decoration: none;
  transition: transform 0.22s var(--spring), box-shadow 0.22s var(--ease);
  box-shadow:
    0 1px 0 rgba(255,255,255,0.55) inset,
    0 -2px 0 rgba(122,10,62,0.4) inset,
    0 5px 0 -1px rgba(122,10,62,0.5),
