}
.bc-watch-btn:hover { transform: translateY(-2px) scale(1.02); box-shadow: 0 1px 0 rgba(255,255,255,0.6) inset, 0 -2px 0 rgba(122,10,62,0.4) inset, 0 7px 0 -1px rgba(122,10,62,0.5), 0 14px 36px rgba(157,107,255,0.50); }

/* ────────────────────────────────────────────
   SCHEDULE
──────────────────────────────────────────── */
.schedule-section { padding: 36px 0; }
.schedule-tabs { display: flex; gap: 0; margin-bottom: 18px; position: relative; }
.schedule-tabs::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 1px; background: rgba(255,255,255,0.06); }
.tab {
  font-family: var(--font-display); font-weight: 700; font-size: 13px;
  letter-spacing: 0.5px; padding: 10px 20px; cursor: pointer;
  color: var(--text-muted); position: relative; background: none;
  transition: all 0.18s var(--ease); white-space: nowrap;
}
.tab::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 2px; background: var(--indigo); border-radius: 8px; transform: scaleX(0); transition: transform 0.22s var(--ease); }
.tab.active { color: var(--white); }
.tab.active::after { transform: scaleX(1); }
.tab:hover { color: rgba(255,255,255,0.85); }

.match-row {
  display: grid; grid-template-columns: 100px 1fr auto 1fr 140px;
  align-items: center; gap: 12px; padding: 13px 10px;
  border-radius: 8px;
  transition: background 0.18s var(--ease);
}
.match-row:hover { background: var(--s1); }
.match-time { font-family: var(--font-display); font-weight: 700; font-size: 13px; color: var(--white); line-height: 1.4; }
.match-sport-badge { font-family: var(--font-display); font-weight: 800; font-size: 8px; letter-spacing: 1px; padding: 2px 6px; border-radius: 8px; text-transform: uppercase; display: inline-block; margin-top: 3px; background: rgba(252,252,252,0.12); color: #d7dce1; }
.team-home,.team-away { text-align: center; }
.team-name { font-family: var(--font-display); font-weight: 700; font-size: 14px; color: var(--white); }
.team-logo-s { width: 34px; height: 34px; object-fit: contain; display: block; margin: 0 auto 3px; }
.vs-box { font-family: var(--font-display); font-weight: 900; font-size: 17px; color: var(--live-red); text-align: center; }
.match-channel { font-family: var(--font-display); font-weight: 700; font-size: 11px; color: var(--text-muted); text-align: right; }
.match-live-tag { display: inline-block; background: var(--live-red); color: var(--white); font-family: var(--font-display); font-weight: 800; font-size: 9px; letter-spacing: 1.5px; padding: 3px 7px; border-radius: 8px; margin-bottom: 4px; }

/* ────────────────────────────────────────────
   CTA
──────────────────────────────────────────── */
.cta-box {
  background: var(--glass); backdrop-filter: var(--blur);
  border-radius: 8px; padding: 56px 40px; text-align: center;
  position: relative; overflow: hidden;
  box-shadow: 0 8px 50px rgba(0,0,0,0.60), 0 0 90px rgba(157,107,255,0.10), 0 0 60px rgba(157,107,255,0.08);
}
.cta-box::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse 55% 80% at 50% 50%,rgba(157,107,255,0.07) 0%,transparent 70%); pointer-events: none; }
.cta-title {
  font-family: var(--font-display); font-weight: 900; font-size: clamp(28px,5vw,52px);
  background: var(--grad-gold-h); background-size: 200% auto;
  -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
  text-transform: uppercase; letter-spacing: 1px; margin-bottom: 12px; position: relative;
}
.cta-sub { font-size: 15px; color: var(--text-muted); max-width: 500px; margin: 0 auto 28px; line-height: 1.6; position: relative; }
.cta-btns { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; position: relative; }
.cta-btn-primary {
  background: var(--grad-gold); color: #FFFFFF; border: none;
  font-family: var(--font-display); font-weight: 900; font-size: 17px;
  padding: 14px 36px; border-radius: 8px; text-decoration: none; letter-spacing: 0.5px;
  transition: transform 0.22s var(--spring), box-shadow 0.22s var(--ease);
  box-shadow:
    0 1px 0 rgba(255,255,255,0.6) inset,
    0 -3px 0 rgba(122,10,62,0.45) inset,
    0 6px 0 -1px rgba(122,10,62,0.55),
    0 10px 30px rgba(157,107,255,0.40);
}
.cta-btn-primary:hover {
  transform: translateY(-3px) scale(1.02);
  box-shadow:
    0 1px 0 rgba(255,255,255,0.65) inset,
    0 -3px 0 rgba(122,10,62,0.45) inset,
    0 9px 0 -1px rgba(122,10,62,0.55),
    0 16px 44px rgba(157,107,255,0.55);
}
.cta-btn-outline {
  background: rgba(157,107,255,0.10); color: var(--white); border: none;
  font-family: var(--font-display); font-weight: 700; font-size: 15px;
  padding: 14px 28px; border-radius: 8px; text-decoration: none;
  transition: all 0.18s var(--ease);
}
.cta-btn-outline:hover { background: rgba(157,107,255,0.18); color: var(--diamond-light); box-shadow: 0 0 30px rgba(157,107,255,0.30); }

/* ────────────────────────────────────────────
   DISCORD CARD
──────────────────────────────────────────── */
.discord-section { padding: 0 0 8px; }
.discord-card {
  position: relative; overflow: hidden;
  display: flex; align-items: center; gap: 24px;
  background: linear-gradient(135deg,rgba(157,107,255,0.12) 0%,rgba(0,0,0,0.85) 60%);
  backdrop-filter: var(--blur); -webkit-backdrop-filter: var(--blur);
  border-radius: 8px; padding: 28px 32px;
  box-shadow: 0 8px 40px rgba(0,0,0,0.55), 0 0 50px rgba(157,107,255,0.08);
}
.discord-card::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse 45% 90% at 0% 50%,rgba(157,107,255,0.20) 0%,transparent 60%); pointer-events: none; }
.discord-card::after { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg,rgba(255,255,255,0.05) 0%,transparent 40%); pointer-events: none; border-radius: inherit; }
.discord-icon-badge { position: relative; flex-shrink: 0; width: 62px; height: 62px; border-radius: 8px; background: linear-gradient(150deg,#9d6bff,#9d6bff); display: flex; align-items: center; justify-content: center; box-shadow: 0 0 24px rgba(157,107,255,0.5); }
.discord-icon-badge svg { width: 34px; height: 26px; }
.discord-online-dot { position: absolute; bottom: -3px; right: -3px; width: 14px; height: 14px; border-radius: 50%; background: #9d6bff; border: 2px solid var(--s0); animation: pulseDot 1.8s infinite; }
.discord-body { flex: 1; min-width: 0; position: relative; z-index: 1; }
.discord-title { font-family: var(--font-display); font-weight: 800; font-size: 19px; color: var(--white); letter-spacing: 0.2px; margin-bottom: 5px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.discord-title .live-pill { font-size: 9px; font-weight: 700; background: rgba(157,107,255,0.12); color: #9d6bff; border-radius: 8px; padding: 3px 9px; letter-spacing: 0.5px; }
