.whatsapp-online-dot { position: absolute; bottom: -3px; right: -3px; width: 14px; height: 14px; border-radius: 50%; background: #6d28ff; border: 2px solid var(--s0); animation: pulseDot 1.8s infinite; }
.whatsapp-body { flex: 1; min-width: 0; position: relative; z-index: 1; }
.whatsapp-title { font-family: var(--font-display); font-weight: 800; font-size: 19px; color: var(--white); letter-spacing: 0.2px; margin-bottom: 5px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.whatsapp-title .live-pill { font-size: 9px; font-weight: 700; background: rgba(109,40,255,0.12); color: #6d28ff; border-radius: 8px; padding: 3px 9px; letter-spacing: 0.5px; }
.whatsapp-sub { font-size: 13px; color: var(--text-muted); line-height: 1.55; margin-bottom: 12px; max-width: 520px; }
.whatsapp-tags { display: flex; gap: 7px; flex-wrap: wrap; }
.whatsapp-tag { font-family: var(--font-display); font-size: 10px; font-weight: 600; color: rgba(255,255,255,0.80); background: var(--s2); border-radius: 8px; padding: 5px 12px; display: flex; align-items: center; gap: 5px; }
.whatsapp-join-btn {
  flex-shrink: 0; position: relative; z-index: 1;
