.whatsapp-join-btn:hover { transform: translateY(-2px); box-shadow: 0 10px 30px rgba(109,40,255,0.6); background: #FFE6EF; }

@media(max-width:900px) {
  .whatsapp-card { flex-direction: column; text-align: center; padding: 26px 20px; gap: 14px; }
  .whatsapp-body { text-align: center; }
