/* ────────────────────────────────────────────
   SOCIAL BAR
──────────────────────────────────────────── */
.social-bar { padding: 18px 0; }
.social-inner { max-width: 1400px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.social-text { font-family: var(--font-display); font-weight: 700; font-size: 15px; color: var(--white); }
