/* ────────────────────────────────────────────
   FOOTER
──────────────────────────────────────────── */
footer { background: rgba(0,0,0,0.94); padding: 48px 0 24px; }
.footer-inner { max-width: 1400px; margin: 0 auto; padding: 0 24px; }
