.footer-wordmark { font-family: var(--font-display); font-weight: 900; font-size: 20px; color: var(--white); letter-spacing: 0.01em; }
.footer-brand p { font-size: 13px; color: var(--text-muted); line-height: 1.6; max-width: 420px; text-align: center; }
.footer-nav { display: flex; gap: 28px; flex-wrap: wrap; justify-content: center; list-style: none; padding: 0; margin: 2px 0 0; }
.footer-nav a { font-size: 11.5px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-muted); text-decoration: none; transition: color 0.15s; }
