/* ────────────────────────────────────────────
   WATCH MODAL
──────────────────────────────────────────── */
.watch-overlay { display: none; position: fixed; inset: 0; z-index: 1000; background: rgba(0,0,0,0.80); backdrop-filter: blur(10px); align-items: center; justify-content: center; padding: 16px; }
.watch-overlay.open { display: flex; animation: fadeUp 0.22s var(--ease); }
@keyframes fadeUp { from { opacity:0; } to { opacity:1; } }
.watch-modal {
  background: rgba(0,0,0,0.97); backdrop-filter: var(--blur);
  border-radius: 8px; width: 100%; max-width: 600px; max-height: 90vh; overflow-y: auto;
  position: relative; box-shadow: 0 0 80px rgba(157,107,255,0.15), 0 32px 90px rgba(0,0,0,0.90);
  animation: modalIn 0.28s var(--spring) both;
}
@keyframes modalIn { from { opacity:0; transform:translateY(22px) scale(.96); } to { opacity:1; transform:none; } }
.watch-modal-header { padding: 20px 24px 16px; display: flex; align-items: center; justify-content: space-between; background: rgba(255,255,255,0.02); border-radius: 8px; position: sticky; top: 0; z-index: 2; backdrop-filter: var(--blur-sm); }
.watch-modal-title { font-family: var(--font-display); font-size: 20px; font-weight: 900; letter-spacing: 0.06em; color: var(--lavender); display: flex; align-items: center; gap: 10px; }
.watch-modal-close { width: 34px; height: 34px; border-radius: 50%; background: var(--s2); color: rgba(255,255,255,0.75); font-size: 16px; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.2s; }
.watch-modal-close:hover { background: rgba(255,50,50,0.18); color: #fff; }
.watch-modal-body { padding: 20px 24px 24px; }
.watch-lang-section { margin-bottom: 18px; }
.watch-lang-label { font-family: var(--font-body); font-size: 9px; letter-spacing: 0.3em; text-transform: uppercase; color: rgba(196,165,255,0.5); margin-bottom: 10px; display: flex; align-items: center; gap: 8px; }
.watch-lang-label::after { content: ''; flex: 1; height: 1px; background: rgba(196,165,255,0.08); }
.watch-channels { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.watch-channel-btn {
  display: flex; align-items: center; gap: 11px; padding: 12px 14px;
  border-radius: 8px; background: var(--s1); text-decoration: none; color: var(--white);
  transition: all 0.2s var(--ease); cursor: pointer;
}
.watch-channel-btn:hover { background: var(--s2); transform: translateY(-1px); }
.watch-sx-featured {
  display: flex; align-items: center; gap: 14px; padding: 14px 16px;
  border-radius: 8px; background: rgba(157,107,255,0.08); text-decoration: none; color: var(--white);
  transition: all 0.2s var(--ease); margin-bottom: 14px; position: relative; overflow: hidden;
}
.watch-sx-featured::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 1.5px; background: linear-gradient(90deg,#9d6bff,#c4a5ff); }
.watch-sx-featured:hover { background: rgba(157,107,255,0.13); box-shadow: 0 0 24px rgba(157,107,255,0.18); }
.watch-ch-logo { width: 40px; height: 40px; border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; overflow: hidden; }
.watch-ch-logo img { width: 36px; height: 36px; object-fit: contain; }
.watch-ch-info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.watch-ch-name { font-weight: 700; font-size: 13px; letter-spacing: 0.02em; }
.watch-ch-lang { font-size: 10px; color: rgba(196,165,255,0.55); letter-spacing: 0.1em; text-transform: uppercase; }
.watch-ch-arrow { margin-left: auto; color: rgba(157,107,255,0.45); font-size: 12px; flex-shrink: 0; }
.watch-modal-footer { padding: 12px 24px; text-align: center; font-size: 10px; color: var(--text-dim); letter-spacing: 0.06em; }
.badge-free { background: rgba(0,220,80,0.10); border-radius: 8px; padding: 1px 6px; font-size: 9px; letter-spacing: 0.1em; color: #00dc50; font-weight: 700; }
.badge-nologin { background: rgba(196,165,255,0.08); border-radius: 8px; padding: 1px 6px; font-size: 9px; letter-spacing: 0.08em; color: rgba(196,165,255,0.65); font-weight: 700; }
.badge-4k { background: rgba(196,165,255,0.08); border-radius: 8px; padding: 1px 6px; font-size: 9px; letter-spacing: 0.08em; color: var(--lavender); font-weight: 700; }
.badge-unavail { background: rgba(109,40,255,0.08); border-radius: 8px; padding: 1px 6px; font-size: 9px; letter-spacing: 0.08em; color: #FF6FA0; font-weight: 700; }
.unavail-card { opacity: 0.5; pointer-events: none; }

/* ────────────────────────────────────────────
   MATCH WATCH SCREEN — full-screen takeover shown for every match
   card that has at least one working btn_url (btn_url, btn_url_2..5
   in the MATCH CARDS sheet tab). Left = match details, right =
   list of watch/server links (just one entry if only btn_url is set).
   Style: flat, solid surfaces (no blur/translucent glass), corners
   softened to a subtle curve, ribbon accent line + motion for polish.
──────────────────────────────────────────── */
.mws-overlay {
  display: none; position: fixed; inset: 0; z-index: 10000;
  background: #000000;
}
.mws-overlay.open { display: block; animation: fadeUp 0.25s var(--ease); }
.mws-bg {
  position: absolute; inset: 0; z-index: 0;
  background-size: cover; background-position: center;
  filter: blur(42px) saturate(1.15) brightness(0.4);
  transform: scale(1.15);
}
.mws-bg::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(160deg, rgba(157,107,255,0.06), transparent 45%),
              rgba(0,0,0,0.78);
}
.mws-close {
  position: absolute; top: 18px; right: 18px; z-index: 5;
  width: 38px; height: 38px; border-radius: 8px;
  background: #000000;
  border: 1px solid rgba(255,255,255,0.14); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; cursor: pointer; transition: all 0.2s var(--ease);
}
.mws-close:hover { background: #FF5FA0; border-color: #FF5FA0; }
.mws-wrap {
  position: relative; z-index: 1;
  display: flex; align-items: stretch; justify-content: center;
  width: 100%; height: 100%; padding: 60px 60px;
  gap: 2px;
}
.mws-panel {
  background: #000000;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 8px;
  box-shadow: none;
}
.mws-left {
  flex: 0 0 38%; max-width: 460px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 40px 32px; gap: 18px; text-align: center;
  background: linear-gradient(165deg, #000000 0%, #000000 65%);
  border-top-right-radius: 0; border-bottom-right-radius: 0;
}
.mws-right {
  flex: 1 1 auto; min-width: 0;
  display: flex; flex-direction: column; padding: 0;
  border-top-left-radius: 0; border-bottom-left-radius: 0;
}
.mws-right-head { padding: 26px 32px 16px; border-bottom: 1px solid rgba(255,255,255,0.08); flex-shrink: 0; }
.mws-right-eyebrow { font-family: var(--font-body); font-size: 10px; letter-spacing: 0.28em; text-transform: uppercase; color: rgba(196,165,255,0.7); margin-bottom: 6px; font-weight: 700; }
.mws-right-title { font-family: var(--font-display); font-size: 20px; font-weight: 900; letter-spacing: 0.03em; color: var(--white); }
.mws-right-body { flex: 1 1 auto; overflow-y: auto; padding: 20px 32px 32px; display: flex; flex-direction: column; gap: 10px; }

.mws-badge-row { display: flex; justify-content: center; align-items: center; }
/* Server selector (match watch screen) LIVE badge — solid red, centered
   on both axes, no blinking dot. Scoped to .mws-badge-row (more specific
   than the site-wide .smo-live-badge rules) so every OTHER live badge
   on the site keeps its own look; only this one screen's badge changes. */
.mws-badge-row .smo-live-badge {
  display: inline-flex !important; align-items: center !important; justify-content: center !important;
  /* var(--live-red) is actually magenta site-wide — use a genuine red here
     (same red the "Live Now" tab already uses) so this badge reads as red. */
  background: #ff3b3b !important; color: #fff !important;
  box-shadow: none !important;
}
.mws-badge-row .smo-live-badge .live-dot-r { display: none !important; }
.mws-details { font-family: var(--font-body); font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: rgba(196,165,255,0.75); font-weight: 700; }
.mws-date { font-size: 11px; letter-spacing: 0.08em; color: rgba(255,255,255,0.45); }
.mws-teams { display: flex; align-items: center; justify-content: center; gap: 22px; width: 100%; }
.mws-team { display: flex; flex-direction: column; align-items: center; gap: 8px; flex: 1; min-width: 0; }
.mws-team-logo { width: 68px; height: 68px; object-fit: contain; }
.mws-team-code { font-family: var(--font-display); font-size: 18px; font-weight: 900; letter-spacing: 0.03em; color: var(--white); }
.mws-team-full { font-size: 10.5px; color: rgba(255,255,255,0.5); text-align: center; max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mws-vs { font-family: var(--font-display); font-size: 13px; font-weight: 800; color: rgba(255,255,255,0.35); flex-shrink: 0; }
.mws-timer-label { font-size: 9px; letter-spacing: 0.24em; text-transform: uppercase; color: rgba(255,255,255,0.4); }
.mws-timer { font-family: var(--font-display); font-size: 22px; font-weight: 800; color: var(--cu-accent,#9d6bff); letter-spacing: 0.02em; }

/* ── Server rows: only a server whose name actually MATCHES a LIVE
   CHANNELS entry gets a real thumbnail — a 16:9 box on one side of the
   row holding that channel's logo (cropped to fill, not stretched full
   width). Anything that doesn't match a live channel (keyword-guessed
   logo, or no logo at all) stays as the small square icon / number
   chip — the plain "normal" row look. ── */
.mws-server-btn {
  display: flex; align-items: center; gap: 14px; width: 100%; padding: 14px 16px;
  border: 1px solid rgba(255,255,255,0.09); border-left: 3px solid rgba(157,107,255,0.35); border-radius: 8px;
  background: #000000;
  text-decoration: none; color: var(--white);
  transition: all 0.18s var(--ease); cursor: pointer; font-family: var(--font-body); text-align: left; box-shadow: none;
  position: relative; overflow: hidden;
}
.mws-server-btn:hover { background: #111111; border-color: rgba(157,107,255,0.35); border-left-color: var(--cu-accent,#9d6bff); }
.mws-server-num {
  width: 32px; height: 32px; flex-shrink: 0; border-radius: 8px;
  background: var(--cu-accent,#9d6bff);
  color: #000000; font-family: var(--font-display); font-size: 13px; font-weight: 800;
  display: flex; align-items: center; justify-content: center;
}
.mws-server-icon {
  width: 32px; height: 32px; flex-shrink: 0; border-radius: 8px;
  object-fit: contain; background: rgba(255,255,255,0.06);
  padding: 3px; box-sizing: border-box;
}
/* 16:9 thumbnail — only for logos matched against LIVE CHANNELS. */
.mws-server-thumb {
  position: relative; flex-shrink: 0; overflow: hidden; border-radius: 6px;
  width: 96px; aspect-ratio: 16 / 9;
  background: rgba(255,255,255,0.06);
}
.mws-server-thumb img { width: 100%; height: 100%; object-fit: cover; object-position: center; display: block; transition: transform 0.3s var(--ease); }
.mws-server-btn:hover .mws-server-thumb img { transform: scale(1.08); }
@media (max-width: 480px) { .mws-server-thumb { width: 78px; } }
.mws-server-btn-fcx { padding: 14px 18px; border-left-color: #F5C518; min-height: 76px; }
.mws-server-btn-fcx:hover { border-left-color: #F5C518; }
.mws-server-logo-lg {
  height: 56px; width: auto; max-width: 150px; flex-shrink: 0;
  object-fit: contain; background: transparent; padding: 0; border-radius: 0;
}
.mws-server-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.mws-server-label { font-size: 14px; font-weight: 700; letter-spacing: 0.02em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mws-server-sub { font-size: 10px; color: rgba(255,255,255,0.4); letter-spacing: 0.04em; }
.mws-server-app-note { display: block; margin-top: 3px; font-size: 9px; font-weight: 800; letter-spacing: 0.05em; text-transform: uppercase; color: #F5C518; }
/* Visual enhancement for auto-connected servers from LIVE CHANNELS */
.mws-server-btn:has(.mws-auto-badge) {
  border-left-color: #c4a5ff;
}
.mws-server-btn:has(.mws-auto-badge):hover {
  border-left-color: #9d6bff;
  box-shadow: 0 0 0 1px rgba(196,165,255, 0.4);
}
/* Shown at the top of the server list when the match hasn't kicked off
   yet — deliberately red so it reads as a "not yet" warning rather than
   another playable option. */
/* Before kickoff EVERY server in the list (not just FanCode) is locked:
   greyed out, non-playable, and it shakes with a red flash when tapped. */
.mws-server-btn.mws-server-locked {
  filter: grayscale(1);
  opacity: 0.42;
  cursor: not-allowed;
  border-color: rgba(255,255,255,0.06) !important;
  box-shadow: none !important;
}
.mws-server-btn.mws-server-locked:hover { transform: none !important; }
.mws-server-btn.mws-server-locked .mws-server-play { color: #ff5b5b; }
.mws-server-btn.mws-shake {
  animation: mwsShake 0.42s cubic-bezier(.36,.07,.19,.97) both;
  border-color: rgba(255,59,59,0.75) !important;
  box-shadow: 0 0 0 1px rgba(255,59,59,0.45), 0 0 22px rgba(255,59,59,0.35) !important;
}
@keyframes mwsShake {
  10%,90% { transform: translateX(-2px); }
  20%,80% { transform: translateX(4px); }
  30%,50%,70% { transform: translateX(-7px); }
  40%,60% { transform: translateX(7px); }
}
/* Red toast that pops up over the watch screen on a locked tap. */
.mws-lock-toast {
  position: fixed; left: 50%; bottom: 40px; transform: translateX(-50%) translateY(16px);
  z-index: 2147483000;
  display: flex; align-items: center; gap: 9px;
  max-width: min(440px, calc(100vw - 32px));
  background: linear-gradient(135deg,#c2172c,#8d0f1f);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 10px; padding: 13px 18px;
  font-family: var(--font-display); font-weight: 800; font-size: 12px;
  letter-spacing: 0.5px; color: #fff; text-transform: uppercase;
  box-shadow: 0 12px 40px rgba(0,0,0,0.6), 0 0 26px rgba(255,59,59,0.35);
  opacity: 0; pointer-events: none;
  transition: opacity 0.22s var(--ease), transform 0.22s var(--spring);
}
.mws-lock-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
@media(max-width:600px){ .mws-lock-toast { bottom: 24px; font-size: 11px; padding: 11px 14px; } }

.mws-notlive {
  display: block; width: 100%;
  background: rgba(255,59,59,0.12);
  border: 1px solid rgba(255,59,59,0.45);
  border-left: 3px solid #ff3b3b;
  border-radius: 8px; padding: 12px 14px;
  font-family: var(--font-display); font-weight: 800; font-size: 12px;
  letter-spacing: 0.6px; color: #ff5b5b; text-transform: uppercase;
  margin-bottom: 4px;
}
/* ════════════════════════════════════════════════════════════════════════
   AUTO-CONNECTED BADGE — shown when a server was auto-linked from LIVE TV
═════════════════════════════════════════════════════════════════════════ */
.mws-auto-badge {
  display: inline-block;
  background: linear-gradient(135deg, #c4a5ff 0%, #9d6bff 100%);
  color: #fff;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 3px 8px;
  margin-left: 8px;
  border-radius: 4px;
  vertical-align: middle;
  box-shadow: 0 2px 8px rgba(196,165,255, 0.35);
}
.mws-server-play { font-size: 13px; color: rgba(157,107,255,0.6); flex-shrink: 0; display: flex; align-items: center; }
.mws-play-disc {
  display: flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; border-radius: 50%; flex-shrink: 0;
  background: rgba(157,107,255,0.14); color: #9d6bff;
  transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}
.mws-play-disc svg { margin-left: 1px; } /* optical centering for the triangle */
.mws-server-btn:hover .mws-play-disc { background: #9d6bff; color: #fff; transform: scale(1.06); }

/* "More Live Matches" strip — banner-fallback (FanCode, no team logos)
   watch screens only. Sits under the server list, scrolls sideways. */
.mws-more-live { margin-top: 6px; padding-top: 14px; border-top: 1px solid rgba(255,255,255,0.08); }
.mws-more-title { font-family: var(--font-display); font-size: 10px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(255,255,255,0.45); margin-bottom: 10px; }
.mws-more-row { display: flex; gap: 10px; overflow-x: auto; -webkit-overflow-scrolling: touch; scrollbar-width: none; -ms-overflow-style: none; padding-bottom: 2px; }
.mws-more-row::-webkit-scrollbar { display: none; }
.mws-more-card { flex: 0 0 auto; width: 128px; display: flex; flex-direction: column; gap: 6px; background: transparent; border: none; padding: 0; cursor: pointer; text-align: left; }
.mws-more-thumb { position: relative; width: 128px; height: 72px; border-radius: 6px; overflow: hidden; background: #000000; border: 1px solid rgba(255,255,255,0.08); }
.mws-more-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.2s ease; }
.mws-more-card:hover .mws-more-thumb img { transform: scale(1.05); }
.mws-more-live-badge { position: absolute; top: 5px; left: 5px; display: flex; align-items: center; gap: 4px; background: #ff3b3b; color: #fff; font-size: 8.5px; font-weight: 800; letter-spacing: 0.5px; padding: 2px 6px; border-radius: 3px; }
.mws-more-live-badge .live-dot-r { width: 4px; height: 4px; background: #fff; box-shadow: none; }
.mws-more-name { font-size: 11px; font-weight: 600; color: rgba(255,255,255,0.75); line-height: 1.35; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.mws-more-card:hover .mws-more-name { color: #fff; }
@media (max-width: 900px) {
  .mws-more-card, .mws-more-thumb { width: 108px; }
  .mws-more-thumb { height: 62px; }
}

/* Sidebar ad placeholder — sits under the More Live Matches strip (or on
   its own when there are no other live matches). Flat, dashed border so
   it visually reads as a slot, not a real match/server row. */
.mws-ad-box {
  margin-top: 14px;
  border: 1px dashed rgba(157,107,255,0.35);
  border-radius: 6px;
  padding: 18px 14px;
  text-align: center;
  background: rgba(157,107,255,0.05);
}
.mws-ad-title { font-family: var(--font-display); font-size: 12px; font-weight: 800; letter-spacing: 0.14em; color: rgba(157,107,255,0.75); margin-bottom: 6px; }
.mws-ad-contact { font-size: 11px; color: rgba(255,255,255,0.4); }
.mws-ad-handle { color: #9d6bff; font-weight: 700; }

/* Full-screen banner fallback (no team logos available) — the banner
   image fills the whole left panel edge-to-edge, with a bottom scrim so
   the badge/details/date/timer stack stays readable sitting over it. */
.mws-left.mws-left-banner {
  padding: 0; justify-content: flex-end; align-items: stretch;
  position: relative; overflow: hidden;
  min-height: 100%;
  background: #000000;
}
.mws-fallback-banner {
  position: absolute; inset: 0; width: 100%; height: 100%;
  object-fit: cover; z-index: 0;
}
.mws-fallback-scrim {
  position: absolute; inset: 0; z-index: 1;
  background: linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.35) 45%, rgba(0,0,0,0.94) 100%);
}
.mws-fallback-content {
  position: relative; z-index: 2;
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  text-align: center; padding: 32px 28px;
}

/* ── Ribbon accent + motion ──────────────────────────────────────────
   A slow-flowing gradient "ribbon" line runs along the top edge of
   each panel (cyan → lavender → gold → cyan, endlessly cycling),
   plus a living, drifting background and a staggered fade/slide-in
   for the panels, badge, teams and each server row so the screen
   doesn't just snap into place. */
.mws-bg { animation: mwsBgDrift 20s ease-in-out infinite alternate; }
@keyframes mwsBgDrift {
  from { transform: scale(1.15) translate(0, 0); }
  to   { transform: scale(1.24) translate(-1.5%, 1.5%); }
}

.mws-panel { position: relative; overflow: hidden; }
.mws-panel::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; z-index: 3;
  background: linear-gradient(90deg, #9d6bff, #c4a5ff, #c4a5ff, #9d6bff);
  background-size: 300% 100%;
  animation: mwsRibbonFlow 7s linear infinite;
}
@keyframes mwsRibbonFlow {
  0%   { background-position: 0% 50%; }
  100% { background-position: 300% 50%; }
}

.mws-close { animation: mwsFadeDown 0.45s var(--ease) both; }
@keyframes mwsFadeDown { from { opacity: 0; transform: translateY(-10px); } to { opacity: 1; transform: none; } }

.mws-left  { animation: mwsSlideInLeft  0.5s var(--spring) both; }
.mws-right { animation: mwsSlideInRight 0.5s var(--spring) both; animation-delay: 0.06s; }
@keyframes mwsSlideInLeft  { from { opacity: 0; transform: translateX(-26px); } to { opacity: 1; transform: none; } }
@keyframes mwsSlideInRight { from { opacity: 0; transform: translateX(26px);  } to { opacity: 1; transform: none; } }

.mws-badge-row, .mws-details, .mws-date, .mws-teams, [id^="mws-timerwrap"], .mws-right-head {
  animation: mwsFadeUp 0.5s var(--ease) both;
}
@keyframes mwsFadeUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
.mws-badge-row  { animation-delay: 0.12s; }
.mws-details    { animation-delay: 0.17s; }
.mws-date       { animation-delay: 0.20s; }
.mws-teams      { animation-delay: 0.25s; }
[id^="mws-timerwrap"] { animation-delay: 0.32s; }
.mws-right-head { animation-delay: 0.18s; }

.mws-team-logo { transition: transform 0.3s var(--ease); }
.mws-teams:hover .mws-team-logo { transform: scale(1.06); }

/* Server rows fan in one after another, then get a soft ribbon-light
   sweep across them on hover — like a glint of silk catching light. */
.mws-server-btn { position: relative; overflow: hidden; animation: mwsFadeUp 0.4s var(--ease) both; }
.mws-server-btn:nth-of-type(1) { animation-delay: 0.20s; }
.mws-server-btn:nth-of-type(2) { animation-delay: 0.27s; }
.mws-server-btn:nth-of-type(3) { animation-delay: 0.34s; }
.mws-server-btn:nth-of-type(4) { animation-delay: 0.41s; }
.mws-server-btn:nth-of-type(5) { animation-delay: 0.48s; }
.mws-server-btn::after {
  content: ''; position: absolute; top: 0; left: -60%; width: 35%; height: 100%;
  background: linear-gradient(120deg, transparent, rgba(255,255,255,0.16), transparent);
  transform: skewX(-20deg); pointer-events: none;
  transition: left 0.55s ease;
}
.mws-server-btn:hover::after { left: 130%; }
.mws-server-btn:hover { transform: translateX(2px); }
.mws-server-num { transition: transform 0.25s var(--spring); }
.mws-server-btn:hover .mws-server-num { transform: scale(1.1); }

/* ── Raw HLS/DASH stream cards (channel rows + match servers) — orange
   accent instead of the usual magenta, plus a VLC badge, to mark links
   that open externally in VLC/MX Player rather than our own player. ── */
.epg-vlc-icon, .mws-vlc-icon {
  width: 18px; height: 18px; object-fit: contain; vertical-align: middle;
  filter: drop-shadow(0 0 2px rgba(0,0,0,0.4));
}
.epg-row.epg-row-raw-stream {
  border-left: 3px solid #FF7A1A;
  background: linear-gradient(90deg, rgba(255,122,26,0.14), rgba(255,122,26,0.02));
}
.epg-row.epg-row-raw-stream:hover { border-color: rgba(255,122,26,0.5); }
.epg-row.epg-row-raw-stream .epg-badges { display: flex; align-items: center; gap: 6px; }
.mws-server-btn.mws-server-btn-raw {
  border-left-color: #FF7A1A !important;
  background: linear-gradient(90deg, rgba(255,122,26,0.14), rgba(255,122,26,0.02));
}
.mws-server-btn.mws-server-btn-raw:hover { border-color: rgba(255,122,26,0.5); border-left-color: #FF7A1A; }
.mws-server-btn.mws-server-btn-raw .mws-server-label { display: flex; align-items: center; gap: 6px; }

/* ── VLC / MX Player external-play popup ── */
.sx-vlc-popup-overlay {
  position: fixed; inset: 0; z-index: 10050; display: none;
  align-items: center; justify-content: center;
  background: rgba(0,0,0,0.72); backdrop-filter: blur(4px);
}
.sx-vlc-popup-overlay.open { display: flex; }
.sx-vlc-popup-box {
  position: relative; width: min(340px, 88vw); text-align: center;
  background: #000000; border: 1px solid rgba(255,122,26,0.35);
  border-radius: 16px; padding: 28px 22px 22px; box-shadow: 0 20px 60px rgba(0,0,0,0.6);
}
.sx-vlc-popup-close {
  position: absolute; top: 10px; right: 12px; background: none; border: none;
  color: rgba(255,255,255,0.55); font-size: 22px; line-height: 1; cursor: pointer;
}
.sx-vlc-popup-close:hover { color: #fff; }
.sx-vlc-popup-icon { width: 56px; height: 56px; margin: 0 auto 12px; display: block; }
.sx-vlc-popup-title { font-family: var(--cu-font); font-weight: 800; font-size: 15px; color: #fff; margin-bottom: 4px; }
.sx-vlc-popup-sub { font-family: var(--cu-font); font-size: 12px; color: rgba(255,255,255,0.6); margin-bottom: 18px; }
.sx-vlc-popup-actions { display: flex; flex-direction: column; gap: 10px; }
.sx-vlc-popup-btn {
  display: block; width: 100%; padding: 11px 14px; border-radius: 10px;
  font-family: var(--cu-font); font-weight: 700; font-size: 13px; text-decoration: none;
  border: 1px solid rgba(255,255,255,0.14); color: #fff; background: rgba(255,255,255,0.06);
  cursor: pointer; box-sizing: border-box;
}
.sx-vlc-popup-btn-primary { background: #FF7A1A; border-color: #FF7A1A; color: #111; }
.sx-vlc-popup-btn:hover { filter: brightness(1.08); }

@media (max-width: 900px) {
  .mws-left, .mws-right { animation: mwsFadeUp 0.4s var(--ease) both; }
}

@media (max-width: 900px) {
  .mws-wrap { flex-direction: column; padding: 0; height: 100%; }
  .mws-left { flex: 0 0 auto; max-width: none; width: 100%; padding: 54px 24px 24px; border-right: none; border-bottom: 1px solid rgba(255,255,255,0.10); }
  .mws-right { flex: 1 1 auto; border-left: none; min-height: 0; }
  .mws-right-head { padding: 18px 20px 14px; }
  .mws-right-body { padding: 14px 20px 24px; }
  .mws-team-logo { width: 52px; height: 52px; }
  .mws-teams { gap: 14px; }
  /* No team logos (FanCode-style single-image events): the banner takes the
     full width of the phone screen as a proper hero, not a thin strip. */
  .mws-left.mws-left-banner {
    padding: 0;
    width: 100%;
    min-height: 42vh;
    justify-content: flex-end;
  }
  .mws-left.mws-left-banner .mws-fallback-content { padding: 20px 18px 22px; gap: 10px; }
  .mws-left.mws-left-banner .mws-fallback-scrim {
    background: linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.45) 40%, rgba(0,0,0,0.95) 100%);
  }
}


/* Device name / ID — top right corner, desktop only */
.nav-device-info {
  display: flex; flex-direction: column; align-items: flex-end; justify-content: center;
  line-height: 1.35; flex-shrink: 0; padding-right: 2px; user-select: none;
}
.nav-device-name { font-family: var(--font-display); font-size: 11px; font-weight: 700; letter-spacing: 0.03em; color: rgba(255,255,255,0.75); white-space: nowrap; }
.nav-device-id { display: flex; align-items: center; justify-content: flex-end; color: var(--text-dim); margin-top: 2px; }
.nav-device-id svg { display: block; }

/* QR Panel */
.nav-qr-wrap { position: relative; display: flex; align-items: center; }
.nav-qr-btn { width: 38px; height: 38px; background: transparent; border: none; outline: none; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 17px; cursor: pointer; transition: all 0.18s; flex-shrink: 0; padding: 2px; box-shadow: none; color: #fff; }
.nav-qr-btn:hover,.nav-qr-btn.active { background: transparent; opacity: 0.85; }
.nav-qr-btn-img { width: 100%; height: 100%; object-fit: contain; display: block; }
.qr-float-panel { position: absolute; top: calc(100% + 14px); right: 0; z-index: 500; background: rgba(0,0,0,0.97); backdrop-filter: var(--blur); border-radius: 8px; padding: 18px; box-shadow: 0 0 44px rgba(157,107,255,0.15), 0 14px 44px rgba(0,0,0,0.75); text-align: center; transform: scale(0.88) translateY(-8px); opacity: 0; pointer-events: none; transform-origin: top right; transition: all 0.25s var(--spring); width: 196px; }
.qr-float-panel.open { transform: scale(1) translateY(0); opacity: 1; pointer-events: all; }
.qr-float-title { font-family: var(--font-display); font-size: 14px; font-weight: 800; letter-spacing: 0.1em; color: var(--lavender); margin-bottom: 4px; }
.qr-float-sub { font-size: 10px; color: var(--text-muted); letter-spacing: 0.05em; margin-bottom: 12px; }
.qr-float-panel img { width: 158px; height: 158px; background: #ffffff; padding: 8px; border: none; border-radius: 8px; display: block; outline: none; box-shadow: none; }
.qr-open-btn { display: block; margin-top: 12px; background: var(--grad-gold); color: #FFFFFF; border: none; padding: 9px 0; border-radius: 8px; width: 100%; font-family: var(--font-display); font-weight: 800; font-size: 12px; text-decoration: none; box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset, 0 6px 18px rgba(157,107,255,0.30); transition: all 0.18s; }
.qr-open-btn:hover { transform: translateY(-1px); box-shadow: 0 1px 0 rgba(255,255,255,0.6) inset, 0 10px 26px rgba(157,107,255,0.45); }
.qr-open-btn:hover { opacity: 0.9; }

/* ────────────────────────────────────────────
   RESPONSIVE
──────────────────────────────────────────── */
@media(max-width:900px) {
  header { display: none !important; }
  .nav-links-desktop { display: none; }
  .hamburger { display: flex; }
  .header-actions .btn-yt { display: none; }
  .header-actions .btn-get-vip-nav { display: none; }
  .header-actions .btn-login-nav { display: none; }
  .header-inner { padding: 0 16px; height: 58px; }
  .logo-img { height: 50px; }

  /* Device name/ID is desktop-only */
  .nav-device-info { display: none !important; }

  /* Hamburger + QR/scanner: flat, magenta */
  .nav-qr-btn {
    background: transparent; border: none;
    color: #9d6bff; box-shadow: none;
  }
  .nav-qr-btn:hover, .nav-qr-btn.active { background: transparent; }
  .hamburger { background: transparent; box-shadow: none; border: none; }
  .hamburger span { background: #9d6bff; border-radius: 1px; box-shadow: none; }

  .hero-cards-section { display: none !important; }
  .slides-container { display: block !important; }
  .hero-card-dots { display: none !important; }

  .match-overlay-section { display: block !important; padding: 6px 0 0; }
  .slider-match-overlay { flex-direction: column; overflow-x: visible; padding: 0 14px; gap: 8px; }
  .smo-card { min-width: 0 !important; max-width: 100% !important; flex-shrink: unset; width: 100%; }
  .smo-section { display: grid !important; grid-template-columns: 1fr !important; gap: 8px; }
  .smo-section-label { display: flex !important; grid-column: 1 / -1; }
  .smo-name { font-size: 16px; }
  .smo-logo { width: 36px; height: 36px; }

  #ch-browser .ch-tabs { flex-direction: row !important; overflow-x: auto; gap: 6px; }
  #ch-browser .ch-tab { width: auto !important; }

  .section-inner { padding: 0 16px; }
  .section { padding: 26px 0; }
  .channels-grid { grid-template-columns: repeat(3,1fr); }
  .fixtures-grid { grid-template-columns: 1fr 1fr; }
  .categories-grid { grid-template-columns: repeat(2,1fr); }
  .ott-grid { grid-template-columns: 1fr 1fr; }
