  .schedule-tabs { overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .tab { padding: 10px 14px; font-size: 12px; white-space: nowrap; }
  .footer-nav { gap: 20px; }
  .cta-box { padding: 32px 18px; }
}

@media(max-width:560px) {
  .header-inner { padding: 0 12px; height: 54px; }
  .logo-img { height: 44px; }

  .hero-cards-section { display: none !important; }
  .slides-container { display: block !important; }
  .match-overlay-section { display: block !important; padding: 6px 0 4px; }
  .slider-match-overlay { padding: 0 12px; gap: 8px; }
  .smo-card { width: 100% !important; min-width: 0 !important; padding: 10px 10px 9px; }
  .smo-section { display: grid !important; grid-template-columns: 1fr !important; gap: 8px; }
  .smo-section-label { display: flex !important; grid-column: 1 / -1; align-items: center; gap: 8px; font-family: var(--font-display); font-size: 10px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase; color: var(--lavender); padding: 2px 0; }
  .smo-section + .smo-section { border-top: 1px solid rgba(255,255,255,0.05); padding-top: 4px; }
  .smo-name { font-size: 14px; }
  .smo-logo { width: 32px; height: 32px; }
  .smo-btn { font-size: 11px; padding: 7px 12px; }
  .timer-display { font-size: 12px !important; }

  .section-inner { padding: 0 12px; }
  .section { padding: 20px 0; }
  .section-title { font-size: 19px; }

  #ch-browser .ch-tabs { flex-direction: column !important; gap: 6px; padding-bottom: 8px; overflow-x: visible; }
  #ch-browser .ch-tab { width: 100% !important; justify-content: flex-start; padding: 10px 14px; border-radius: 8px; }
  #ch-browser .ch-tab span { flex: 1; }

  .channels-grid { grid-template-columns: repeat(2,1fr); gap: 9px; }
  .channel-card { padding: 12px 10px; align-items: center; }
  .channel-icon-wrap { width: 50px; height: 50px; }
  .channel-name { font-size: 10px; text-align: center; }
  .channel-status { font-size: 9px; }
  .channel-prog { font-size: 9px; }
  .quality-badge { font-size: 7px; padding: 2px 5px; }

  .fixtures-grid { grid-template-columns: 1fr; gap: 10px; }
  .team-logo-wrap { width: 50px; height: 50px; }
  .categories-grid { grid-template-columns: repeat(2,1fr); gap: 10px; }
  .cat-card { height: 108px; padding: 14px; }
  .cat-name { font-size: 19px; }
  .ott-grid { grid-template-columns: 1fr; }
  .broadcast-grid { grid-template-columns: 1fr; }
  .ott-card { padding: 20px 16px; }
  .ott-name { font-size: 16px; }
  .ott-desc { font-size: 12px; }
  .partner-logos-row { grid-template-columns: repeat(4,1fr); }

  .match-row { display: flex; flex-direction: column; gap: 5px; padding: 10px 0; }
  .match-row > * { width: 100%; }
  .team-home,.team-away { text-align: left; }
  .match-vs { display: none; }

  .cta-title { font-size: clamp(20px,6vw,28px); }
  .cta-sub { font-size: 13px; }
  .cta-btn-primary,.cta-btn-outline { font-size: 13px; padding: 12px 18px; width: 100%; text-align: center; }
  .cta-btns { flex-direction: column; gap: 8px; }

  .social-inner { flex-direction: column; align-items: flex-start; gap: 10px; }
  .footer-nav { gap: 14px 20px; }
  .footer-bottom { align-items: center; gap: 8px; }

  .watch-modal { border-radius: 8px; max-height: 95vh; }
  .watch-modal-header { padding: 14px 16px 12px; }
  .watch-modal-title { font-size: 17px; }
  .watch-modal-body { padding: 14px 14px 16px; }
  .watch-channels { grid-template-columns: 1fr; }
  .watch-sx-featured { padding: 12px 14px; }
  .watch-channel-btn { padding: 10px 12px; }
}

@media(max-width:360px) {
  .logo-img { height: 38px; }
