  .channel-name { font-size: 9px; }
  .categories-grid { grid-template-columns: 1fr 1fr; }
  .partner-logos-row { grid-template-columns: repeat(3,1fr); }
  .smo-name { font-size: 13px; }
  /* Very narrow: hide subtitle in slides to keep content within 16:9 */
  .slide-sub { display: none; }
}

/* ────────────────────────────────────────────
   FONTS (keep selectors consistent)
──────────────────────────────────────────── */
.section-title,.channel-name,.fixture-team-name,.team-name,.smo-name,
.broadcast-name,.cat-name,.tab,.ticker-label,.ticker-item,.match-live-tag,
.slide-title,.cta-title,h1,h2,h3,h4 { font-family: var(--font-display) !important; }

.slide-sub,.broadcast-desc,.channel-prog,.fixture-venue-sm,.footer-brand p,
.footer-copy,p,.watch-ch-name,.social-link,.cta-sub { font-family: var(--font-body) !important; }

.nav-links-desktop a:not(.nav-movies-link),.drawer-nav a:not(.drawer-movies) { font-family: var(--font-display) !important; }
.slide-sport-badge,.smo-live-badge,.smo-upcoming-badge,.fixture-badge,
.quality-badge,.match-sport-badge,.badge-free,.badge-nologin,.badge-4k { font-family: var(--font-display) !important; }

/* ────────────────────────────────────────────
   MISC / LEGACY COMPAT
──────────────────────────────────────────── */
/* slide-content positioning is now handled by the main rule above — removed old override */
.slides-container { position: relative; }
.schedule-tabs { overflow-x: auto; -webkit-overflow-scrolling: touch; }

/* ────────────────────────────────────────────
   MOBILE BOTTOM NAV — narrow single-line strip, solid black,
   transparent icon-only buttons, outline → fill on tap.
   5 items: Home / Live Matches / Search / Live TV / Favourites.
   Desktop: hidden entirely.
──────────────────────────────────────────── */
.mobile-tabbar { display: none; }
@media(max-width:900px) {
  .mobile-tabbar {
    display: flex; align-items: center; justify-content: space-around;
    flex-wrap: nowrap;
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 1220;
    height: 40px; padding-bottom: env(safe-area-inset-bottom, 0);
    background: #000; border: none; box-shadow: none;
  }
  .mtab {
    flex: 1; display: flex; align-items: center; justify-content: center;
    height: 100%; color: #fff; text-decoration: none;
    background: transparent; border: none; box-shadow: none; cursor: pointer; padding: 0;
    -webkit-tap-highlight-color: transparent;
    transition: color 0.16s ease, transform 0.16s ease;
  }
  .mtab svg { width: 19px; height: 19px; display: block; }
  .mtab .mtab-fill-part { transition: fill 0.15s ease; }
  .mtab.active { color: #fff; }
  .mtab.active .mtab-fill-part { fill: currentColor; }
  .mtab:active { transform: scale(0.86); }

  /* Push page content above the fixed bar */
  body { padding-bottom: 40px; }
  footer { padding-bottom: calc(24px + 40px + env(safe-area-inset-bottom, 0)); }
}

/* ────────────────────────────────────────────
   MOBILE TOP STRIP — very narrow bar, just the hamburger menu.
   Replaces the full header on mobile (see header{display:none} above).
   Desktop: hidden entirely.
──────────────────────────────────────────── */
.mobile-topstrip { display: none; }
@media(max-width:900px) {
  .mobile-topstrip {
    display: flex; align-items: center; justify-content: flex-start;
    position: fixed; top: 0; left: 0; right: 0; z-index: 1210;
    height: 34px; padding: 0 12px;
    background: transparent;
    pointer-events: none;
  }
  .mts-hamburger {
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    gap: 4px; width: 30px; height: 100%; padding: 0;
    background: transparent; border: none; cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    pointer-events: auto;
  }
  .mts-hamburger span {
    display: block; width: 18px; height: 1.6px; border-radius: 1px;
    background: #fff;
    box-shadow: 0 0 3px rgba(0,0,0,0.9), 0 0 1px rgba(0,0,0,0.9);
    transition: transform 0.22s ease, opacity 0.22s ease;
  }
  .mts-hamburger.open span:nth-child(1) { transform: translateY(5.6px) rotate(45deg); }
  .mts-hamburger.open span:nth-child(2) { opacity: 0; }
  .mts-hamburger.open span:nth-child(3) { transform: translateY(-5.6px) rotate(-45deg); }
}

/* Ensure watch-strip doesn't duplicate style (override from body style tag) */
/* ══════════════════════════════════════════════════════════════════════
   CLEAN UI OVERRIDE — flat, minimal "TimStreams" style pass
   Everything below wins the cascade (loads after the block above).
   No JS/markup logic touched — only how things look.
═══════════════════════════════════════════════════════════════════════ */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

