@keyframes tgShimmer{ 0%{ background-position:130% 0; } 100%{ background-position:-30% 0; } }
@keyframes tgReveal{ from{ clip-path:inset(0 100% 0 0); opacity:.25; } to{ clip-path:inset(0 0 0 0); opacity:1; } }
