/* ══════════════════════════════════════════════════════════════════════
   FCX — integrated FanCode match browser (was an external iframe embed,
   now the full match-listing UI lives inline in the page). Every class
   and id is "fcx-" prefixed so nothing collides with the rest of the
   site's generic .card/.btn/.grid/.badge/.meta selectors. Cards route to
   play.html — that player page is already set up separately.
═══════════════════════════════════════════════════════════════════════ */
#fcx-root{ max-width: 1400px; margin: 0 auto; padding: 76px 20px 60px; }
.fcx-search-wrap{ position: relative; width: 100%; max-width: 320px; margin: 0 0 20px; }
.fcx-search-wrap input{
  width: 100%; background: var(--s2,rgba(255,255,255,0.06)); border: 1px solid var(--s3,rgba(255,255,255,0.08));
  color: var(--white,#fff); font-family: var(--font-body); font-size: 13px; padding: 10px 14px;
  border-radius: 8px; outline: none;
}
.fcx-search-wrap input:focus{ border-color: var(--indigo,#9d6bff); }

.fcx-hero{ position: relative; width: 100%; height: 380px; margin-bottom: 40px; border-radius: 12px; overflow: hidden; box-shadow: 0 12px 48px rgba(0,0,0,0.9); background:#000; }
.fcx-carousel-track{ position: relative; width: 100%; height: 100%; display: flex; transition: transform 0.5s cubic-bezier(0.4,0,0.2,1); }
.fcx-carousel-slide{ position: relative; min-width: 100%; height: 100%; background: #000; overflow: hidden; }
.fcx-slide-bg{ position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0.7; }
.fcx-slide-content{ position: relative; z-index: 2; height: 100%; display: flex; flex-direction: column; justify-content: flex-end; padding: 32px; }
.fcx-slide-content::before{ content:''; position:absolute; inset:0; z-index:-1; background: linear-gradient(135deg, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0.35) 50%, transparent 100%); }
.fcx-slide-status{ display: inline-flex; align-items: center; gap: 6px; background: transparent; border: 1px solid rgba(157,107,255,0.5); color: #9d6bff; font-family: var(--font-display); font-size: 10px; font-weight: 700; letter-spacing: 1px; padding: 5px 11px; border-radius: 18px; margin-bottom: 16px; text-transform: uppercase; width: fit-content; }
.fcx-slide-title{ font-family: var(--font-display); font-weight: 800; font-size: clamp(20px,4vw,36px); line-height: 1.15; margin-bottom: 12px; letter-spacing: -0.4px; color: var(--white,#fff); }
.fcx-slide-meta{ display: flex; gap: 16px; font-size: 13px; color: var(--text-muted,rgba(255,255,255,0.6)); margin-bottom: 16px; }
.fcx-slide-time{ font-size: 14px; font-weight: 600; color: var(--white,#fff); margin-bottom: 16px; }
.fcx-slide-actions{ display: flex; gap: 10px; }
.fcx-slide-btn{ appearance: none; border: none; cursor: pointer; background: var(--indigo,#9d6bff); color: #fff; font-family: var(--font-display); font-weight: 700; font-size: 12px; padding: 11px 20px; border-radius: 8px; box-shadow: 0 4px 12px rgba(157,107,255,0.3); transition: filter 0.2s; text-transform: uppercase; letter-spacing: 0.03em; }
.fcx-slide-btn:hover:not(:disabled){ filter: brightness(1.15); }
.fcx-slide-btn:disabled{ opacity: 0.6; cursor: not-allowed; box-shadow: none; }

.fcx-carousel-nav{ position: absolute; top: 50%; transform: translateY(-50%); z-index: 10; display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; background: rgba(157,107,255,0.2); border: 1px solid rgba(157,107,255,0.3); color: var(--indigo,#9d6bff); font-size: 18px; font-weight: 700; cursor: pointer; border-radius: 8px; transition: all 0.3s; opacity: 0; }
.fcx-hero:hover .fcx-carousel-nav{ opacity: 1; }
.fcx-carousel-nav:hover{ background: var(--indigo,#9d6bff); color: #fff; }
.fcx-carousel-nav.fcx-prev{ left: 16px; } .fcx-carousel-nav.fcx-next{ right: 16px; }

.fcx-carousel-dots{ position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%); z-index: 10; display: flex; gap: 8px; }
.fcx-dot{ width: 8px; height: 8px; background: rgba(255,255,255,0.3); border-radius: 50%; cursor: pointer; transition: all 0.3s; }
.fcx-dot.fcx-active{ background: var(--indigo,#9d6bff); width: 22px; border-radius: 4px; }

.fcx-section-title{ font-family: var(--font-display); font-size: 12px; font-weight: 700; margin: 0 0 24px; letter-spacing: 2px; text-transform: uppercase; color: var(--text-muted,rgba(255,255,255,0.55)); }

.fcx-grid{ display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 16px; }
.fcx-loading-state, .fcx-empty-state{ grid-column: 1/-1; text-align: center; padding: 70px 20px; color: var(--text-muted,rgba(255,255,255,0.55)); font-size: 13px; border: 1px dashed var(--s3,rgba(255,255,255,0.08)); border-radius: 12px; }

.fcx-card{ background: var(--s1,rgba(255,255,255,0.03)); border: 1px solid var(--s3,rgba(255,255,255,0.08)); overflow: hidden; box-shadow: 0 4px 16px rgba(0,0,0,0.6); transition: all 0.3s cubic-bezier(0.4,0,0.2,1); display: flex; flex-direction: column; }
.fcx-card:hover{ transform: translateY(-2px); border-color: rgba(157,107,255,0.4); box-shadow: 0 12px 32px rgba(0,0,0,0.8); }
.fcx-thumb-wrap{ position: relative; width: 100%; height: 150px; background: #000; overflow: hidden; }
.fcx-thumb-wrap img{ width: 100%; height: 100%; object-fit: cover; }
.fcx-badge{ position: absolute; top: 8px; right: 8px; display: inline-flex; align-items: center; gap: 4px; background: rgba(0,0,0,0.6); border: 1px solid rgba(157,107,255,0.5); color: #9d6bff; font-family: var(--font-display); font-size: 9px; font-weight: 700; letter-spacing: 0.8px; padding: 4px 8px; border-radius: 14px; text-transform: uppercase; }
.fcx-badge.fcx-upcoming{ border-color: rgba(157,107,255,0.5); color: var(--indigo,#9d6bff); }
.fcx-meta{ padding: 14px; display: flex; flex-direction: column; gap: 8px; flex: 1; text-align: center; }
.fcx-teams{ font-family: var(--font-body); font-size: 13px; font-weight: 600; line-height: 1.35; color: var(--white,#fff); }
.fcx-event{ font-size: 11px; color: var(--text-muted,rgba(255,255,255,0.55)); }
.fcx-card-time{ font-size: 11px; color: var(--text-muted,rgba(255,255,255,0.55)); }
.fcx-actions{ display: flex; flex-direction: column; gap: 8px; margin-top: 4px; }
.fcx-btn{ appearance: none; border: none; background: var(--indigo,#9d6bff); color: #fff; font-family: var(--font-display); font-weight: 700; font-size: 11px; padding: 10px 12px; border-radius: 6px; cursor: pointer; transition: filter 0.2s; text-transform: uppercase; letter-spacing: 0.02em; }
.fcx-btn:hover:not(:disabled){ filter: brightness(1.15); }
.fcx-btn:disabled{ opacity: 0.7; cursor: default; }
.fcx-btn.fcx-btn-upcoming{ background: transparent; border: 1px solid var(--s3,rgba(255,255,255,0.08)); color: var(--text-muted,rgba(255,255,255,0.55)); }

@media(max-width:768px){
  #fcx-root{ padding: 70px 16px 50px; }
  .fcx-hero{ height: 280px; margin-bottom: 30px; }
  .fcx-grid{ grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }
