.va-id-guide-steps b{ color: #fff; }
.va-id-guide-steps code{
  background: rgba(255,255,255,0.08); color: #6d28ff; padding: 1px 5px;
  border-radius: 4px; font-family: monospace; font-size: 11px;
}

.va-sort-row, .va-genre-row{ display:flex; gap:8px; flex-wrap:wrap; }
.va-sort-btn, .va-genre-chip{
  font-family:var(--cu-font,inherit); font-weight:700; font-size:11.5px;
  color:rgba(255,255,255,0.55); background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08);
  padding:7px 13px; border-radius:999px; cursor:pointer; white-space:nowrap;
}
.va-sort-btn.active, .va-genre-chip.active{ background:rgba(157,107,255,0.14); border-color:rgba(157,107,255,0.35); color:#fff; }

/* ── result grid (reuses .epg-no-results for empty states) ── */
.va-grid{
  display:grid !important; grid-template-columns:repeat(5,1fr) !important; gap:16px !important;
}
@media(max-width:1100px){ .va-grid{ grid-template-columns:repeat(3,1fr) !important; gap:14px !important; } }
@media(max-width:640px){ .va-grid{ grid-template-columns:repeat(2,1fr) !important; gap:10px !important; } }
@media(max-width:420px){ .va-grid{ grid-template-columns:repeat(2,1fr) !important; gap:8px !important; } }

.va-movie-card{
  position:relative; cursor:pointer; overflow:hidden; border-radius:8px !important;
  background:rgba(255,255,255,0.035) !important; border:1px solid rgba(255,255,255,0.07) !important;
  transition:transform .18s ease, border-color .18s ease;
}
.va-movie-card:hover{ transform:translateY(-3px); border-color:rgba(109,40,255,0.5) !important; }
.va-movie-poster{ position:relative; width:100%; aspect-ratio:2/3; background:#0a0a0a; overflow:hidden; }
.va-movie-poster img{ width:100%; height:100%; object-fit:cover; display:block; }
.va-movie-rating{
  position:absolute; top:6px; right:6px; z-index:1;
  display:inline-flex; align-items:center; gap:3px;
  font-size:10px !important; font-weight:800 !important;
  padding:3px 7px !important; border-radius:5px !important;
  background:linear-gradient(135deg,#C21764,#6d28ff) !important; color:#fff !important;
}
.va-movie-meta{ padding:9px 10px 10px; }
.va-movie-title{
  font-family:var(--font-display) !important; font-weight:800 !important; font-size:14px !important; color:#fff !important;
  overflow:hidden; text-overflow:ellipsis; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; line-height:1.3;
}
.va-movie-year{ font-size:11.5px !important; color:rgba(255,255,255,0.45) !important; margin-top:3px; font-weight:600; }

.va-sentinel{ height:1px; }
.va-loading-more{ text-align:center; padding:16px; font-size:12px; color:rgba(255,255,255,0.4); }

/* ── TV season/episode picker — VidAPI's listing embed_url for TV is
   show-level only, so this asks which episode before playing ── */
#va-tv-modal{
  display:none; position:fixed; inset:0; z-index:1600;
  background:rgba(0,0,0,0.7); align-items:center; justify-content:center; padding:20px;
}
#va-tv-modal.open{ display:flex; }
.va-tv-modal-box{
  width:100%; max-width:300px; background:#000000; border:1px solid rgba(255,255,255,0.1);
  border-radius:10px; padding:20px;
}
.va-tv-modal-title{ font-weight:800; color:#fff; font-size:14px; margin-bottom:14px; }
.va-tv-modal-row{ display:flex; gap:10px; margin-bottom:14px; }
.va-tv-modal-row label{ flex:1; }
.va-tv-modal-row span{ display:block; font-size:11px; color:rgba(255,255,255,0.5); margin-bottom:4px; }
.va-tv-modal-row input{
  width:100%; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.1);
  border-radius:6px; padding:8px 10px; color:#fff; font-size:13px; outline:none;
}
.va-tv-modal-actions{ display:flex; gap:8px; justify-content:flex-end; }
.va-tv-modal-actions button{ font-family:var(--cu-font,inherit); font-weight:700; font-size:12px; padding:8px 14px; border-radius:6px; cursor:pointer; border:none; }
.va-tv-modal-cancel{ background:rgba(255,255,255,0.08); color:#fff; }
.va-tv-modal-play{ background:var(--cu-accent,#9d6bff); color:#fff; font-weight:800; }

/* ── Load-on-demand gate: Movies content only starts fetching once the
     visitor explicitly taps "Load Movies", instead of auto-fetching the
     moment the Movies page opens (from hamburger, nav, or bottom tab). ── */
.va-load-gate{
  display:flex; flex-direction:column; align-items:center; justify-content:center;
  text-align:center; gap:12px; padding:60px 20px; margin-top:8px;
  background: var(--pm-surface-1,rgba(255,255,255,0.03));
  border:1px solid var(--pm-border,rgba(255,255,255,0.08));
  border-radius: 12px;
}
.va-load-gate-icon{ font-size:34px; line-height:1; }
.va-load-gate-title{
  font-family:var(--cu-font,inherit); font-weight:800; font-size:16px; color:#fff;
}
.va-load-gate-sub{
  font-family:var(--cu-font,inherit); font-size:13px; color:rgba(255,255,255,0.60);
  max-width:320px; line-height:1.5;
}
.va-load-gate-btn{
  display:inline-flex; align-items:center; gap:8px;
  background: var(--cu-accent,#9d6bff); color:#fff; border:none;
  font-family:var(--cu-font,inherit); font-weight:800; font-size:14px;
  padding:12px 26px; border-radius:8px; cursor:pointer; letter-spacing:0.02em;
  margin-top:6px; transition: background-color .2s ease, transform .15s ease;
}
.va-load-gate-btn:hover{ background:#c4a5ff; transform: translateY(-1px); }

/* inline */

#stream-player-overlay{
  display: none; position: fixed; inset: 0; z-index: 1600;
  background: #000;
}
#stream-player-overlay.open{ display: flex; flex-direction: column; }
@media (min-width: 901px){
  #stream-player-overlay.open{ flex-direction: row; }
}

#stream-player-main{
  position: relative;
  flex: 1 1 auto; min-width: 0; min-height: 0;
  display: flex; flex-direction: column;
  background: #000;
}

/* ── Bottom info bar (channel/match name, tag, fullscreen) ── */
#stream-player-infobar{
  position: relative; z-index: 4; flex-shrink: 0;
  display: flex; align-items: center; gap: 10px;
  padding: 9px 14px; background: #000000;
  border-top: 1px solid rgba(255,255,255,0.08);
}
#sp-info-logo{
  width: 32px; height: 32px; border-radius: 6px; flex-shrink: 0; overflow: hidden;
  background: rgba(255,255,255,0.06); display: flex; align-items: center; justify-content: center;
}
#sp-info-logo img{ width: 100%; height: 100%; object-fit: contain; }
#sp-info-text{ min-width: 0; flex: 1; }
#sp-info-name{
  font-family: var(--cu-font,inherit); font-weight: 800; font-size: 13px; color: #fff;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
#sp-info-meta{
  font-family: var(--cu-font,inherit); font-weight: 700; font-size: 10px; letter-spacing: .03em;
  color: rgba(255,255,255,0.5); display: flex; align-items: center; gap: 6px; margin-top: 2px;
  text-transform: uppercase;
}
.sp-info-live{ display: inline-flex; align-items: center; gap: 4px; color: #6d28ff; font-weight: 800; }
.sp-info-4k{ display: inline-flex; align-items: center; padding: 1px 6px; border-radius: 5px; background: var(--pm-magenta,#9d6bff); color: #fff; font-weight: 800; font-size: 9px; letter-spacing: .06em; }
.sp-info-live::before{ content: ''; width: 6px; height: 6px; border-radius: 50%; background: #6d28ff; box-shadow: 0 0 6px #6d28ff; }
#sp-info-fullscreen{
  flex-shrink: 0; width: 32px; height: 32px; border-radius: 8px; border: none;
  background: rgba(255,255,255,0.08); color: #fff; display: flex; align-items: center; justify-content: center;
  cursor: pointer;
}
#sp-info-fullscreen:hover{ background: rgba(255,255,255,0.16); }
#sp-info-fullscreen svg{ width: 15px; height: 15px; }
#sp-info-multiview{
  flex-shrink: 0; width: 32px; height: 32px; border-radius: 8px; border: none;
  background: rgba(255,255,255,0.08); color: #fff; display: flex; align-items: center; justify-content: center;
  cursor: pointer;
}
#sp-info-multiview:hover{ background: rgba(255,255,255,0.16); }
#sp-info-multiview svg{ width: 15px; height: 15px; }
/* FanCode source switch (World / India) — only shown while a FanCode match is playing */
#sp-src-switch{ display: none; align-items: center; gap: 3px; flex-shrink: 0; padding: 3px; border-radius: 9px; background: rgba(255,255,255,0.07); }
#sp-src-switch.show{ display: flex; }
.sp-src-btn{
  border: none; background: transparent; color: rgba(255,255,255,0.62); cursor: pointer;
  font-family: var(--cu-font,inherit); font-weight: 800; font-size: 10px; letter-spacing: .04em; text-transform: uppercase;
  padding: 7px 11px; border-radius: 7px; white-space: nowrap;
}
.sp-src-btn:hover:not(:disabled):not(.active){ background: rgba(255,255,255,0.10); color: #fff; }
.sp-src-btn.active{ background: var(--cu-accent,#9d6bff); color: #fff; }
.sp-src-btn:disabled{ opacity: .38; cursor: not-allowed; }

/* ── Ad-safety notice: recommend Brave / an ad blocker (sits beside the
     player, in the rail column — never overlapping the video itself) ── */
#sp-adblock-banner{
  flex-shrink: 0;
  display: flex; align-items: center; gap: 9px;
  background: rgba(255,255,255,0.045); border-bottom: 1px solid rgba(255,255,255,0.08);
  padding: 11px 14px;
}
#sp-adblock-logo{ width: 16px; height: 16px; flex-shrink: 0; }
#sp-adblock-text{
  flex: 1; font-family: var(--cu-font,inherit); font-weight: 600; font-size: 11px;
  line-height: 1.4; color: rgba(255,255,255,0.85);
}
#sp-adblock-text b{ color: #6d28ff; font-weight: 800; }
#sp-adblock-text a{ color: #6d28ff; font-weight: 800; text-decoration: underline; }
#sp-adblock-close{
  flex-shrink: 0; background: none; border: none; color: rgba(255,255,255,0.45);
  font-size: 17px; line-height: 1; cursor: pointer; padding: 0 2px;
}
#sp-adblock-close:hover{ color: #fff; }
@media (max-width: 900px){
  #sp-adblock-text{ font-size: 10.5px; }
}

/* ── Rail sidebar: "MORE CHANNELS" / "MORE MATCHES" (replaces live chat) ── */
#stream-player-rail{
  flex-shrink: 0; min-height: 0;
  background: #000000; display: flex; flex-direction: column;
  border-top: 1px solid rgba(255,255,255,0.08);
}
@media (min-width: 901px){
  #stream-player-rail{
    width: 300px; max-width: 30vw;
    border-top: none; border-left: 1px solid rgba(255,255,255,0.08);
  }
}
#sp-rail-header{ display: flex; align-items: center; gap: 8px; padding: 14px 16px 10px; flex-shrink: 0; }
#sp-rail-header-bar{ width: 3px; height: 15px; border-radius: 3px; background: linear-gradient(180deg,#F5A623,#6d28ff); flex-shrink: 0; }
#stream-player-rail-title{
  font-family: var(--cu-font,inherit); font-weight: 800; font-size: 11px; letter-spacing: .08em;
  color: #fff; text-transform: uppercase;
}
#stream-player-rail-list{
  flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden;
  padding: 0 10px 14px; display: flex; flex-direction: column; gap: 6px;
  -webkit-overflow-scrolling: touch;
}
@media (max-width: 900px){
  #stream-player-rail-list{
    flex-direction: row; overflow-x: auto; overflow-y: hidden;
    padding: 0 12px 14px;
  }
}
.sp-rail-item{
  display: flex; align-items: center; gap: 10px; flex-shrink: 0;
  background: transparent; border: none; border-radius: 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding: 10px 4px; cursor: pointer; text-align: left; color: #fff;
  font-family: var(--cu-font,inherit); width: 100%;
  border-left: 3px solid transparent;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.sp-rail-item:hover{ background: rgba(255,255,255,0.05); }
.sp-rail-item.active{ background: rgba(109,40,255,0.10); border-left-color: #6d28ff; }
@media (max-width: 900px){
  .sp-rail-item{ width: 188px; border-bottom: none; border-left: none; border-right: 1px solid rgba(255,255,255,0.07); border-radius: 0; padding: 8px 10px; }
  .sp-rail-item.active{ background: rgba(109,40,255,0.10); border-bottom: 2px solid #6d28ff; }
}
.sp-rail-thumb{
  width: 34px; height: 34px; border-radius: 6px; flex-shrink: 0; overflow: hidden;
  background: rgba(255,255,255,0.05); display: flex; align-items: center; justify-content: center;
}
.sp-rail-thumb img{ max-width: 100%; max-height: 100%; object-fit: contain; }
/* FanCode entries (no team logos) show their banner instead — wider, and
   cropped to fill rather than letterboxed like a small square team icon. */
.sp-rail-thumb.sp-rail-thumb-banner{ width: 56px; height: 34px; }
.sp-rail-thumb.sp-rail-thumb-banner img{ width: 100%; height: 100%; max-width: none; max-height: none; object-fit: cover; }
.sp-rail-vs{ font-size: 8px; color: rgba(255,255,255,0.4); margin: 0 1px; flex-shrink: 0; }
.sp-rail-info{ min-width: 0; flex: 1; display: flex; flex-direction: column; gap: 2px; }
.sp-rail-name{ font-size: 12px; font-weight: 700; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-rail-meta{ font-size: 10px; color: rgba(255,255,255,0.4); display: flex; align-items: center; gap: 5px; }
.sp-rail-live{ color: #6d28ff; font-weight: 800; font-size: 9px; letter-spacing: .03em; }
.sp-rail-empty{ padding: 24px 10px; font-size: 12px; color: rgba(255,255,255,0.4); font-family: var(--cu-font,inherit); text-align: center; }
.sp-rail-viewall{
  display: block; width: 100%; margin-top: 8px; flex-shrink: 0;
  background: #6d28ff; color: #101010; border: none; border-radius: 8px;
  font-family: var(--cu-font,inherit); font-weight: 800; font-size: 11px; letter-spacing: .04em;
  text-transform: uppercase; padding: 11px; cursor: pointer; text-align: center;
}
.sp-rail-viewall:hover{ background: #FF5FA0; }
.sp-ad-box{
  margin: 10px 10px 14px; flex-shrink: 0;
  border: 1px dashed rgba(157,107,255,0.35); border-radius: 6px;
  padding: 16px 12px; text-align: center; background: rgba(157,107,255,0.05);
}
.sp-ad-title{ font-family: var(--cu-font,inherit); font-size: 11px; font-weight: 800; letter-spacing: .12em; color: rgba(157,107,255,0.75); margin-bottom: 6px; text-transform: uppercase; }
.sp-ad-contact{ font-size: 10.5px; color: rgba(255,255,255,0.4); }
.sp-ad-handle{ color: #9d6bff; font-weight: 700; }
@media (max-width: 900px){ .sp-ad-box{ flex-shrink: 0; width: 180px; margin: 0 12px 0 0; } }
@media (max-width: 900px){
  .sp-rail-viewall{ width: 160px; margin-top: 0; flex-shrink: 0; }
}

#stream-player-topbar{
  position: absolute; top: 0; left: 0; right: 0; z-index: 5;
  display: flex; align-items: center; gap: 12px;
  padding: 14px 16px 28px;
  pointer-events: none;
}
#stream-player-backdrop{
  position: absolute; inset: 0; z-index: 0;
  background: linear-gradient(to bottom, rgba(0,0,0,0.80) 0%, rgba(0,0,0,0.45) 55%, transparent 100%);
  opacity: 1;
  transition: opacity 0.35s ease;
  pointer-events: none;
}
#stream-player-topbar.sp-idle #stream-player-backdrop{ opacity: 0; }
#stream-player-back{
  position: relative; z-index: 1;
  display: flex; align-items: center; gap: 6px;
  background: rgba(255,255,255,0.10); border: none; color: #fff;
  font-family: var(--cu-font,inherit); font-weight: 700; font-size: 12px;
  padding: 8px 12px; cursor: pointer; border-radius: 8px; letter-spacing: 0.03em;
  flex-shrink: 0; backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
  opacity: 1; pointer-events: auto;
}
#stream-player-back:hover{ background: rgba(255,255,255,0.18); }
#stream-player-back svg{ width: 14px; height: 14px; flex-shrink: 0; }
#stream-player-cast{
  position: relative; z-index: 1; margin-left: auto;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255,255,255,0.10); border: none; color: #fff;
  width: 34px; height: 34px; padding: 0; cursor: pointer; border-radius: 50%;
  flex-shrink: 0; backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
  opacity: 1; pointer-events: auto;
}
#stream-player-cast:hover{ background: rgba(255,255,255,0.18); }
#stream-player-cast svg{ width: 17px; height: 17px; flex-shrink: 0; display: block; }
#stream-player-cast.sp-cast-active{ background: #6d28ff; color: #101010; }
#stream-player-cast.sp-cast-active:hover{ background: #FF5FA0; }
#sx-cast-toast{
  position: fixed; left: 50%; bottom: 32px; transform: translateX(-50%) translateY(20px);
  background: rgba(20,20,20,0.95); color: #fff; font-family: var(--cu-font,inherit);
  font-size: 12.5px; font-weight: 600; letter-spacing: 0.01em;
  padding: 10px 18px; border-radius: 8px; max-width: 90vw; text-align: center;
  z-index: 2000; opacity: 0; pointer-events: none;
  transition: opacity .25s ease, transform .25s ease;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}
#sx-cast-toast.show{ opacity: 1; transform: translateX(-50%) translateY(0); }
.sx-cast-help-overlay{
  display: none; position: fixed; inset: 0; z-index: 2100;
  background: rgba(0,0,0,0.72);
  align-items: center; justify-content: center; padding: 20px;
}
.sx-cast-help-overlay.open{ display: flex; }
.sx-cast-help-box{
  background: #000000; border: 1px solid rgba(255,255,255,0.12);
  border-radius: 8px; max-width: 360px; width: 100%; padding: 22px 22px 18px;
  font-family: var(--cu-font,inherit); color: #fff;
  box-shadow: 0 20px 50px rgba(0,0,0,0.55);
}
.sx-cast-help-title{ font-size: 15px; font-weight: 800; margin-bottom: 10px; letter-spacing: 0.01em; }
.sx-cast-help-body{ font-size: 12.5px; line-height: 1.55; color: rgba(255,255,255,0.75); margin: 0 0 12px; }
.sx-cast-help-steps{ margin: 0 0 16px; padding-left: 18px; font-size: 12.5px; line-height: 1.7; color: rgba(255,255,255,0.85); }
.sx-cast-help-steps b{ color: #6d28ff; }
.sx-cast-help-close{
  width: 100%; background: #6d28ff; color: #101010; border: none;
  font-weight: 800; font-size: 12.5px; letter-spacing: 0.04em; text-transform: uppercase;
  padding: 11px; cursor: pointer; border-radius: 8px;
}
.sx-cast-help-close:hover{ background: #FF5FA0; }
#stream-player-title{
  position: relative; z-index: 1;
  flex: 1 1 auto; min-width: 0;
  font-family: var(--cu-font,inherit); font-weight: 800; font-size: 13px;
  color: #fff; letter-spacing: 0.02em;
  text-shadow: 0 1px 4px rgba(0,0,0,0.6);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  opacity: 1;
  transition: opacity 0.35s ease;
}
#stream-player-topbar.sp-idle #stream-player-title{ opacity: 0; }

#stream-player-body{
  flex: 1; min-height: 0;
  display: flex; align-items: center; justify-content: center;
  background: #000;
  position: relative;
}
#stream-player-frame-wrap{
  width: 100%; height: 100%;
  max-width: 100%; max-height: 100%;
  aspect-ratio: 16/9;
  margin: auto;
  position: relative;
}
#stream-player-frame{
  width: 100%; height: 100%; border: none; display: block; background: #000;
}

#stream-player-loading{
  position: absolute; inset: 0; z-index: 5;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: #000000;
  opacity: 1; transition: opacity .35s ease;
  pointer-events: none;
  padding: 28px;
}
#stream-player-loading.sp-loading-hide{ opacity: 0; }
#sp-loading-spinner{
  width: 40px; height: 40px; border-radius: 50%;
  border: 3px solid rgba(255,255,255,0.12); border-top-color: #6d28ff;
  animation: spLoadingSpin 0.85s linear infinite;
