}
@keyframes spLoadingSpin{ to{ transform: rotate(360deg); } }
#sp-loading-status{ width: 240px; max-width: 70vw; margin-top: 4px; }
#sp-loading-label{
  font-size: 11.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  color: rgba(255,255,255,0.8); text-align: center; margin-bottom: 9px;
}
