  background: linear-gradient(90deg,#6d28ff,#c4a5ff);
  border-radius: 999px;
}

/* inline */

#sx-multiview-overlay{
  display:none; position:fixed; inset:0; z-index:1450;
  background:#000; flex-direction:column;
}
#sx-multiview-overlay.open{ display:flex; }
#mv-topbar{
  flex:0 0 auto; display:flex; align-items:center; gap:14px;
  padding:12px 16px; padding-top:max(12px,env(safe-area-inset-top));
  background:rgba(0,0,0,0.94); border-bottom:1px solid rgba(255,255,255,0.08);
}
#mv-back{
  display:flex; align-items:center; gap:4px; background:none; border:none;
  color:#fff; font-weight:700; font-size:13px; cursor:pointer; padding:6px 4px 6px 0; flex-shrink:0;
}
#mv-back svg{ width:20px; height:20px; }
