/* inline */

#vip-overlay{
  display: none; position: fixed; inset: 0; z-index: 1200;
  background: #000000; overflow-y: auto; -webkit-overflow-scrolling: touch;
}
#vip-overlay.open{ display: block; }

/* Content starts BELOW the floating nav pill: nav clearance + two lines. */
#vip-page-inner{
  max-width: 1120px; margin: 0 auto;
  padding: calc(var(--sx-nav-safe, 80px) + 48px) 20px 96px;
  min-height: 100vh;
  --sxp-gold: #E8C265; --sxp-gold-deep: #B98A2E;
  --sxp-ok: #4ADE9A; --sxp-warn: #FFB547; --sxp-mix: #9d6bff;
  --sxp-line: var(--pm-border, rgba(255,255,255,0.08));
  --sxp-text: var(--pm-text, #F5F5F7);
  --sxp-dim: var(--pm-text-muted, rgba(245,245,247,0.58));
  --sxp-faint: var(--pm-text-faint, rgba(245,245,247,0.36));
  --sxp-s1: var(--pm-surface-1, #000000);
  --sxp-s2: var(--pm-surface-2, #000000);
  --sxp-s3: var(--pm-surface-3, #101010);
  --sxp-accent: var(--pm-magenta, #9d6bff);
  color: var(--sxp-text);
  font-family: var(--pm-font, 'Inter', sans-serif);
}
#vip-page-inner *{ box-sizing: border-box; }
#vip-page-inner button, #vip-page-inner a, #vip-page-inner select, #vip-page-inner input{ font-family: inherit; }
#vip-page-inner :focus-visible{ outline: 2px solid var(--sxp-gold); outline-offset: 2px; }

/* ── Heading row ── */
.sxp-top{ display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 22px; }
.sxp-title{ font-size: 30px; line-height: 1.15; font-weight: 800; color: #fff; margin: 0 0 8px; letter-spacing: -0.01em; }
.sxp-sub{ font-size: 14px; line-height: 1.6; color: var(--sxp-dim); max-width: 620px; margin: 0; }
.sxp-back{
  flex-shrink: 0; cursor: pointer; background: var(--sxp-s2); color: var(--sxp-text);
  border: 1px solid var(--sxp-line); padding: 8px 14px; font-size: 13px; font-weight: 600; border-radius: 999px;
}
.sxp-back:hover{ background: var(--sxp-s3); }

.sxp-cta{
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; cursor: pointer;
  border: 1px solid var(--sxp-line); background: var(--sxp-s2); color: var(--sxp-text);
  font-size: 13px; font-weight: 700; padding: 9px 14px; text-decoration: none; line-height: 1.2; border-radius: 10px;
  transition: background-color .15s ease, border-color .15s ease;
}
.sxp-cta:hover{ background: var(--sxp-s3); border-color: var(--pm-border-strong, rgba(255,255,255,0.14)); }
.sxp-cta.main{ background: var(--sxp-accent); border-color: var(--sxp-accent); color: #fff; width: 100%; }
.sxp-cta.main:hover{ background: var(--pm-magenta-hover, #c4a5ff); border-color: var(--pm-magenta-hover, #c4a5ff); }

/* ── Access gate ── */
#vip-gate{ display: flex; align-items: center; justify-content: center; min-height: 50vh; padding: 20px 0; }
.vip-gate-box{
  width: 100%; max-width: 360px; text-align: center;
  background: var(--sxp-s1); border: 1px solid var(--sxp-line); border-radius: 16px; padding: 34px 26px 28px;
}
.vip-gate-icon{
  width: 52px; height: 52px; margin: 0 auto 16px; border-radius: 50%;
  background: rgba(157,107,255,0.12); display: flex; align-items: center; justify-content: center;
  color: var(--sxp-accent);
}
.vip-gate-icon svg{ width: 24px; height: 24px; }
.vip-gate-title{ font-size: 19px; font-weight: 800; color: #fff; margin: 0 0 6px; }
.vip-gate-sub{ font-size: 13px; color: var(--sxp-dim); line-height: 1.5; margin: 0 0 20px; }
#vip-gate-form{ display: flex; flex-direction: column; gap: 10px; }
.vip-gate-input{
  width: 100%; text-align: center; letter-spacing: 4px; font-size: 18px; font-weight: 700;
  background: var(--sxp-s2); border: 1px solid var(--sxp-line); border-radius: 10px; color: #fff;
  padding: 12px 14px; outline: none;
}
.vip-gate-input:focus{ border-color: var(--sxp-accent); }
.vip-gate-err{ min-height: 16px; font-size: 12.5px; color: #FF6B6B; margin: 12px 0 0; }

/* ── Stat row / toolbar ── */
.vip-stat-row{ display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 18px; }
.vip-stat-chip{
  display: inline-flex; align-items: center; gap: 8px; padding: 8px 14px; border-radius: 999px;
  background: var(--sxp-s1); border: 1px solid var(--sxp-line); font-size: 12.5px; font-weight: 600; color: var(--sxp-dim);
}
.vip-stat-chip b{ color: #fff; font-variant-numeric: tabular-nums; }
.vip-stat-dot{ width: 8px; height: 8px; border-radius: 50%; background: var(--sxp-ok); box-shadow: 0 0 10px 2px rgba(74,222,154,0.55); flex: 0 0 auto; }
.vip-stat-dot.pulse{ animation: vipPulse 1.6s ease-in-out infinite; }
.vip-stat-dot.err{ background: #FF6B6B; box-shadow: 0 0 10px 2px rgba(255,107,107,0.55); }
@keyframes vipPulse{ 0%,100%{ opacity:1; transform:scale(1); } 50%{ opacity:.45; transform:scale(.78); } }

.vip-toolbar{ display: flex; flex-direction: column; gap: 12px; margin-bottom: 18px; }
.vip-search{
  display: flex; align-items: center; gap: 10px; padding: 4px 8px 4px 14px; border-radius: 999px;
  background: var(--sxp-s1); border: 1px solid var(--sxp-line);
}
.vip-search svg{ flex: 0 0 auto; opacity: .6; width: 17px; height: 17px; color: var(--sxp-dim); }
.vip-search input{
  flex: 1; min-width: 0; background: transparent; border: none; outline: none; color: #fff;
  font-size: 14px; padding: 9px 4px;
}
.vip-search input::placeholder{ color: var(--sxp-faint); }
.vip-search-clear{
  flex: 0 0 auto; width: 26px; height: 26px; border-radius: 50%; border: none; display: none;
  align-items: center; justify-content: center; background: rgba(255,255,255,0.08); color: var(--sxp-dim); cursor: pointer;
}
.vip-search-clear.show{ display: flex; }
.vip-cats{ display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; scrollbar-width: none; }
.vip-cats::-webkit-scrollbar{ display: none; }
.vip-pill{
  flex: 0 0 auto; display: flex; align-items: center; gap: 7px; cursor: pointer;
  background: var(--sxp-s1); color: var(--sxp-dim); border: 1px solid var(--sxp-line);
  font-size: 12.5px; font-weight: 600; padding: 7px 13px; border-radius: 999px; white-space: nowrap;
}
.vip-pill .cnt{ font-size: 11px; color: var(--sxp-faint); }
.vip-pill.active{ color: #fff; background: rgba(157,107,255,0.14); border-color: rgba(157,107,255,0.32); }
.vip-pill.active .cnt{ color: rgba(255,255,255,0.7); }

/* ── Loading / error stages ── */
.vip-stage{ display: flex; align-items: center; justify-content: center; min-height: 40vh; padding: 30px 0; text-align: center; }
.vip-stage-card{ max-width: 320px; }
.vip-spinner{ width: 40px; height: 40px; margin: 0 auto 16px; border-radius: 50%; border: 3px solid var(--sxp-line); border-top-color: var(--sxp-accent); animation: vipSpin 0.9s linear infinite; }
@keyframes vipSpin{ to{ transform: rotate(360deg); } }
.vip-stage-title{ font-size: 15px; font-weight: 700; color: #fff; margin: 0 0 6px; }
.vip-stage-sub{ font-size: 12.5px; color: var(--sxp-dim); margin: 0; line-height: 1.5; }
.vip-retry{ margin-top: 16px; }

/* ── Channel grid ── */
.vip-grid{ display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; }
.vip-card{
  background: var(--sxp-s1); border: 1px solid var(--sxp-line); border-radius: 12px; padding: 12px;
  display: flex; flex-direction: column; gap: 8px; cursor: pointer; transition: border-color .15s ease, transform .15s ease;
}
.vip-card:hover{ border-color: rgba(157,107,255,0.4); transform: translateY(-2px); }
.vip-card-logo{
  width: 100%; aspect-ratio: 16/9; border-radius: 8px; background: var(--sxp-s2); display: flex;
  align-items: center; justify-content: center; overflow: hidden;
}
.vip-card-logo img{ width: 100%; height: 100%; object-fit: contain; padding: 10px; }
.vip-card-logo.placeholder{ color: var(--sxp-faint); }
.vip-card-logo svg{ width: 26px; height: 26px; }
.vip-card-name{ font-size: 13px; font-weight: 700; color: #fff; line-height: 1.3; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.vip-card-group{ font-size: 11px; color: var(--sxp-faint); text-transform: uppercase; letter-spacing: .04em; }
.vip-card-play{ display: flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 700; color: var(--sxp-accent); margin-top: auto; }
.vip-card-play svg{ width: 12px; height: 12px; }

.vip-empty{ text-align: center; color: var(--sxp-dim); font-size: 14px; padding: 36px 12px; background: var(--sxp-s1); border: 1px dashed var(--sxp-line); border-radius: 12px; }
.vip-loadmore{ text-align: center; font-size: 12px; color: var(--sxp-faint); padding: 18px 0 6px; }
.vip-sentinel{ height: 1px; }

@media (max-width: 560px){
  #vip-page-inner{ padding-left: 14px; padding-right: 14px; }
  .sxp-title{ font-size: 24px; }
  .sxp-top{ flex-direction: column; }
  .vip-grid{ grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); }
}

