/* perf-overrides */

/* PERF: no backdrop-filter on always-visible / repeated elements (it forces a GPU blur of whatever scrolls behind) */
header,.btn-yt,.btn-discord,.btn-telegram,.channel-card,.smo-card,.smo-empty-box,.smo-game-tab,.smo-game-select,
.fixture-card,.ott-card,.ott-card-full,.broadcast-card,.cta-box,.discord-card,.whatsapp-card,.ch-search-box,
.epg-search-box,.epg-select-wrap select,.fpx-card,.sx-heart-btn,.sx-maintenance-box,#fifa-knockout-card,
#fifa-topbar,#fifa-panel-hdr,#adminchat-topbar,#fancode-back-btn,[class*="-card"]{
  backdrop-filter:none !important;-webkit-backdrop-filter:none !important;
}
header,header.scrolled{background:rgba(0,0,0,0.96) !important;}
/* full-screen 42px blur on movie detail backdrop is very expensive */
.mws-bg{filter:brightness(.35) !important;}

/* smooth-motion */

/* ===== SMOOTH MOTION: animate only transform/opacity/colour (compositor-friendly) ===== */
/* 1. replace "transition: all" with an explicit, cheap property list (never layout props) */
.btn-diamond-glow,
.loader-powered,
header,
.nav-links-desktop a,
.nav-watch-btn,
.btn-get-vip-nav,
.btn-login-nav,
.btn-yt,
.btn-discord,
.btn-telegram,
.drawer-close,
.drawer-nav a,
.hsc-btn-outline,
.btn-slide-outline,
.wcs-btn,
.smo-game-tab,
.ch-tab,
.cat-card-preview,
.cat-viewall-card,
.ott-card,
.tab,
.cta-btn-outline,
.social-link,
.watch-modal-close,
.watch-channel-btn,
.watch-sx-featured,
.mws-close,
.mws-server-btn,
.nav-qr-btn,
.qr-open-btn,
#fifa-panel-ext,
.ott-card-full,
.fcx-carousel-nav,
.fcx-card,
.pcqn-item,
.mtab,
.va-type-btn,
.va-sort-btn,
.va-genre-chip{
  transition-property: background-color, color, border-color, opacity, transform, box-shadow !important;
}
.hamburger span{ transition-property: transform, opacity, background-color !important; }
.dot{ transition-property: transform, background-color !important; }
.fcx-dot{ transition-property: width, background-color !important; }
.qr-float-panel{ transition-property: transform, opacity, visibility !important; transition-duration:.18s !important; }
/* snappier timing on the big card hovers (was 0.28-0.3s) */
.ott-card,.ott-card-full,.fcx-card,.cat-card-preview,header{ transition-duration:.2s !important; }
.slide{ transition-duration:.35s !important; }

/* 2. side drawer: slide with transform (GPU) instead of animating "left" (layout every frame) + fade the dim overlay */
.side-drawer{ left:0 !important; transform:translate3d(-105%,0,0); transition:transform .24s cubic-bezier(.2,.8,.2,1) !important; will-change:transform; }
.side-drawer.open{ transform:translate3d(0,0,0); }
.drawer-overlay.open{ animation:fadeUp .2s ease both; }

/* 3. keyframes that repainted every frame (text-shadow / filter / box-shadow) -> opacity & transform only */
@keyframes moviesGlow{ 0%,100%{opacity:1} 50%{opacity:.72} }
@keyframes loaderLogoPulse{ 0%,100%{transform:scale(1)} 50%{transform:scale(1.05)} }
@keyframes sxPanelIntroPop{ 0%{opacity:0;transform:scale(.8)} 100%{opacity:1;transform:scale(1)} }
@keyframes pulse{ 0%,100%{opacity:1} 50%{opacity:.45} }

/* 4. tap feel: no 300ms double-tap delay, no hover-lag on touch screens / TVs without a pointer */
a,button,[onclick],[role="button"],.tab,.ch-tab,.smo-game-tab{ touch-action:manipulation; }
@media (hover:none){
  *,*::before,*::after{ transition-duration:.12s !important; }
  .side-drawer{ transition-duration:.24s !important; }
}

/* 5. respect "reduce motion" (also helps weak devices): stop decorative loops */
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{ animation-iteration-count:1 !important; animation-duration:.01s !important; transition-duration:.01s !important; scroll-behavior:auto !important; }
  .ticker-track{ animation:none !important; }
}

/* hotstar-ui */

