.sxs-va{margin-left:auto;font:600 14px var(--pm-font,inherit);color:#c4a5ff;cursor:pointer;}
.sxs-va:hover{color:#fff;}
.sxs-po{flex:0 0 150px;width:150px;}.sxs-po .sxs-th{aspect-ratio:2/3;}
.sxs-lo{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:16px;background:radial-gradient(circle at 50% 40%,#202020,#101010);}
