.sxs-lo u{text-decoration:none;font:800 26px var(--pm-font,inherit);color:#bababa;}
.sxs-sb{display:flex;align-items:center;gap:8px;width:min(340px,100%);padding:9px 14px;background:rgba(255,255,255,.08);border-radius:999px;margin:0 0 12px;color:#a7a7a7;}
