/* home screen movies / TV posters: no title under the poster */
.sxs-po .sxs-bar{display:none}
.sxs-po{cursor:pointer}

/* ev-minimal-ui */

#sp-info-multiview{display:none!important}
:root{--evc:40px}
#stream-player-back{width:var(--evc);height:var(--evc)}
#stream-player-infobar{height:76px;padding:0 20px 0 70px;gap:10px}
