    background:inherit; background-repeat:no-repeat; background-size:contain !important; background-position:center center !important;
    -webkit-mask-image:linear-gradient(90deg,transparent 0%,rgba(0,0,0,.04) 3%,rgba(0,0,0,.15) 7%,rgba(0,0,0,.4) 13%,rgba(0,0,0,.72) 19%,rgba(0,0,0,.92) 25%,#000 31%,#000 69%,rgba(0,0,0,.92) 75%,rgba(0,0,0,.72) 81%,rgba(0,0,0,.4) 87%,rgba(0,0,0,.15) 93%,rgba(0,0,0,.04) 97%,transparent 100%),linear-gradient(180deg,transparent 0%,rgba(0,0,0,.15) 5%,rgba(0,0,0,.5) 10%,rgba(0,0,0,.85) 16%,#000 22%,#000 76%,rgba(0,0,0,.8) 84%,rgba(0,0,0,.4) 92%,transparent 100%); -webkit-mask-composite:source-in;
    mask-image:linear-gradient(90deg,transparent 0%,rgba(0,0,0,.04) 3%,rgba(0,0,0,.15) 7%,rgba(0,0,0,.4) 13%,rgba(0,0,0,.72) 19%,rgba(0,0,0,.92) 25%,#000 31%,#000 69%,rgba(0,0,0,.92) 75%,rgba(0,0,0,.72) 81%,rgba(0,0,0,.4) 87%,rgba(0,0,0,.15) 93%,rgba(0,0,0,.04) 97%,transparent 100%),linear-gradient(180deg,transparent 0%,rgba(0,0,0,.15) 5%,rgba(0,0,0,.5) 10%,rgba(0,0,0,.85) 16%,#000 22%,#000 76%,rgba(0,0,0,.8) 84%,rgba(0,0,0,.4) 92%,transparent 100%); mask-composite:intersect; }
  /* blur laid OVER the image edges */
  #hs-hero::after{ content:""; position:absolute; z-index:1; top:0; bottom:0; left:0; right:0; margin:0 auto; pointer-events:none;
    width:calc(var(--evW) + 80px); max-width:100%;
