    mask-image:linear-gradient(90deg,#000 0%,rgba(0,0,0,.85) 6%,rgba(0,0,0,.55) 12%,rgba(0,0,0,.25) 19%,rgba(0,0,0,.06) 26%,transparent 32%,transparent 68%,rgba(0,0,0,.06) 74%,rgba(0,0,0,.25) 81%,rgba(0,0,0,.55) 88%,rgba(0,0,0,.85) 94%,#000 100%),linear-gradient(180deg,#000 0%,rgba(0,0,0,.7) 6%,rgba(0,0,0,.3) 13%,rgba(0,0,0,.06) 20%,transparent 26%,transparent 74%,rgba(0,0,0,.08) 82%,rgba(0,0,0,.35) 90%,#000 100%); mask-composite:add; }
  #hs-hero .sh{ z-index:2; background:
      linear-gradient(90deg,#000 0%,rgba(0,0,0,.88) 12%,rgba(0,0,0,.5) 26%,rgba(0,0,0,.1) 38%,transparent 46%,transparent 54%,rgba(0,0,0,.1) 62%,rgba(0,0,0,.5) 74%,rgba(0,0,0,.88) 88%,#000 100%),
      linear-gradient(0deg,rgba(0,0,0,.9) 0%,rgba(0,0,0,.35) 24%,transparent 48%) !important; }
