/* ev-perf */

/* PERF: no GPU-heavy blur-behind effects; backgrounds are already translucent */
*,*::before,*::after{-webkit-backdrop-filter:none !important;backdrop-filter:none !important;}
/* PERF: stop decorative always-on animations that force constant repaints */
body::before,.mws-bg,.live-shimmer,.sx-glow,[class*="shimmer"]{animation:none !important;}
.nav-live-btn,.drawer-nav .drawer-live,[class*="movies-glow"]{animation:none !important;}
/* PERF: skip layout/paint of off-screen rows and cards */
.sxs-sec,.sxs-gsec,.hs-gsec{content-visibility:auto;contain-intrinsic-size:auto 230px;}
.sxs-card,.channel-card{contain:layout paint style;}
/* PERF: lighter scrolling */
.sxs-track{-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.001s !important;animation-iteration-count:1 !important;transition-duration:.001s !important;}}

