/* sx-smooth-slider */

/* ═════ SX SMOOTH CARD SLIDER — Live / Movies / TV Shows / Sports rails ═════ */
.sxs-track,.hsm-track,.mws-more-row,#ev-pop-slider .evp-track{ -webkit-overflow-scrolling:touch; overscroll-behavior-x:contain; scroll-behavior:auto; }
/* while a rail is moving, cards ignore touches → no accidental opens, no hover/tap flicker */
.sx-scrolling > *{ pointer-events:none; }

@media(max-width:900px){
  /* one card at a time snap, finger-flick momentum, peek of the next card */
  #sxs-home .sxs-track,#sxs-live .sxs-track,#sxs-root .sxs-track,.hsm-track,#ev-pop-slider .evp-track{
    scroll-snap-type:x mandatory; scroll-padding-left:12px; scroll-padding-right:12px; }
  .fixtures-grid{ scroll-snap-type:x mandatory !important; scroll-padding-left:16px; scroll-padding-right:16px; overscroll-behavior-x:contain; }
  .sxs-card,.sxs-tile,.hsm-card,#ev-pop-slider .evp-chip,.fixtures-grid > *{ scroll-snap-align:start; scroll-snap-stop:normal; }

  /* quick press feedback instead of the slow .38s / .6s hover transitions */
  .sxs-card{ transition:transform .12s ease !important; -webkit-tap-highlight-color:transparent; }
  .sxs-th{ transition:transform .14s ease !important; }
  .sxs-card:active .sxs-th{ transform:scale(.97); }

  /* desktop arrow buttons never belong on a touch rail */
  .sxs-btn{ display:none !important; }
}
/* touch screens: sticky :hover after a tap must not scale cards */
@media(hover:none){
  .sxs-card:hover .sxs-th,.sxs-card:focus-visible .sxs-th{ transform:none; box-shadow:none; }
  .hsm-card:hover,.fixture-card:hover,.channel-card:hover,.smo-card:hover,.fcx-card:hover{ transform:none !important; box-shadow:none !important; }
}


/* rf-theme */

/* ══════════════════════════════════════════════════════════════
   RISHI FORGE THEME — matches saptarshi-samanta.html
   Unbounded display + Figtree body · black / white / electric purple
   pill buttons · hairline borders · soft panels · smooth motion
   (colour-only layer: no layout, sizing or JS behaviour is changed)
══════════════════════════════════════════════════════════════ */
:root{
  --rf-bg:#000;--rf-fg:#f5f5fa;--rf-mute:#9a9aae;--rf-line:#24232f;--rf-line2:rgba(255,255,255,.10);
  --rf-accent:#9d6bff;--rf-accent2:#6d28ff;--rf-ink:#000;--rf-panel:#0d0c14;--rf-panel2:#141322;
  --rf-disp:"Unbounded","Arial Black",system-ui,sans-serif;
  --rf-body:"Figtree",system-ui,-apple-system,"Segoe UI",sans-serif;
  --rf-ease:cubic-bezier(.2,.8,.2,1);
  --gold:#9d6bff;--gold-light:#c4a5ff;--gold-dark:#6d28ff;--diamond:#9d6bff;--diamond-light:#c4a5ff;--diamond-dark:#1a0f33;
  --live-red:#9d6bff;--red-live:#9d6bff;--blue:#9d6bff;--indigo:#9d6bff;--violet:#6d28ff;--lavender:#c4a5ff;--ice:#c4a5ff;
  --yellow:#c4a5ff;--yellow-dark:#6d28ff;--cyan:#9d6bff;--cyan-dark:#1a0f33;
  --grad-brand:#9d6bff;--grad-brand-h:#9d6bff;--grad-magenta:#9d6bff;--grad-gold:#9d6bff;--grad-gold-h:#9d6bff;--grad-diamond:#9d6bff;
  --logo-grad:#9d6bff;--logo-grad-rev:#9d6bff;--logo-grad-h:#9d6bff;
  --font-display:var(--rf-disp);--font-body:var(--rf-body);
  --cu-accent:#9d6bff;--cu-accent-light:#c4a5ff;--cu-panel:#0d0c14;--cu-panel-2:#141322;--cu-line:rgba(255,255,255,.10);--cu-font:var(--rf-body);
  --hs-r:16px;--hs-blue:#9d6bff;--hs-grad:linear-gradient(90deg,#9d6bff,#6d28ff);
  --pm-magenta:#9d6bff;--pm-magenta-hover:#c4a5ff;--pm-magenta-dim:rgba(157,107,255,.16);--pm-magenta-dim-2:rgba(157,107,255,.30);--pm-magenta-text:#c4a5ff;
  --pm-surface-1:#0d0c14;--pm-surface-2:#141322;--pm-surface-3:#1a1830;--pm-border:rgba(255,255,255,.10);
  --pm-radius-sm:10px;--pm-radius-md:14px;--pm-radius-lg:20px;--pm-font:var(--rf-body);
  --mg:linear-gradient(135deg,#6d28ff,#9d6bff);
  --glow-indigo:rgba(157,107,255,.30);--glow-magenta:rgba(157,107,255,.28);--glow-gold:rgba(109,40,255,.40);--glow-diamond:rgba(157,107,255,.34);
  --purple-glow:0 0 40px rgba(157,107,255,.35);
}
html{scroll-behavior:smooth;scroll-padding-top:84px;-webkit-text-size-adjust:100%}
body{font-family:var(--rf-body) !important;font-size:16px;background:#000 !important;color:var(--rf-fg);text-rendering:optimizeLegibility;animation:rfFade .6s ease both}
@keyframes rfFade{from{opacity:0}to{opacity:1}}
button,input,select,textarea{font-family:var(--rf-body) !important}
::selection{background:var(--rf-accent);color:#000}
:focus-visible{outline:2px solid var(--rf-accent) !important;outline-offset:3px;border-radius:6px}
*{scrollbar-color:#2d2b3d transparent;scrollbar-width:thin}
::-webkit-scrollbar{width:10px;height:10px}::-webkit-scrollbar-thumb{background:#2d2b3d;border-radius:99px;border:2px solid #000}::-webkit-scrollbar-thumb:hover{background:var(--rf-accent)}::-webkit-scrollbar-track{background:transparent}

/* ambient glow: soft purple, no pink */
body::before{background:
  radial-gradient(ellipse 70% 45% at 15% 0%,rgba(157,107,255,.10),transparent 65%),
  radial-gradient(ellipse 55% 40% at 90% 85%,rgba(109,40,255,.10),transparent 60%) !important}
body::after{opacity:.02 !important}

/* ── titles: Unbounded ── */
.section-title,.sxs-sec-h,.slide-title,.cta-title,.discord-title,.whatsapp-title,.footer-vip-title,.mws-right-title,
.hsc-title,.hero-title,.smo-section-label,.drawer-header,.footer-brand p,.cat-name{font-family:var(--rf-disp) !important;letter-spacing:-.02em !important;font-weight:800 !important}
.section-title{font-size:clamp(20px,3.4vw,30px) !important;text-transform:none !important;letter-spacing:-.025em !important}
.sxs-sec-h{font-size:12px !important;font-weight:600 !important;letter-spacing:.04em !important;text-transform:none !important;color:var(--rf-fg) !important}
.sxs-sec-h em{font-family:var(--rf-body);font-style:normal;color:var(--rf-mute);font-weight:500}
.channel-name,.team-name,.fixture-team-name,.smo-name,.ch-name,.cat-name{font-family:var(--rf-body) !important;font-weight:700 !important;letter-spacing:-.005em !important}

/* ── wordmark ── */
.evw .evw-a{color:var(--rf-fg) !important}.evw .evw-b{color:var(--rf-accent) !important}
#cms-loader .ldr-st{color:var(--rf-accent) !important}
html #cms-loader{--l-accent:#9d6bff;--l-glow:rgba(157,107,255,.18)}

/* ── header: floating capsule, hairline border ── */
header{background:rgba(0,0,0,.72) !important;border:1px solid var(--rf-line2) !important;backdrop-filter:blur(14px) saturate(1.4) !important;-webkit-backdrop-filter:blur(14px) saturate(1.4) !important;box-shadow:0 10px 30px rgba(0,0,0,.45) !important;transition:background .3s,border-color .3s,box-shadow .3s}
header.scrolled{background:rgba(0,0,0,.88) !important;border-color:var(--rf-line) !important}
.nav-links-desktop a,.pcqn-item{font-family:var(--rf-body) !important;font-weight:600 !important;color:var(--rf-mute) !important;border-radius:999px !important;transition:color .2s,background .2s,transform .2s var(--rf-ease) !important}
.nav-links-desktop a:hover,.pcqn-item:hover{color:var(--rf-fg) !important;background:rgba(255,255,255,.06) !important}
.nav-links-desktop a.active,.pcqn-item.active{color:var(--rf-accent) !important;background:rgba(157,107,255,.12) !important}
.pcqn-dot,.live-dot-r,.ch-live-dot{background:var(--rf-accent) !important}

/* ── buttons: pill, flat, lift on hover ── */
.btn-get-vip-nav,.btn-discord,.btn-telegram,.btn-watch-sm,.btn-slide-watch,.btn-slide-outline,.hsc-btn-watch,.hsc-btn-outline,
.cta-btn-primary,.cta-btn-outline,.bc-watch-btn,.wcs-btn,.btn-get-vip,.btn-join-discord-footer,.discord-join-btn,.whatsapp-join-btn,
.qr-open-btn,.btn-3d-gold,.btn-diamond-glow,.btn-yt,.nav-watch-btn,.smo-btn,.mws-server-btn{
  font-family:var(--rf-body) !important;font-weight:600 !important;border-radius:999px !important;
  transition:transform .2s var(--rf-ease),background .2s,border-color .2s,color .2s,box-shadow .2s,filter .2s !important;
  text-shadow:none !important}
.btn-get-vip-nav,.btn-watch-sm,.btn-slide-watch,.hsc-btn-watch,.cta-btn-primary,.bc-watch-btn,.btn-get-vip,.discord-join-btn,.whatsapp-join-btn,.qr-open-btn,.btn-3d-gold,.nav-watch-btn{
  background:var(--rf-accent) !important;color:#000 !important;border:1px solid var(--rf-accent) !important;box-shadow:none !important}
