.ch-card:hover,.channel-card:hover,.cat-card:hover,.fixture-card:hover,.match-row:hover,.smo-card:hover,.ott-card:hover,.broadcast-card:hover,.fpx-card:hover,.wt20-card:hover,.mws-more-card:hover{
  transform:translateY(-3px) !important;border-color:var(--rf-accent) !important;background:var(--rf-panel2) !important;box-shadow:0 14px 34px rgba(0,0,0,.5),0 0 0 1px rgba(157,107,255,.18) !important}
.ch-card.star-card,.ch-card.sony-card,.ch-card.fox-card,.ch-card.fancode-card,.ch-card.unite8-card,.ch-card.intl-card,.ch-card.zee-card,.ch-card.news-card,.ch-card.fifa-card{background:var(--rf-panel) !important}
.is-live-channel{border-color:rgba(157,107,255,.55) !important}
.cta-box,.footer-vip{background:var(--rf-panel) !important;border-radius:22px !important}
.sxs-th,.sxs-card img,.hero-slide-card,.slide,.mws-bg,.sk{border-radius:16px;overflow:hidden}
.sxs-card{transition:transform .3s var(--rf-ease) !important}
