.channel-icon-wrap,.ch-logo-wrap{border-radius:14px !important}

/* badges & chips */
.quality-badge,.smo-live-badge,.smo-upcoming-badge,.live-pill,.match-live-tag,.hsc-live-badge,.slide-sport-badge,.mws-badge-row>*{font-family:var(--rf-body) !important;font-weight:700 !important;border-radius:999px !important;letter-spacing:.03em}
.smo-live-badge,.live-pill,.match-live-tag,.hsc-live-badge{background:var(--rf-accent) !important;color:#000 !important;border-color:transparent !important}

/* search / inputs */
.ch-search-box,#sx-search-input,input[type=search],input[type=text]{border-radius:999px !important;background:var(--rf-panel) !important;border:1px solid var(--rf-line2) !important;color:var(--rf-fg) !important;transition:border-color .2s,box-shadow .2s}
.ch-search-box:focus-within,#sx-search-input:focus,input[type=search]:focus,input[type=text]:focus{border-color:var(--rf-accent) !important;box-shadow:0 0 0 3px rgba(157,107,255,.18) !important;outline:0 !important}

/* hero dots / progress */
.hero-card-dots .dot,.dot{background:rgba(255,255,255,.25) !important;transition:all .3s var(--rf-ease) !important}
.hero-card-dots .dot.active,.dot.active{background:var(--rf-accent) !important}

/* ── side rail / drawer / tab bar ── */
#hs-rail,#hsm-bar,.side-drawer,.mobile-tabbar{background:#000 !important}
.side-drawer{border-right:1px solid var(--rf-line) !important}
.drawer-nav a{font-family:var(--rf-body) !important;font-weight:600 !important;transition:color .2s,background .2s,padding .25s var(--rf-ease) !important}
.drawer-nav a:hover,.drawer-nav a.active{color:var(--rf-accent) !important;background:rgba(157,107,255,.08) !important}
.mobile-tabbar{border-top:1px solid var(--rf-line) !important;backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.mtab{transition:color .2s,transform .2s var(--rf-ease) !important}
.mtab.active{color:var(--rf-accent) !important}
.mtab:active{transform:scale(.92)}
.hamburger span{background:var(--rf-fg) !important}

/* ── overlays / modals ── */
.watch-overlay,.mws-overlay,.drawer-overlay{backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.watch-modal,.mws-panel{border-radius:22px !important}
.mws-server-btn{background:var(--rf-panel2) !important;border:1px solid var(--rf-line2) !important}
.mws-server-btn:hover{border-color:var(--rf-accent) !important;background:rgba(157,107,255,.10) !important}

/* ── footer ── */
footer{background:#000 !important;border-top:1px solid var(--rf-line) !important}
.footer-nav a,.footer-legal a{color:var(--rf-mute) !important;transition:color .2s}
.footer-nav a:hover,.footer-legal a:hover{color:var(--rf-accent) !important}
.footer-disclaimer,.footer-copy{color:var(--rf-mute) !important;font-size:13px}

/* links */
a{transition:color .2s}

/* ── reduced motion ── */
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}body{animation:none}
  *,*::before,*::after{transition-duration:.01ms !important;animation-duration:.01ms !important;animation-iteration-count:1 !important}
}

/* ══════════════ SMOOTH + MINIMAL LAYER ══════════════
   quieter surfaces, no decorative glow/shimmer, one easing curve,
   compositor-only hover motion, lazy section rendering */
:root{--rf-line2:rgba(255,255,255,.07);--rf-panel:#0a0a10;--rf-panel2:#101018;--rf-t:.35s var(--rf-ease)}
html{overscroll-behavior-y:none;-webkit-tap-highlight-color:transparent}
body{overflow-x:hidden;font-weight:400;line-height:1.6}
a,button,[role=button],.ch-card,.channel-card,.cat-card,.fixture-card,.smo-card,.ott-card,.mtab{touch-action:manipulation;-webkit-tap-highlight-color:transparent}

/* remove decorative noise: ambient glow, shimmer sweeps, text/box glows */
body::before,body::after,.mws-bg,.live-shimmer,.sx-glow,.sp-rail-viewall::before,[class*="shimmer"]:not(.mh-sk):not(.sk){display:none !important;animation:none !important}
*{text-shadow:none !important}
.live-dot,.live-dot-r,.ch-live-dot,.chp-live-dot,.fpx-dot,.fpx-live-dot,.discord-online-dot,.whatsapp-online-dot,.chip .dot,#golive .dot{box-shadow:none !important}
[class*="glow"]:not(svg):not(path){box-shadow:none !important;filter:none !important}
.btn-get-vip-nav,.btn-watch-sm,.btn-slide-watch,.hsc-btn-watch,.cta-btn-primary,.bc-watch-btn,.btn-get-vip,.discord-join-btn,.whatsapp-join-btn,.qr-open-btn,.btn-3d-gold,.nav-watch-btn{box-shadow:none !important}

/* calm typography */
.section-title{font-weight:700 !important}
.sxs-sec-h,.mws-right-eyebrow,.smo-section-label{text-transform:none !important;letter-spacing:.01em !important;font-weight:600 !important}
.cta-title,.discord-title,.whatsapp-title,.footer-vip-title{font-weight:700 !important}
p,.footer-disclaimer{color:var(--rf-mute)}

/* generous, even rhythm */
section{padding-top:clamp(28px,5vw,56px);padding-bottom:clamp(8px,2vw,16px)}
.channels-grid,.ch-grid,.fixtures-grid,.categories-grid,.ott-grid,.chp-grid,.broadcast-grid{gap:clamp(10px,1.6vw,18px) !important}

/* surfaces: flatter, hairline, no inner gradients */
.ch-card,.channel-card,.cat-card,.fixture-card,.match-row,.smo-card,.ott-card,.broadcast-card,.whatsapp-card,.discord-card,.cta-box,.fpx-card,.wt20-card,.mws-panel,.footer-vip,.watch-modal,.mws-more-card{
  background:var(--rf-panel) !important;background-image:none !important;border:1px solid var(--rf-line2) !important;border-radius:16px !important;box-shadow:none !important;
  transition:transform var(--rf-t),border-color var(--rf-t),background-color var(--rf-t) !important;will-change:auto}
.fixture-header,.watch-modal-header{background:transparent !important}
.ch-card:hover,.channel-card:hover,.cat-card:hover,.fixture-card:hover,.match-row:hover,.smo-card:hover,.ott-card:hover,.broadcast-card:hover,.fpx-card:hover,.wt20-card:hover,.mws-more-card:hover{
  transform:translate3d(0,-2px,0) !important;box-shadow:none !important;border-color:rgba(157,107,255,.45) !important}
@media (hover:none){.ch-card:hover,.channel-card:hover,.cat-card:hover,.fixture-card:hover,.smo-card:hover,.ott-card:hover{transform:none !important}}
.ch-card:active,.channel-card:active,.cat-card:active,.fixture-card:active,.smo-card:active,.ott-card:active{transform:scale(.985) !important;transition-duration:.12s !important}
.btn-get-vip-nav:hover,.btn-watch-sm:hover,.btn-slide-watch:hover,.hsc-btn-watch:hover,.cta-btn-primary:hover,.bc-watch-btn:hover,.btn-get-vip:hover,.discord-join-btn:hover,.whatsapp-join-btn:hover,.qr-open-btn:hover,.btn-3d-gold:hover{box-shadow:none !important;transform:translate3d(0,-1px,0) !important}

/* header: lighter blur = smoother scroll */
header{box-shadow:none !important;backdrop-filter:blur(10px) !important;-webkit-backdrop-filter:blur(10px) !important;border-color:var(--rf-line2) !important}
.mobile-tabbar{backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
.watch-overlay,.mws-overlay,.drawer-overlay{backdrop-filter:none;-webkit-backdrop-filter:none;background:rgba(0,0,0,.78) !important}
.watch-modal,.mws-panel{border-radius:20px !important}

/* images fade in, no layout jump */
img{image-rendering:auto}
img[loading=lazy]{opacity:0;transition:opacity .5s ease}
img[loading=lazy].loaded,img[loading=lazy][data-ok]{opacity:1}
.ch-card img,.channel-card img,.cat-card img{transition:transform .5s var(--rf-ease)}

/* horizontal rails: momentum + clean edges */
.schedule-tabs,.ch-tabs,.smo-sport-tabs,.mws-more-row,.hero-cards-track,[class*="rail"],[class*="-row"][style*="overflow"]{scroll-behavior:smooth;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;scrollbar-width:none}
.schedule-tabs::-webkit-scrollbar,.ch-tabs::-webkit-scrollbar,.smo-sport-tabs::-webkit-scrollbar,.mws-more-row::-webkit-scrollbar{display:none}

/* thinner scrollbar */
::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-thumb{border:0;background:#26252f}

/* lazy-render off-screen sections for smoother scroll */
#ch-browser,footer,.footer-vip{content-visibility:auto;contain-intrinsic-size:auto 600px}

/* ── borderless cards ── */
.ch-card,.channel-card,.cat-card,.fixture-card,.match-row,.smo-card,.ott-card,.broadcast-card,.whatsapp-card,.discord-card,.cta-box,.fpx-card,.wt20-card,.mws-panel,.footer-vip,.watch-modal,.mws-more-card,.hero-slide-card,.sxs-card,.chp-card,.cat-card-preview,.mws-server-btn,.is-live-channel{border:0 !important;outline:0}
.ch-card:hover,.channel-card:hover,.cat-card:hover,.fixture-card:hover,.match-row:hover,.smo-card:hover,.ott-card:hover,.broadcast-card:hover,.fpx-card:hover,.wt20-card:hover,.mws-more-card:hover,.mws-server-btn:hover{border:0 !important;background:var(--rf-panel2) !important}

/* ── loader: hide status text ("Fetching CMS data…") ── */
#cms-loader .ldr-msg,#ldr-msg{position:absolute !important;width:1px !important;height:1px !important;overflow:hidden !important;clip:rect(0 0 0 0) !important;opacity:0 !important;margin:0 !important;padding:0 !important}
/* ── borderless rectangular cards (catch-all, incl. dynamically rendered) ── */
[class*="card"]:not([class*="btn"]):not([class*="dot"]):not(.th),[class*="-tile"],[class*="tile-"],.match-row,.mws-server-btn,.watch-modal,.mws-panel,.footer-vip,.cta-box,.smo-game-tab,.sxs-th,.fx2-card,.fx2-card *,.ch-card *,.channel-card *,.cat-card *,.fixture-card *,.smo-card *:not(button){
  border-color:transparent !important;box-shadow:none !important;outline:0 !important}
[class*="card"]:not([class*="btn"]):not([class*="dot"]):not(.th):hover,.match-row:hover,.mws-server-btn:hover{border-color:transparent !important;box-shadow:none !important}
.fixture-header,.fixture-card [class*="header"],.fixture-card [class*="footer"]{border-color:transparent !important}

/* page reveal: single soft fade */
body{animation:rfFade .45s ease both}


/* evdl-css */

#evdl{position:fixed;inset:0;z-index:99990;background:#000;color:var(--rf-fg,#f5f5fa);font-family:var(--rf-body,'Satoshi',system-ui,sans-serif);overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;opacity:0;visibility:hidden;transform:translate3d(0,14px,0);transition:opacity .35s var(--rf-ease,ease),transform .35s var(--rf-ease,ease),visibility 0s .35s;scroll-behavior:smooth}
#evdl.open{opacity:1;visibility:visible;transform:none;transition:opacity .35s var(--rf-ease,ease),transform .35s var(--rf-ease,ease)}
#evdl *{box-sizing:border-box}
#evdl .w{max-width:1000px;margin:0 auto;padding:0 clamp(16px,4vw,28px)}
#evdl .bar{position:sticky;top:0;z-index:2;background:rgba(0,0,0,.8);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
#evdl .bar .w{display:flex;align-items:center;justify-content:space-between;height:60px}
#evdl .brand{display:flex;align-items:center;gap:10px;font:800 15px var(--rf-disp,'Satoshi',sans-serif);letter-spacing:-.02em}
#evdl .brand img{width:28px;height:28px;object-fit:contain}
#evdl .brand b{color:#9d6bff}
#evdl .x{width:38px;height:38px;border-radius:50%;border:0;background:#101018;color:#fff;font-size:18px;cursor:pointer;display:grid;place-items:center;transition:background .25s,transform .25s var(--rf-ease,ease)}
#evdl .x:hover{background:#1a1830;transform:rotate(90deg)}
#evdl .hero{text-align:center;padding:clamp(36px,7vw,80px) 0 36px}
#evdl .hero img{width:clamp(76px,16vw,104px);height:auto;margin:0 auto 22px;display:block}
#evdl h1{font:800 clamp(30px,7vw,60px)/1.02 var(--rf-disp,'Satoshi',sans-serif);letter-spacing:-.035em;margin:0}
#evdl h1 em{font-style:normal;color:#9d6bff}
#evdl .lede{max-width:500px;margin:18px auto 0;color:#9a9aae;font-size:clamp(15px,2.4vw,18px);line-height:1.6}
#evdl .stats{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;list-style:none;margin:26px 0 0;padding:0}
#evdl .stats li{background:#0a0a10;border-radius:16px;padding:12px 20px;min-width:140px}
#evdl .stats b{display:block;font:800 clamp(18px,4vw,24px)/1.1 var(--rf-disp,'Satoshi',sans-serif);color:#9d6bff;letter-spacing:-.02em}
#evdl .stats span{font-size:13px;color:#9a9aae}
#evdl .det{margin:22px 0 0;color:#9a9aae;font-size:14px}#evdl .det b{color:#fff}
#evdl .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;padding-bottom:56px}
@media(max-width:720px){#evdl .grid{grid-template-columns:1fr}}
#evdl .c{position:relative;background:#0a0a10;border-radius:20px;padding:clamp(20px,3.4vw,30px);display:flex;flex-direction:column;transition:background .3s,transform .3s var(--rf-ease,ease)}
#evdl .c:hover{background:#101018;transform:translate3d(0,-2px,0)}
#evdl .c.rec{order:-1;background:linear-gradient(180deg,rgba(157,107,255,.16),#0a0a10 70%)}
#evdl .c.rec::after{content:"Recommended for you";position:absolute;top:18px;right:18px;background:#9d6bff;color:#000;font:700 11px var(--rf-body,sans-serif);padding:4px 12px;border-radius:999px}
#evdl .ic{width:46px;height:46px;border-radius:14px;background:#000;display:inline-grid;place-items:center;gap:6px;color:#9d6bff}
