/* sx-theme-css */

/* THEME SWITCH — toggle button + dark-mode helpers (this block is never disabled) */
#sx-theme-toggle{
  all:unset; box-sizing:border-box; cursor:pointer; flex-shrink:0;
  width:40px; height:40px; border-radius:50%;
  display:inline-flex !important; align-items:center; justify-content:center;
  position:relative; overflow:hidden;
  transition:background-color .25s ease,border-color .25s ease,color .25s ease,transform .2s ease !important;
  -webkit-tap-highlight-color:transparent;
}
#sx-theme-toggle:active{ transform:scale(.92); }
#sx-theme-toggle:focus-visible{ outline:2px solid #2F93E8; outline-offset:3px; }
#sx-theme-toggle svg{ position:absolute; transition:transform .45s cubic-bezier(.22,1,.36,1),opacity .3s ease; }
/* light theme (current look): ink icon on pearl */
