/* ev-search-polish */

/* ===== EV Search bar polish (final override) ===== */
html:root:root body #sx-search-overlay{
  --sb-bg:#ffffff; --sb-bg-hover:#f7f8fa; --sb-line:rgba(20,22,27,.10); --sb-line-strong:rgba(20,22,27,.22);
  --sb-text:#14161B; --sb-muted:#8a90a0; --sb-accent:#2f8fe8; --sb-accent-soft:rgba(47,143,232,.16);
  --sb-chip-bg:#f1f3f7; --sb-chip-text:#4a5060; --sb-shadow:0 6px 24px rgba(20,22,27,.08),0 1px 2px rgba(20,22,27,.06);
}
html[data-theme="dark"]:root:root body #sx-search-overlay{
  --sb-bg:#14161C; --sb-bg-hover:#1a1d25; --sb-line:rgba(255,255,255,.10); --sb-line-strong:rgba(255,255,255,.26);
  --sb-text:#F2F4F8; --sb-muted:#7d8496; --sb-accent:#4aa3ff; --sb-accent-soft:rgba(74,163,255,.22);
  --sb-chip-bg:rgba(255,255,255,.06); --sb-chip-text:#b9bfcc; --sb-shadow:0 8px 28px rgba(0,0,0,.45);
}
html:root:root body #sx-search-overlay .sx-search-topline{gap:14px;}
html:root:root body #sx-search-overlay .sx-search-bar{
  height:60px; padding:0 10px 0 22px; gap:12px; border-radius:999px !important;
  background:var(--sb-bg) !important; border:1px solid var(--sb-line) !important;
  box-shadow:var(--sb-shadow); color:var(--sb-muted) !important;
  transition:border-color .18s, box-shadow .18s, transform .18s;
}
html:root:root body #sx-search-overlay .sx-search-bar:hover{border-color:var(--sb-line-strong) !important;}
html:root:root body #sx-search-overlay .sx-search-bar:focus-within{
  border-color:var(--sb-accent) !important;
  box-shadow:0 0 0 4px var(--sb-accent-soft), var(--sb-shadow) !important;
}
html:root:root body #sx-search-overlay .sx-search-bar>svg{width:21px;height:21px;flex:0 0 21px;opacity:.7;color:var(--sb-muted) !important;transition:color .18s,opacity .18s;}
html:root:root body #sx-search-overlay .sx-search-bar:focus-within>svg{color:var(--sb-accent) !important;opacity:1;}
html:root:root body #sx-search-overlay .sx-search-bar input,
html:root:root body #sx-search-overlay .sx-search-bar input:focus{
  background:transparent !important; box-shadow:none !important; border:0 !important; outline:0 !important;
  color:var(--sb-text) !important; -webkit-text-fill-color:var(--sb-text) !important; caret-color:var(--sb-accent);
  font-size:16px !important; font-weight:500; letter-spacing:.005em; height:100%;
}
html:root:root body #sx-search-overlay .sx-search-bar input::placeholder{
  color:var(--sb-muted) !important; -webkit-text-fill-color:var(--sb-muted) !important; font-weight:400;
}
/* clear button */
html:root:root body #sx-search-overlay .sx-search-clear{
  width:30px; height:30px; border-radius:50%; background:var(--sb-chip-bg) !important; color:var(--sb-chip-text) !important; transition:background .15s;
}
html:root:root body #sx-search-overlay .sx-search-clear:hover{background:var(--sb-line-strong) !important;}
/* mic */
html:root:root body #sx-search-overlay .sx-search-bar .ev-mic{
  width:42px; height:42px; flex:0 0 42px; border-radius:50% !important; border:0; color:var(--sb-chip-text);
  background:var(--sb-chip-bg) !important; transition:background .15s,color .15s,transform .15s;
}
html:root:root body #sx-search-overlay .sx-search-bar .ev-mic:hover{background:var(--sb-accent) !important;color:#fff;transform:scale(1.05);}
html:root:root body #sx-search-overlay .sx-search-bar .ev-mic.listening{background:#e5116f !important;color:#fff;}
/* language chip */
html:root:root body #sx-search-overlay .sx-search-bar .ev-lang{
  height:32px; padding:0 12px; border-radius:999px !important; border:1px solid var(--sb-line) !important;
  color:var(--sb-chip-text) !important; background:transparent !important; font-size:11px; font-weight:700;
}
html:root:root body #sx-search-overlay .sx-search-bar .ev-lang:hover{border-color:var(--sb-accent) !important;color:var(--sb-accent) !important;}
/* close */
html:root:root body #sx-search-overlay .sx-search-cancel{
  height:60px; padding:0 28px; border-radius:999px !important; background:var(--sb-bg) !important;
  border:1px solid var(--sb-line) !important; color:var(--sb-text) !important; box-shadow:var(--sb-shadow);
  font-weight:700; letter-spacing:.1em; transition:all .18s;
}
html:root:root body #sx-search-overlay .sx-search-cancel:hover{background:var(--sb-text) !important;color:var(--sb-bg) !important;border-color:var(--sb-text) !important;}
/* filter chips */
html:root:root body #sx-search-overlay .sx-search-chips{gap:10px;margin-top:16px;padding:2px 2px 6px;}
html:root:root body #sx-search-overlay .sx-chip{
  height:38px; padding:0 18px; border-radius:999px !important; background:var(--sb-chip-bg) !important;
  border:1px solid transparent !important; color:var(--sb-chip-text) !important; letter-spacing:.07em; font-weight:700;
  transition:background .15s,color .15s,transform .15s,box-shadow .15s;
}
html:root:root body #sx-search-overlay .sx-chip:hover{background:var(--sb-accent-soft) !important;color:var(--sb-accent) !important;border-color:transparent !important;transform:translateY(-1px);}
html:root:root body #sx-search-overlay .sx-chip.active{
  background:var(--sb-accent) !important; color:#fff !important; border-color:var(--sb-accent) !important;
  box-shadow:0 4px 14px var(--sb-accent-soft);
}
/* language dropdown aligns with new radius */
html:root:root body #ev-lang-panel{top:72px;border-radius:18px;}
@media(max-width:900px){
  html:root:root body #sx-search-overlay .sx-search-bar{height:52px;padding:0 8px 0 16px;}
  html:root:root body #sx-search-overlay .sx-search-bar .ev-mic{width:36px;height:36px;flex-basis:36px;}
  html:root:root body #sx-search-overlay .sx-search-cancel{height:52px;padding:0 18px;}
  html:root:root body #sx-search-overlay .sx-chip{height:34px;padding:0 14px;}
  html:root:root body #ev-lang-panel{top:62px;}
}

