/* ev-playhtml-quality */

/* narrow quality switcher (play.html style): small popover under the Quality button, ticks on the right */
html body #stream-player-overlay #stream-player-infobar>#sp-quality-menu{
  width:176px !important;max-width:calc(100vw - 16px) !important;left:auto !important;right:12px !important;
  padding:4px !important;border-radius:12px !important;background:rgba(20,20,24,.96) !important;border:1px solid rgba(255,255,255,.1) !important;box-shadow:none !important;}
#sp-quality-menu .sp-sv-h{padding:10px 12px 6px !important;font-size:12px !important;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.5) !important;}
#sp-quality-menu .sp-sv-item{flex-direction:row-reverse;justify-content:space-between;padding:9px 10px !important;font-size:14px !important;font-weight:500;border-radius:8px !important;}
#sp-quality-menu .sp-sv-item.on{font-weight:700;}
#sp-quality-menu .sp-sv-item .mk{margin:0 !important;width:auto !important;color:#1f80ff;}
#sp-quality-menu .sp-sv-item .nm{flex:1;min-width:0;}
#sp-quality-menu .sp-sv-item small{display:none !important;}
#sp-quality-menu .sp-sv-report{padding:9px 10px !important;font-size:14px !important;}
#sp-quality-menu .sp-sv-sep{margin:3px 6px !important;}
/* on phones the player has its own Quality button (top-right, like play.html) */
@media(max-width:900px),(pointer:coarse){html body #stream-player-overlay #sp-quality-wrap{display:none !important;}}
#ev-embed-help{display:none !important;}


/* ===== EVORA brand (logo images; replaces the old mask-based wordmark) ===== */
:root{ --ev-lockup:url(evora-lockup.png); --ev-stack:url(evora-logo.png); --tg-r:4.6712; --ev-stack-r:1.5908; --ev-mag:#FF14A0; }
html:root:root body .evw{
  background:var(--ev-lockup) left center/contain no-repeat !important;
  -webkit-mask:none !important; mask:none !important;
}
html:root:root body .evw-nav{ --tg-h:26px; }
html:root:root body .evw-drawer{ --tg-h:26px; }
html:root:root body .evw-foot{ --tg-h:32px; }
html:root:root body .evw-bar{ --tg-h:26px; }
html:root:root body .evw-rail{ --tg-h:28px; }
@media (max-width:900px){ html:root:root body .evw-nav{ --tg-h:28px; } }
/* loader: full stacked logo, reveals then holds */
html:root:root body #cms-loader .ldr-word{ width:min(62vw,300px) !important; aspect-ratio:var(--ev-stack-r) !important; }
html:root:root body #cms-loader .ldr-word > .tg-ol{ display:none !important; }
html:root:root body #cms-loader .tg-fill{
  background:var(--ev-stack) center/contain no-repeat !important;
  -webkit-mask:none !important; mask:none !important;
  animation:evReveal 1s cubic-bezier(.2,.8,.2,1) .2s both, evGlow 2.4s ease-in-out 1.2s infinite !important;
}
@keyframes evReveal{ from{ clip-path:inset(0 100% 0 0); opacity:.3; } to{ clip-path:inset(0 0 0 0); opacity:1; } }
@keyframes evGlow{ 0%,100%{ filter:drop-shadow(0 0 0 rgba(255,20,160,0)); } 50%{ filter:drop-shadow(0 0 14px rgba(255,20,160,.55)); } }
/* player loader */
html:root:root body #stream-player-loading #sp-loading-spinner{
  width:min(50vw,200px) !important; aspect-ratio:var(--ev-stack-r) !important;
  background:var(--ev-stack) center/contain no-repeat !important;
  -webkit-mask:none !important; mask:none !important;
  animation:evGlow 2s ease-in-out infinite !important;
}
@media (prefers-reduced-motion:reduce){
  html:root:root body #cms-loader .tg-fill,html:root:root body #stream-player-loading #sp-loading-spinner{ animation:none !important; clip-path:none !important; }
}

/* ===== EVORA sidebar logo: same mark both states (larger), bold coloured name when expanded ===== */
html:root:root:root:root:root body #hs-rail .in .logo .evw{ display:none !important; }
html:root:root:root:root:root body #hs-rail .in .logo{ padding-left:9px !important; gap:10px; height:44px !important; align-items:center !important; }
html:root:root:root:root:root body #hs-rail .in .logo .rail-logo-img,
html:root:root:root:root:root body #hs-rail:hover .in .logo .rail-logo-img,
html:root:root:root:root:root body #hs-rail:hover .in .logo img{
  display:block !important; width:38px !important; height:auto !important; max-height:30px; flex:0 0 38px !important; object-fit:contain !important; filter:none !important;
}
html:root:root:root:root:root body #hs-rail .in .logo::after{
  content:"EVORA"; display:none; font:800 19px/1 "Unbounded","Poppins","Arial Black",system-ui,sans-serif; letter-spacing:.05em;
  color:#FF14A0; text-shadow:0 0 14px rgba(255,20,160,.35); white-space:nowrap;
}
html:root:root:root:root:root body #hs-rail:hover .in .logo::after{ display:block; animation:tgFade .35s ease both; }
